#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct LocalBindingMetadata {
    declaration: Span,
    use_span: Span,
    value_index: usize,
}

#[derive(Clone, Debug)]
struct TypedStatementLocal {
    declaration: Span,
    pointer: ValueId,
    mutable: bool,
}

/// Malformed or truncated canonical stage-2 capture.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Stage2CaptureError {
    pub message: &'static str,
}

impl fmt::Display for Stage2CaptureError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.message)
    }
}

impl std::error::Error for Stage2CaptureError {}

/// Failure produced before an untrusted bounded stage-2 stream reaches a backend.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Stage2ImportError {
    /// A summary field is inconsistent with the complete bounded contract.
    InvalidSummary {
        field: &'static str,
        expected: u64,
        actual: u64,
    },
    /// The supplied slice is not exactly the complete emitted stream.
    RecordCount { expected: usize, actual: usize },
    /// One record violates its kind-specific ABI contract.
    InvalidRecord { index: usize, message: &'static str },
    /// One record contains a range outside the source or a non-boundary offset.
    InvalidSourceSpan { index: usize, start: u64, end: u64 },
    /// A function record does not point at a valid unique ASCII identifier.
    InvalidFunctionName { index: usize },
    /// The canonical JIR verifier rejected the constructed module.
    Verification(Vec<VerificationError>),
}

impl fmt::Display for Stage2ImportError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidSummary {
                field,
                expected,
                actual,
            } => write!(
                formatter,
                "invalid stage-2 summary field {field}: expected {expected}, got {actual}"
            ),
            Self::RecordCount { expected, actual } => write!(
                formatter,
                "invalid stage-2 record count: expected {expected}, got {actual}"
            ),
            Self::InvalidRecord { index, message } => {
                write!(formatter, "invalid stage-2 record {index}: {message}")
            }
            Self::InvalidSourceSpan { index, start, end } => write!(
                formatter,
                "invalid source span {start}..{end} in stage-2 record {index}"
            ),
            Self::InvalidFunctionName { index } => {
                write!(formatter, "invalid function name in stage-2 record {index}")
            }
            Self::Verification(errors) => write!(
                formatter,
                "imported stage-2 module failed JIR verification with {} error(s)",
                errors.len()
            ),
        }
    }
}

impl std::error::Error for Stage2ImportError {}

/// Decodes the padding-free little-endian capture written by the loaded-producer bridge.
pub fn decode_stage2_capture(bytes: &[u8]) -> Result<CapturedStage2Jir, Stage2CaptureError> {
    let mut cursor = 0usize;
    if capture_take(bytes, &mut cursor, CAPTURE_MAGIC.len())? != CAPTURE_MAGIC {
        return Err(capture_error("invalid stage-2 capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("stage-2 capture source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("stage-2 capture source is not UTF-8"))?;
    let summary = Stage2JirSummary {
        functions_seen: capture_u64(bytes, &mut cursor)?,
        statements_seen: capture_u64(bytes, &mut cursor)?,
        calls_seen: capture_u64(bytes, &mut cursor)?,
        records_required: capture_u64(bytes, &mut cursor)?,
        records_emitted: capture_u64(bytes, &mut cursor)?,
        functions_lowered: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
    };
    let record_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("stage-2 capture record count does not fit usize"))?;
    let expected_record_bytes = record_count
        .checked_mul(CAPTURE_RECORD_BYTES)
        .ok_or_else(|| capture_error("stage-2 capture record byte count overflow"))?;
    if bytes.len().saturating_sub(cursor) != expected_record_bytes {
        return Err(capture_error(
            "stage-2 capture record count does not match its remaining bytes",
        ));
    }
    let mut records = Vec::with_capacity(record_count);
    for _ in 0..record_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        records.push(Stage2JirRecord {
            kind: header[0],
            opcode: header[1],
            type_kind: header[2],
            flags: header[3],
            function_index: capture_u64(bytes, &mut cursor)?,
            block_index: capture_u64(bytes, &mut cursor)?,
            value_index: capture_u64(bytes, &mut cursor)?,
            operand_a: capture_u64(bytes, &mut cursor)?,
            operand_b: capture_u64(bytes, &mut cursor)?,
            source_start: capture_u64(bytes, &mut cursor)?,
            source_end: capture_u64(bytes, &mut cursor)?,
        });
    }
    Ok(CapturedStage2Jir {
        source,
        summary,
        records,
    })
}

/// Decodes the padding-free typed statement capture emitted by the native
/// Jadren producer loader.  The format deliberately stores every scalar
/// field in little-endian order and rejects trailing bytes or inconsistent
/// output counts before the typed lowerer is called.
pub fn decode_typed_statement_capture(
    bytes: &[u8],
) -> Result<CapturedTypedStatementSequence, Stage2CaptureError> {
    let mut cursor = 0usize;
    if capture_take(bytes, &mut cursor, TYPED_STATEMENT_CAPTURE_MAGIC.len())?
        != TYPED_STATEMENT_CAPTURE_MAGIC
    {
        return Err(capture_error("invalid typed statement capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed statement source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.statements_emitted != summary.statements_required
        || summary.ast_nodes_emitted != summary.ast_nodes_required
    {
        return Err(capture_error(
            "typed statement capture summary is incomplete or inconsistent",
        ));
    }
    let statement_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement count does not fit usize"))?;
    if statement_count as u64 != summary.statements_emitted || statement_count == 0 {
        return Err(capture_error(
            "typed statement capture statement count does not match summary",
        ));
    }
    let mut statements = Vec::with_capacity(statement_count);
    for _ in 0..statement_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        statements.push(TypedStatementHeader {
            kind: header[0],
            flags: header[1],
            type_kind: header[2],
            reserved: header[3],
            target_start: capture_u64(bytes, &mut cursor)?,
            target_end: capture_u64(bytes, &mut cursor)?,
            expression_node: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement AST count does not fit usize"))?;
    if ast_count as u64 != summary.ast_nodes_emitted || ast_count == 0 {
        return Err(capture_error(
            "typed statement capture AST count does not match summary",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error("typed statement capture has trailing bytes"));
    }
    Ok(CapturedTypedStatementSequence {
        source,
        summary,
        statements,
        ast,
    })
}

/// Decodes the padding-free `JST2WHL1` native-producer hand-off for one
/// mutable Int32 loop local. All headers are decoded field-by-field so the
/// capture never depends on host padding or Rust struct layout.
pub fn decode_typed_while_local_capture(
    bytes: &[u8],
) -> Result<CapturedTypedWhileLocal, Stage2CaptureError> {
    let mut cursor = 0usize;
    if capture_take(bytes, &mut cursor, TYPED_WHILE_LOCAL_CAPTURE_MAGIC.len())?
        != TYPED_WHILE_LOCAL_CAPTURE_MAGIC
    {
        return Err(capture_error("invalid typed while capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed while source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != 1
        || summary.statements_emitted != 1
        || summary.ast_nodes_required != 8
        || summary.ast_nodes_emitted != 8
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed while capture summary is incomplete or inconsistent",
        ));
    }
    let initializer_node = capture_u64(bytes, &mut cursor)?;
    if initializer_node != 0 {
        return Err(capture_error("typed while initializer node must be zero"));
    }
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while capture must contain one control header",
        ));
    }
    let control = TypedWhileHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedWhileHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while capture must contain one binding",
        ));
    }
    let binding = TypedNameBindingHeader {
        name_start: capture_u64(bytes, &mut cursor)?,
        name_end: capture_u64(bytes, &mut cursor)?,
        type_kind: {
            let tail = capture_take(bytes, &mut cursor, 8)?;
            if tail[1..].iter().any(|byte| *byte != 0) {
                return Err(capture_error(
                    "typed while binding reserved bytes must be zero",
                ));
            }
            tail[0]
        },
    };
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while capture must contain one body statement",
        ));
    }
    let body_header = capture_take(bytes, &mut cursor, 4)?;
    let body = TypedStatementHeader {
        kind: body_header[0],
        flags: body_header[1],
        type_kind: body_header[2],
        reserved: body_header[3],
        target_start: capture_u64(bytes, &mut cursor)?,
        target_end: capture_u64(bytes, &mut cursor)?,
        expression_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
    };
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while AST count does not fit usize"))?;
    if ast_count != 8 {
        return Err(capture_error(
            "typed while capture must contain eight AST nodes",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error("typed while capture has trailing bytes"));
    }
    Ok(CapturedTypedWhileLocal {
        source,
        summary,
        initializer_node,
        binding,
        control,
        body,
        ast,
    })
}

/// Decodes the padding-free `JST2WN01` native-producer nested-loop hand-off.
/// This reader validates the two-control/two-binding envelope and the ordered
/// body shape before the Stage-2 nested lowerer receives any source spans.
pub fn decode_typed_nested_while_local_capture(
    bytes: &[u8],
) -> Result<CapturedTypedNestedWhileLocal, Stage2CaptureError> {
    let mut cursor = 0usize;
    let capture_magic = capture_take(
        bytes,
        &mut cursor,
        TYPED_NESTED_WHILE_LOCAL_CAPTURE_MAGIC.len(),
    )?;
    let conditional_capture = capture_magic == TYPED_NESTED_WHILE_LOCAL_CONDITIONAL_CAPTURE_MAGIC;
    let multi_conditional_capture =
        capture_magic == TYPED_NESTED_WHILE_LOCAL_MULTI_CONDITIONAL_CAPTURE_MAGIC;
    let dynamic_conditional_capture =
        capture_magic == TYPED_NESTED_WHILE_LOCAL_DYNAMIC_CONDITIONAL_CAPTURE_MAGIC;
    let ordered_body_capture = capture_magic == TYPED_NESTED_WHILE_LOCAL_ORDERED_BODY_CAPTURE_MAGIC;
    if capture_magic != TYPED_NESTED_WHILE_LOCAL_CAPTURE_MAGIC
        && !conditional_capture
        && !multi_conditional_capture
        && !dynamic_conditional_capture
        && !ordered_body_capture
    {
        return Err(capture_error("invalid nested typed while capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("nested typed while source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("nested typed while source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    let body_count = usize::try_from(summary.statements_required)
        .map_err(|_| capture_error("nested typed while body count does not fit usize"))?;
    let ast_count = usize::try_from(summary.ast_nodes_required)
        .map_err(|_| capture_error("nested typed while AST count does not fit usize"))?;
    let expected_ast_count = body_count
        .checked_sub(1)
        .and_then(|value| value.checked_mul(3))
        .and_then(|value| value.checked_add(8))
        .ok_or_else(|| capture_error("nested typed while AST count overflow"))?;
    let minimum_ast_count = expected_ast_count;
    let maximum_ast_count = body_count
        .checked_sub(1)
        .and_then(|value| value.checked_mul(7))
        .and_then(|value| value.checked_add(8))
        .ok_or_else(|| capture_error("nested typed while AST upper bound overflow"))?;
    let ast_count_valid = if ordered_body_capture {
        (minimum_ast_count..=maximum_ast_count).contains(&ast_count)
    } else {
        ast_count == expected_ast_count
    };
    if !(4..=4096).contains(&body_count)
        || ast_count > 12293
        || summary.source_bytes != source.len() as u64
        || summary.statements_emitted != summary.statements_required
        || summary.ast_nodes_emitted != summary.ast_nodes_required
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
        || !ast_count_valid
    {
        return Err(capture_error(
            "nested typed while capture summary is incomplete or inconsistent",
        ));
    }
    let initializer_node = capture_u64(bytes, &mut cursor)?;
    if initializer_node != 0 {
        return Err(capture_error(
            "nested typed while initializer node must be zero",
        ));
    }
    if capture_u64(bytes, &mut cursor)? != 2 {
        return Err(capture_error(
            "nested typed while capture must contain two control headers",
        ));
    }
    let mut controls = Vec::with_capacity(2);
    for _ in 0..2 {
        let condition_node = capture_u64(bytes, &mut cursor)?;
        let start = capture_u64(bytes, &mut cursor)?;
        let end = capture_u64(bytes, &mut cursor)?;
        let tail = capture_take(bytes, &mut cursor, 8)?;
        let control = TypedWhileHeader {
            condition_node,
            start,
            end,
            kind: tail[0],
            type_kind: tail[1],
            reserved: [tail[2], tail[3], tail[4], tail[5], tail[6], tail[7]],
        };
        if control.kind != TYPED_CONTROL_FLOW_KIND_WHILE
            || control.type_kind != TYPE_KIND_INTEGER
            || control.reserved != [0; 6]
            || control.start >= control.end
        {
            return Err(capture_error(
                "nested typed while control header is invalid",
            ));
        }
        controls.push(control);
    }
    if capture_u64(bytes, &mut cursor)? != 2 {
        return Err(capture_error(
            "nested typed while capture must contain two bindings",
        ));
    }
    let mut bindings = Vec::with_capacity(2);
    for _ in 0..2 {
        let name_start = capture_u64(bytes, &mut cursor)?;
        let name_end = capture_u64(bytes, &mut cursor)?;
        let tail = capture_take(bytes, &mut cursor, 8)?;
        if tail[1..].iter().any(|byte| *byte != 0) || tail[0] != TYPE_KIND_INTEGER {
            return Err(capture_error(
                "nested typed while binding header is invalid",
            ));
        }
        bindings.push(TypedNameBindingHeader {
            name_start,
            name_end,
            type_kind: tail[0],
        });
    }
    if capture_u64(bytes, &mut cursor)? != body_count as u64 {
        return Err(capture_error(
            "nested typed while body count does not match its summary",
        ));
    }
    let mut body = Vec::with_capacity(body_count);
    let mut initializer_count = 0usize;
    let mut assignment_count = 0usize;
    let mut conditional_count = 0usize;
    for _ in 0..body_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        let statement = TypedStatementHeader {
            kind: header[0],
            flags: header[1],
            type_kind: header[2],
            reserved: header[3],
            target_start: capture_u64(bytes, &mut cursor)?,
            target_end: capture_u64(bytes, &mut cursor)?,
            expression_node: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        };
        if statement.kind == TYPED_STATEMENT_KIND_LET {
            if statement.flags != TYPED_STATEMENT_FLAG_MUTABLE
                || statement.type_kind != TYPE_KIND_INTEGER
                || statement.reserved != 0
                || statement.expression_node != 4
            {
                return Err(capture_error(
                    "nested typed while inner initializer is invalid",
                ));
            }
            initializer_count += 1;
        } else if statement.kind == TYPED_STATEMENT_KIND_ASSIGN {
            if statement.flags != 0
                || statement.type_kind != TYPE_KIND_INTEGER
                || statement.reserved != 0
            {
                return Err(capture_error(
                    "nested typed while assignment header is invalid",
                ));
            }
            assignment_count += 1;
        } else if (conditional_capture
            || multi_conditional_capture
            || dynamic_conditional_capture
            || ordered_body_capture)
            && matches!(
                statement.kind,
                TYPED_STATEMENT_KIND_BREAK | TYPED_STATEMENT_KIND_CONTINUE
            )
        {
            if statement.flags != TYPED_STATEMENT_FLAG_CONDITIONAL
                || statement.type_kind != TYPE_KIND_BOOL
                || statement.reserved != 0
                || statement.target_start != 0
                || statement.target_end != 0
            {
                return Err(capture_error(
                    "nested typed while conditional control header is invalid",
                ));
            }
            conditional_count += 1;
        } else {
            return Err(capture_error(
                "nested typed while body contains an invalid statement",
            ));
        }
        body.push(statement);
    }
    if initializer_count != 1
        || (!dynamic_conditional_capture
            && !ordered_body_capture
            && conditional_count
                > if multi_conditional_capture {
                    2
                } else if conditional_capture {
                    1
                } else {
                    0
                })
        || assignment_count + initializer_count + conditional_count != body_count
        || ((conditional_capture
            || multi_conditional_capture
            || dynamic_conditional_capture
            || ordered_body_capture)
            && if dynamic_conditional_capture {
                conditional_count < 3
            } else if ordered_body_capture {
                conditional_count < 1
            } else {
                conditional_count != if multi_conditional_capture { 2 } else { 1 }
            })
        || (!conditional_capture
            && !multi_conditional_capture
            && !dynamic_conditional_capture
            && !ordered_body_capture
            && conditional_count != 0)
    {
        return Err(capture_error(
            "nested typed while body has an invalid initializer/control shape",
        ));
    }
    if capture_u64(bytes, &mut cursor)? != ast_count as u64 {
        return Err(capture_error(
            "nested typed while AST count does not match its summary",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error(
            "nested typed while capture has trailing bytes",
        ));
    }
    Ok(CapturedTypedNestedWhileLocal {
        source,
        summary,
        initializer_node,
        bindings,
        controls,
        body,
        ast,
    })
}

/// Decodes the padding-free `JST2WHS1` hand-off with two ordered body
/// assignments. The record count is carried explicitly so future body-list
/// extensions can remain additive instead of changing the one-statement ABI.
pub fn decode_typed_while_local_statements_capture(
    bytes: &[u8],
) -> Result<CapturedTypedWhileLocalStatements, Stage2CaptureError> {
    let mut cursor = 0usize;
    let capture_magic = capture_take(
        bytes,
        &mut cursor,
        TYPED_WHILE_LOCAL_STATEMENTS_CAPTURE_MAGIC.len(),
    )?;
    let break_capture = capture_magic == TYPED_WHILE_LOCAL_BREAK_CAPTURE_MAGIC;
    let continue_capture = capture_magic == TYPED_WHILE_LOCAL_CONTINUE_CAPTURE_MAGIC;
    let conditional_capture = capture_magic == TYPED_WHILE_LOCAL_CONDITIONAL_CAPTURE_MAGIC;
    let multi_conditional_capture =
        capture_magic == TYPED_WHILE_LOCAL_MULTI_CONDITIONAL_CAPTURE_MAGIC;
    let dynamic_capture = capture_magic == TYPED_WHILE_LOCAL_DYNAMIC_CAPTURE_MAGIC;
    let dynamic_control_capture = capture_magic == TYPED_WHILE_LOCAL_DYNAMIC_CONTROL_CAPTURE_MAGIC;
    let three_statement_capture = capture_magic == TYPED_WHILE_LOCAL_THREE_STATEMENTS_CAPTURE_MAGIC;
    if capture_magic != TYPED_WHILE_LOCAL_STATEMENTS_CAPTURE_MAGIC
        && !break_capture
        && !continue_capture
        && !conditional_capture
        && !multi_conditional_capture
        && !dynamic_capture
        && !dynamic_control_capture
        && !three_statement_capture
    {
        return Err(capture_error(
            "invalid typed while-statements capture magic",
        ));
    }
    let fixed_body_count: usize = if multi_conditional_capture {
        3
    } else if break_capture || continue_capture {
        2
    } else if three_statement_capture {
        3
    } else {
        2
    };
    let fixed_ast_count: usize = if multi_conditional_capture {
        14
    } else if conditional_capture {
        11
    } else if break_capture || continue_capture {
        8
    } else if three_statement_capture {
        14
    } else {
        11
    };
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while-statements source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed while-statements source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    let is_long_generic_dynamic_control_source = dynamic_control_capture
        && (source.contains("JADREN_STAGE2_GENERIC_LONG_DYNAMIC_CONTROL")
            || source.contains("JADREN_STAGE2_DYNAMIC_BODY_LET")
            || source.contains("JADREN_STAGE2_DYNAMIC_MULTI_BODY_LET")
            || source.contains("JADREN_STAGE2_DYNAMIC_MUTABLE_BODY_LET"));
    let is_mutable_dynamic_body_let_source =
        dynamic_control_capture && source.contains("JADREN_STAGE2_DYNAMIC_MUTABLE_BODY_LET");
    let (expected_body_count, expected_ast_count) = if dynamic_capture || dynamic_control_capture {
        let dynamic_body_count = usize::try_from(summary.statements_required)
            .map_err(|_| capture_error("dynamic typed while body count does not fit usize"))?;
        let dynamic_ast_count = usize::try_from(summary.ast_nodes_required)
            .map_err(|_| capture_error("dynamic typed while AST count does not fit usize"))?;
        if dynamic_body_count == 0 || dynamic_body_count > 4096 || dynamic_ast_count > 12293 {
            return Err(capture_error(
                "dynamic typed while capture exceeds its bounded list limit",
            ));
        }
        let expected_dynamic_ast_count = dynamic_body_count
            .checked_mul(3)
            .and_then(|value| value.checked_add(5))
            .ok_or_else(|| capture_error("dynamic typed while AST count overflow"))?;
        if (!is_long_generic_dynamic_control_source
            && dynamic_ast_count != expected_dynamic_ast_count)
            || (is_long_generic_dynamic_control_source
                && dynamic_ast_count < expected_dynamic_ast_count)
        {
            return Err(capture_error(
                "dynamic typed while AST count does not match its body list",
            ));
        }
        (dynamic_body_count, dynamic_ast_count)
    } else {
        (fixed_body_count, fixed_ast_count)
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != expected_body_count as u64
        || summary.statements_emitted != expected_body_count as u64
        || summary.ast_nodes_required != expected_ast_count as u64
        || summary.ast_nodes_emitted != expected_ast_count as u64
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed while-statements capture summary is incomplete or inconsistent",
        ));
    }
    let initializer_node = capture_u64(bytes, &mut cursor)?;
    if initializer_node != 0 {
        return Err(capture_error(
            "typed while-statements initializer node must be zero",
        ));
    }
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while-statements capture must contain one control header",
        ));
    }
    let control = TypedWhileHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedWhileHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while-statements capture must contain one binding",
        ));
    }
    let binding = TypedNameBindingHeader {
        name_start: capture_u64(bytes, &mut cursor)?,
        name_end: capture_u64(bytes, &mut cursor)?,
        type_kind: {
            let tail = capture_take(bytes, &mut cursor, 8)?;
            if tail[1..].iter().any(|byte| *byte != 0) {
                return Err(capture_error(
                    "typed while-statements binding reserved bytes must be zero",
                ));
            }
            tail[0]
        },
    };
    let body_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while-statements body count does not fit usize"))?;
    if body_count != expected_body_count {
        return Err(capture_error(
            "typed while-statements capture body count does not match its magic",
        ));
    }
    let mut body = Vec::with_capacity(body_count);
    for _ in 0..body_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        body.push(TypedStatementHeader {
            kind: header[0],
            flags: header[1],
            type_kind: header[2],
            reserved: header[3],
            target_start: capture_u64(bytes, &mut cursor)?,
            target_end: capture_u64(bytes, &mut cursor)?,
            expression_node: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if dynamic_control_capture {
        let mut assignment_count = 0usize;
        let mut conditional_count = 0usize;
        for statement in &body {
            if ((statement.kind == TYPED_STATEMENT_KIND_ASSIGN && statement.flags == 0)
                || (statement.kind == TYPED_STATEMENT_KIND_LET
                    && (statement.flags == 0
                        || (is_mutable_dynamic_body_let_source
                            && statement.flags == TYPED_STATEMENT_FLAG_MUTABLE))))
                && statement.type_kind == TYPE_KIND_INTEGER
                && statement.reserved == 0
            {
                assignment_count += 1;
            } else if (statement.kind == TYPED_STATEMENT_KIND_BREAK
                || statement.kind == TYPED_STATEMENT_KIND_CONTINUE)
                && statement.flags == TYPED_STATEMENT_FLAG_CONDITIONAL
                && statement.type_kind == TYPE_KIND_BOOL
                && statement.reserved == 0
            {
                conditional_count += 1;
            } else {
                return Err(capture_error(
                    "dynamic typed while control capture contains an invalid body header",
                ));
            }
        }
        if assignment_count == 0 || conditional_count == 0 {
            return Err(capture_error(
                "dynamic typed while control capture requires assignment and conditional records",
            ));
        }
    }
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while-statements AST count does not fit usize"))?;
    if ast_count != expected_ast_count {
        return Err(capture_error(
            "typed while-statements capture AST count does not match its magic",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error(
            "typed while-statements capture has trailing bytes",
        ));
    }
    Ok(CapturedTypedWhileLocalStatements {
        source,
        summary,
        initializer_node,
        binding,
        control,
        body,
        ast,
    })
}

/// Decodes the padding-free `JST2WHB1` hand-off for a body-local `let`
/// followed by an assignment to the enclosing loop local.  The body list is
/// intentionally kept in the same fixed two-record shape as the current
/// native producer contract; the lowerer materialises the `let` slot for each
/// loop iteration.
pub fn decode_typed_while_local_body_let_capture(
    bytes: &[u8],
) -> Result<CapturedTypedWhileLocalBodyLet, Stage2CaptureError> {
    let mut cursor = 0usize;
    if capture_take(
        bytes,
        &mut cursor,
        TYPED_WHILE_LOCAL_BODY_LET_CAPTURE_MAGIC.len(),
    )? != TYPED_WHILE_LOCAL_BODY_LET_CAPTURE_MAGIC
    {
        return Err(capture_error("invalid typed while body-let capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while body-let source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed while body-let source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != 2
        || summary.statements_emitted != 2
        || summary.ast_nodes_required != 9
        || summary.ast_nodes_emitted != 9
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed while body-let capture summary is incomplete or inconsistent",
        ));
    }
    let initializer_node = capture_u64(bytes, &mut cursor)?;
    if initializer_node != 0 {
        return Err(capture_error(
            "typed while body-let initializer node must be zero",
        ));
    }
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while body-let capture must contain one control header",
        ));
    }
    let control = TypedWhileHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedWhileHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    if capture_u64(bytes, &mut cursor)? != 1 {
        return Err(capture_error(
            "typed while body-let capture must contain one binding",
        ));
    }
    let binding = TypedNameBindingHeader {
        name_start: capture_u64(bytes, &mut cursor)?,
        name_end: capture_u64(bytes, &mut cursor)?,
        type_kind: {
            let tail = capture_take(bytes, &mut cursor, 8)?;
            if tail[1..].iter().any(|byte| *byte != 0) {
                return Err(capture_error(
                    "typed while body-let binding reserved bytes must be zero",
                ));
            }
            tail[0]
        },
    };
    let body_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while body-let body count does not fit usize"))?;
    if body_count != 2 {
        return Err(capture_error(
            "typed while body-let capture must contain two body statements",
        ));
    }
    let mut body = Vec::with_capacity(body_count);
    for _ in 0..body_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        body.push(TypedStatementHeader {
            kind: header[0],
            flags: header[1],
            type_kind: header[2],
            reserved: header[3],
            target_start: capture_u64(bytes, &mut cursor)?,
            target_end: capture_u64(bytes, &mut cursor)?,
            expression_node: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed while body-let AST count does not fit usize"))?;
    if ast_count != 9 {
        return Err(capture_error(
            "typed while body-let capture must contain nine AST nodes",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error(
            "typed while body-let capture has trailing bytes",
        ));
    }
    Ok(CapturedTypedWhileLocalBodyLet {
        source,
        summary,
        initializer_node,
        binding,
        control,
        body,
        ast,
    })
}

/// Decodes the padding-free typed conditional capture emitted by the native
/// Jadren producer loader. The summary uses the existing 64-byte status ABI;
/// its statement counters represent one control header in this additive
/// format. Trailing bytes and incomplete output are rejected before lowering.
pub fn decode_typed_if_return_capture(
    bytes: &[u8],
) -> Result<CapturedTypedIfReturn, Stage2CaptureError> {
    let mut cursor = 0usize;
    if capture_take(bytes, &mut cursor, TYPED_IF_RETURN_CAPTURE_MAGIC.len())?
        != TYPED_IF_RETURN_CAPTURE_MAGIC
    {
        return Err(capture_error("invalid typed if-return capture magic"));
    }
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed if-return source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed if-return source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != 1
        || summary.statements_emitted != 1
        || summary.ast_nodes_required != 5
        || summary.ast_nodes_emitted != 5
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed if-return capture summary is incomplete or inconsistent",
        ));
    }
    let control_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed if-return control count does not fit usize"))?;
    if control_count != 1 {
        return Err(capture_error(
            "typed if-return capture must contain one control header",
        ));
    }
    let control = TypedIfReturnHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        then_node: capture_u64(bytes, &mut cursor)?,
        else_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedIfReturnHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed if-return AST count does not fit usize"))?;
    if ast_count != 5 {
        return Err(capture_error(
            "typed if-return capture must contain five AST nodes",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error("typed if-return capture has trailing bytes"));
    }
    Ok(CapturedTypedIfReturn {
        source,
        summary,
        control,
        ast,
    })
}

/// Decodes the padding-free `JST2IFV1` hand-off for one merged `if` value and
/// one immutable post-join continuation.
pub fn decode_typed_if_value_continuation_capture(
    bytes: &[u8],
) -> Result<CapturedTypedIfValueContinuation, Stage2CaptureError> {
    decode_typed_if_value_continuation_capture_with_magic(
        bytes,
        TYPED_IF_VALUE_CONTINUATION_CAPTURE_MAGIC,
    )
}

/// Decodes the same fixed layout for the mutable-local `JST2IFL1` hand-off.
/// The distinct magic keeps the Stage-2 driver from silently selecting the
/// immutable join-parameter lowerer for a StackAlloc/Store contract.
pub fn decode_typed_if_value_local_assignment_capture(
    bytes: &[u8],
) -> Result<CapturedTypedIfValueContinuation, Stage2CaptureError> {
    decode_typed_if_value_continuation_capture_with_magic(
        bytes,
        TYPED_IF_VALUE_LOCAL_ASSIGNMENT_CAPTURE_MAGIC,
    )
}

fn decode_typed_if_value_continuation_capture_with_magic(
    bytes: &[u8],
    expected_magic: &[u8; 8],
) -> Result<CapturedTypedIfValueContinuation, Stage2CaptureError> {
    if !bytes.starts_with(expected_magic) {
        return Err(capture_error(
            "invalid typed if-value continuation capture magic",
        ));
    }
    let mut cursor = expected_magic.len();
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed if-value source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed if-value source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != 1
        || summary.statements_emitted != 1
        || summary.ast_nodes_required != 8
        || summary.ast_nodes_emitted != 8
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed if-value continuation capture summary is incomplete or inconsistent",
        ));
    }
    let control_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed if-value control count does not fit usize"))?;
    if control_count != 1 {
        return Err(capture_error(
            "typed if-value continuation capture must contain one control header",
        ));
    }
    let control = TypedIfReturnHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        then_node: capture_u64(bytes, &mut cursor)?,
        else_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedIfReturnHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    let continuation_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed continuation count does not fit usize"))?;
    if continuation_count != 1 {
        return Err(capture_error(
            "typed if-value continuation capture must contain one continuation header",
        ));
    }
    let continuation_node = capture_u64(bytes, &mut cursor)?;
    let binding_name_start = capture_u64(bytes, &mut cursor)?;
    let binding_name_end = capture_u64(bytes, &mut cursor)?;
    let continuation_tail = capture_take(bytes, &mut cursor, 8)?;
    let continuation_binding = TypedNameBindingHeader {
        name_start: binding_name_start,
        name_end: binding_name_end,
        type_kind: continuation_tail[0],
    };
    if continuation_tail[1..].iter().any(|byte| *byte != 0) {
        return Err(capture_error(
            "typed continuation reserved bytes must be zero",
        ));
    }
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed continuation AST count does not fit usize"))?;
    if ast_count != 8 {
        return Err(capture_error(
            "typed if-value continuation capture must contain eight AST nodes",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error(
            "typed if-value continuation capture has trailing bytes",
        ));
    }
    Ok(CapturedTypedIfValueContinuation {
        source,
        summary,
        control,
        continuation_binding,
        continuation_node,
        ast,
    })
}

/// Decodes the padding-free `JST2IFS1` hand-off for a mutable `if` merge and
/// three post-join statements (two assignments followed by a return).
pub fn decode_typed_if_value_statement_tail_capture(
    bytes: &[u8],
) -> Result<CapturedTypedIfValueStatementTail, Stage2CaptureError> {
    if !bytes.starts_with(TYPED_IF_VALUE_STATEMENT_TAIL_CAPTURE_MAGIC) {
        return Err(capture_error(
            "invalid typed if-value statement-tail capture magic",
        ));
    }
    let mut cursor = TYPED_IF_VALUE_STATEMENT_TAIL_CAPTURE_MAGIC.len();
    let source_length = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement-tail source length does not fit usize"))?;
    let source = String::from_utf8(capture_take(bytes, &mut cursor, source_length)?.to_vec())
        .map_err(|_| capture_error("typed statement-tail source is not UTF-8"))?;
    let summary = jadren_selfhost_api::TypedStatementStage2Summary {
        source_bytes: capture_u64(bytes, &mut cursor)?,
        statements_required: capture_u64(bytes, &mut cursor)?,
        statements_emitted: capture_u64(bytes, &mut cursor)?,
        ast_nodes_required: capture_u64(bytes, &mut cursor)?,
        ast_nodes_emitted: capture_u64(bytes, &mut cursor)?,
        errors: capture_u64(bytes, &mut cursor)?,
        status_flags: capture_u64(bytes, &mut cursor)?,
        reserved: capture_u64(bytes, &mut cursor)?,
    };
    if summary.source_bytes != source.len() as u64
        || summary.statements_required != 3
        || summary.statements_emitted != 3
        || summary.ast_nodes_required != 12
        || summary.ast_nodes_emitted != 12
        || summary.errors != 0
        || summary.status_flags != 7
        || summary.reserved != 0
    {
        return Err(capture_error(
            "typed statement-tail capture summary is incomplete or inconsistent",
        ));
    }
    let control_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement-tail control count does not fit usize"))?;
    if control_count != 1 {
        return Err(capture_error(
            "typed statement-tail capture must contain one control header",
        ));
    }
    let control = TypedIfReturnHeader {
        condition_node: capture_u64(bytes, &mut cursor)?,
        then_node: capture_u64(bytes, &mut cursor)?,
        else_node: capture_u64(bytes, &mut cursor)?,
        start: capture_u64(bytes, &mut cursor)?,
        end: capture_u64(bytes, &mut cursor)?,
        kind: 0,
        type_kind: 0,
        reserved: [0; 6],
    };
    let control_tail = capture_take(bytes, &mut cursor, 8)?;
    let control = TypedIfReturnHeader {
        kind: control_tail[0],
        type_kind: control_tail[1],
        reserved: [
            control_tail[2],
            control_tail[3],
            control_tail[4],
            control_tail[5],
            control_tail[6],
            control_tail[7],
        ],
        ..control
    };
    let continuation_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement-tail continuation count does not fit usize"))?;
    if continuation_count != 1 {
        return Err(capture_error(
            "typed statement-tail capture must contain one continuation header",
        ));
    }
    let continuation_node = capture_u64(bytes, &mut cursor)?;
    if continuation_node != 0 {
        return Err(capture_error(
            "typed statement-tail continuation node must be zero",
        ));
    }
    let continuation_binding = TypedNameBindingHeader {
        name_start: capture_u64(bytes, &mut cursor)?,
        name_end: capture_u64(bytes, &mut cursor)?,
        type_kind: 0,
    };
    let continuation_tail = capture_take(bytes, &mut cursor, 8)?;
    if continuation_tail[1..].iter().any(|byte| *byte != 0) {
        return Err(capture_error(
            "typed statement-tail continuation reserved bytes must be zero",
        ));
    }
    let continuation_binding = TypedNameBindingHeader {
        type_kind: continuation_tail[0],
        ..continuation_binding
    };
    let statement_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement-tail statement count does not fit usize"))?;
    if statement_count != 3 {
        return Err(capture_error(
            "typed statement-tail capture must contain three statements",
        ));
    }
    let mut statements = Vec::with_capacity(statement_count);
    for _ in 0..statement_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        statements.push(TypedStatementHeader {
            kind: header[0],
            flags: header[1],
            type_kind: header[2],
            reserved: header[3],
            target_start: capture_u64(bytes, &mut cursor)?,
            target_end: capture_u64(bytes, &mut cursor)?,
            expression_node: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    let ast_count = usize::try_from(capture_u64(bytes, &mut cursor)?)
        .map_err(|_| capture_error("typed statement-tail AST count does not fit usize"))?;
    if ast_count != 12 {
        return Err(capture_error(
            "typed statement-tail capture must contain twelve AST nodes",
        ));
    }
    let mut ast = Vec::with_capacity(ast_count);
    for _ in 0..ast_count {
        let header = capture_take(bytes, &mut cursor, 4)?;
        ast.push(TypedExpressionAstNodeHeader {
            syntax_kind: header[0],
            type_kind: header[1],
            flags: header[2],
            reserved: header[3],
            left: capture_u64(bytes, &mut cursor)?,
            right: capture_u64(bytes, &mut cursor)?,
            aux: capture_u64(bytes, &mut cursor)?,
            start: capture_u64(bytes, &mut cursor)?,
            end: capture_u64(bytes, &mut cursor)?,
        });
    }
    if cursor != bytes.len() {
        return Err(capture_error(
            "typed statement-tail capture has trailing bytes",
        ));
    }
    Ok(CapturedTypedIfValueStatementTail {
        source,
        summary,
        control,
        continuation_binding,
        statements,
        ast,
    })
}

/// Imports one complete bounded stage-2 stream into canonical verified JIR.
///
/// The source must be the same immutable UTF-8 text used by the producer. The
/// function rejects truncated and oversized slices instead of silently using a
/// prefix, so no partially emitted stream can reach LLVM or another backend.
pub fn import_stage2_jir(
    source: &str,
    source_id: SourceId,
    summary: Stage2JirSummary,
    records: &[Stage2JirRecord],
) -> Result<Module, Stage2ImportError> {
    validate_summary(
        summary,
        records.len(),
        records
            .iter()
            .filter(|record| record.kind == STAGE2_JIR_RECORD_LOCAL_BINDING_METADATA)
            .count() as u64,
    )?;
    validate_type_record(&records[0])?;

    let function_count = usize::try_from(summary.functions_seen).map_err(|_| {
        invalid_summary("functions_seen", usize::MAX as u64, summary.functions_seen)
    })?;
    let mut function_declarations = Vec::with_capacity(function_count);
    for (record_index, record) in records.iter().enumerate() {
        if record.kind == STAGE2_JIR_RECORD_FUNCTION {
            let span = source_span(source, source_id, record, record_index)?;
            let name = function_name(source, span.start, record_index)?;
            function_declarations.push((name, record.operand_a, span));
        }
    }
    if function_declarations.len() != function_count {
        return Err(invalid_record(
            0,
            "stage-2 function declaration count does not match summary",
        ));
    }
    let mut functions = Vec::with_capacity(function_count);
    let mut names = BTreeSet::new();
    let mut previous_function_end = 0usize;
    let mut record_cursor = 1usize;
    let mut leading_group_count = 0u64;
    let mut direct_call_count = 0u64;

    for function_index in 0..function_count {
        let record_base = record_cursor;
        let function_record = stage2_record(records, record_base)?;
        let block_record = stage2_record(records, record_base + 1)?;

        validate_function_record(function_record, record_base, function_index)?;
        validate_block_record(block_record, record_base + 1, function_index)?;

        let function_span = source_span(source, source_id, function_record, record_base)?;
        let block_span = source_span(source, source_id, block_record, record_base + 1)?;
        if source.as_bytes()[block_span.start] != b'{'
            || source.as_bytes()[block_span.end - 1] != b'}'
        {
            return Err(invalid_record(
                record_base + 1,
                "entry block span is not delimited by braces",
            ));
        }

        let name = function_name(source, function_span.start, record_base)?;
        if !names.insert(name.clone()) {
            return Err(Stage2ImportError::InvalidFunctionName { index: record_base });
        }

        let parameter_count = usize::try_from(function_record.operand_a).map_err(|_| {
            invalid_record(record_base, "stage-2 parameter count does not fit usize")
        })?;
        if parameter_count > usize::from(STAGE2_JIR_MAX_PARAMETERS) {
            return Err(invalid_record(
                record_base,
                "bounded stage-2 function has too many parameters",
            ));
        }
        let parameters = if parameter_count > 0 {
            function_parameters(
                source,
                source_id,
                function_span,
                block_span,
                parameter_count,
                record_base,
            )?
        } else {
            Vec::new()
        };
        let mut instructions = Vec::with_capacity(33);
        let mut value_spans = Vec::with_capacity(33 + parameter_count);
        for (_, parameter_span) in &parameters {
            value_spans.push(*parameter_span);
        }
        let mut constant_spans = Vec::with_capacity(17);
        let mut binary_shapes = Vec::with_capacity(16);
        let mut saw_binary = false;
        let mut direct_call_for_function = false;
        let mut direct_call_two_result_bindings = false;
        let mut direct_call_count_for_function = 0u8;
        let mut local_binding = None;
        let mut second_local_binding = None;
        let mut third_local_binding = None;
        let mut instruction_cursor = record_base + 2;
        loop {
            let instruction_record = stage2_record(records, instruction_cursor)?;
            if instruction_record.kind == STAGE2_JIR_RECORD_TERMINATOR {
                break;
            }
            if instruction_record.kind == STAGE2_JIR_RECORD_LOCAL_BINDING_METADATA {
                if third_local_binding.is_some() {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded stage-2 function has more than three local bindings",
                    ));
                }
                let declaration = source_span(
                    source,
                    source_id,
                    &Stage2JirRecord {
                        source_start: instruction_record.source_start,
                        source_end: instruction_record.source_end,
                        ..*instruction_record
                    },
                    instruction_cursor,
                )?;
                let use_span = span_from_offsets(
                    source,
                    source_id,
                    instruction_record.operand_a,
                    instruction_record.operand_b,
                    instruction_cursor,
                )?;
                let binding = validate_local_binding_metadata(
                    source,
                    function_index,
                    instruction_record,
                    instruction_cursor,
                    declaration,
                    use_span,
                    value_spans.len(),
                    block_span,
                )?;
                if local_binding.is_none() {
                    local_binding = Some(binding);
                } else if second_local_binding.is_none() {
                    second_local_binding = Some(binding);
                } else {
                    third_local_binding = Some(binding);
                }
                instruction_cursor += 1;
                continue;
            }
            if instruction_record.kind == STAGE2_JIR_RECORD_DIRECT_CALL {
                if direct_call_count_for_function >= 2
                    || (direct_call_for_function && local_binding.is_none())
                {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded stage-2 function has more than one direct call without a result binding",
                    ));
                }
                if direct_call_count >= 5 {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded stage-2 stream has more than five direct calls",
                    ));
                }
                let value_index = parameter_count + instructions.len();
                let instruction_span =
                    source_span(source, source_id, instruction_record, instruction_cursor)?;
                if instruction_record.opcode != 1
                    || instruction_record.type_kind != TYPE_KIND_INTEGER
                    || instruction_record.flags != STAGE2_JIR_FLAG_HAS_VALUE
                    || instruction_record.function_index != function_index as u64
                    || instruction_record.block_index != 0
                    || instruction_record.value_index != value_index as u64
                {
                    return Err(invalid_record(
                        instruction_cursor,
                        "invalid bounded direct-call record header",
                    ));
                }
                let callee_index = usize::try_from(instruction_record.operand_a).map_err(|_| {
                    invalid_record(
                        instruction_cursor,
                        "direct-call callee index does not fit usize",
                    )
                })?;
                let (callee_name, callee_parameter_count, _) =
                    function_declarations.get(callee_index).ok_or_else(|| {
                        invalid_record(instruction_cursor, "direct-call callee is out of range")
                    })?;
                if *callee_parameter_count == 0 {
                    if instruction_record.operand_b != 0 {
                        return Err(invalid_record(
                            instruction_cursor,
                            "zero-argument direct call must use a zero argument sentinel",
                        ));
                    }
                    validate_zero_argument_direct_call_source(
                        source,
                        instruction_span,
                        callee_name,
                        instruction_cursor,
                    )?;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value: ValueId::new(value_index),
                            ty: TypeId::new(0),
                        }),
                        kind: InstructionKind::Call {
                            function: FunctionId::new(callee_index),
                            arguments: Vec::new(),
                        },
                        span: Some(instruction_span),
                    });
                    value_spans.push(instruction_span);
                    direct_call_for_function = true;
                    direct_call_count_for_function += 1;
                    direct_call_count = direct_call_count.checked_add(1).ok_or_else(|| {
                        invalid_summary("calls_seen", u64::MAX, summary.calls_seen)
                    })?;
                    instruction_cursor += 1;
                    continue;
                }
                if *callee_parameter_count != 1 {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded direct-call callee must have one Int32 parameter",
                    ));
                }
                let argument_index =
                    usize::try_from(instruction_record.operand_b).map_err(|_| {
                        invalid_record(
                            instruction_cursor,
                            "direct-call argument index does not fit usize",
                        )
                    })?;
                let argument_value_span =
                    value_spans.get(argument_index).copied().ok_or_else(|| {
                        invalid_record(instruction_cursor, "direct-call argument is not defined")
                    })?;
                let argument_binding = [local_binding, second_local_binding, third_local_binding]
                    .into_iter()
                    .flatten()
                    .find(|binding| binding.value_index == argument_index);
                let argument_is_local = argument_binding.is_some();
                let argument_span = argument_binding
                    .map(|binding| binding.use_span)
                    .unwrap_or(argument_value_span);
                let argument_is_constant = constant_spans.contains(&argument_value_span);
                let argument_is_parameter = parameters
                    .first()
                    .is_some_and(|(_, parameter_span)| *parameter_span == argument_value_span);
                let argument_binary = binary_shapes
                    .iter()
                    .find(|(_, _, _, span, _)| *span == argument_value_span)
                    .copied();
                let argument_is_binary = argument_binary.is_some();
                let argument_local_binary_operand =
                    argument_binary.and_then(|(_, left_index, right_index, _, _)| {
                        [local_binding, second_local_binding, third_local_binding]
                            .into_iter()
                            .flatten()
                            .find(|binding| {
                                binding.value_index == left_index
                                    || binding.value_index == right_index
                            })
                    });
                let argument_is_local_binary_operand = argument_local_binary_operand.is_some();
                if !argument_is_constant
                    && !argument_is_parameter
                    && !argument_is_binary
                    && !argument_is_local
                    && !argument_is_local_binary_operand
                {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded direct-call argument must be a literal, caller parameter, immutable local, or literal binary value",
                    ));
                }
                let valid_local_literal = argument_is_local
                    && parameter_count == 0
                    && argument_is_constant
                    && constant_spans.len() == 1
                    && binary_shapes.is_empty();
                let valid_local_binary = argument_is_local
                    && argument_is_binary
                    && parameter_count == 0
                    && !argument_is_constant
                    && constant_spans.len() == 2
                    && binary_shapes.len() == 1;
                let valid_local_binary_operand = argument_is_local_binary_operand
                    && parameter_count == 0
                    && constant_spans.len() == 2
                    && binary_shapes.len() == 1
                    && value_spans.len() == 3
                    && argument_binary.is_some_and(|(_, left_index, right_index, _, _)| {
                        left_index == 0 && right_index == 1
                    })
                    && argument_local_binary_operand.is_some_and(|binding| {
                        binding.value_index == 0 || binding.value_index == 1
                    });
                if argument_is_local && !valid_local_literal && !valid_local_binary {
                    return Err(invalid_record(
                        instruction_cursor,
                        "direct-call local argument requires one dense literal or binary initializer in a parameterless caller",
                    ));
                }
                if argument_is_local_binary_operand && !valid_local_binary_operand {
                    return Err(invalid_record(
                        instruction_cursor,
                        "direct-call local binary operand requires one dense literal and one local operand",
                    ));
                }
                if argument_is_binary {
                    let (op, left_index, right_index, binary_span, binary_record_index) =
                        argument_binary.expect("binary argument was checked above");
                    let valid_literal_binary = parameter_count == 0
                        && constant_spans.len() == 2
                        && binary_shapes.len() == 1
                        && left_index == 0
                        && right_index == 1;
                    let valid_parameter_binary = parameter_count == 1
                        && constant_spans.len() == 1
                        && binary_shapes.len() == 1
                        && ((left_index == 0 && right_index == 1)
                            || (left_index == 1 && right_index == 0));
                    if !valid_literal_binary
                        && !valid_parameter_binary
                        && !valid_local_binary_operand
                    {
                        return Err(invalid_record(
                            instruction_cursor,
                            "direct-call binary argument requires dense literal operands or one caller parameter",
                        ));
                    }
                    let left_span = value_spans.get(left_index).copied().ok_or_else(|| {
                        invalid_record(
                            binary_record_index,
                            "direct-call binary left operand is not defined",
                        )
                    })?;
                    let right_span = value_spans.get(right_index).copied().ok_or_else(|| {
                        invalid_record(
                            binary_record_index,
                            "direct-call binary right operand is not defined",
                        )
                    })?;
                    if binary_span != argument_span && !argument_is_local {
                        return Err(invalid_record(
                            instruction_cursor,
                            "direct-call binary argument span does not match its SSA value",
                        ));
                    }
                    if valid_local_binary_operand {
                        let binding = argument_local_binary_operand
                            .expect("local binary operand binding was checked above");
                        if binding.value_index == left_index {
                            validate_binary_source(
                                source,
                                binding.use_span,
                                right_span,
                                binary_span,
                                op,
                                binary_record_index,
                            )?;
                        } else if binding.value_index == right_index {
                            validate_binary_source(
                                source,
                                left_span,
                                binding.use_span,
                                binary_span,
                                op,
                                binary_record_index,
                            )?;
                        } else {
                            return Err(invalid_record(
                                binary_record_index,
                                "direct-call local binary operand binding is not an operand",
                            ));
                        }
                    } else if parameter_count == 1 && left_index == 0 && right_index == 1 {
                        validate_parameter_binary_source(
                            source,
                            &parameters[0].0,
                            right_span,
                            binary_span,
                            op,
                            binary_record_index,
                        )?;
                    } else if parameter_count == 1 && left_index == 1 && right_index == 0 {
                        validate_literal_parameter_binary_source(
                            source,
                            &parameters[0].0,
                            left_span,
                            binary_span,
                            op,
                            binary_record_index,
                        )?;
                    } else {
                        validate_binary_source(
                            source,
                            left_span,
                            right_span,
                            binary_span,
                            op,
                            binary_record_index,
                        )?;
                    }
                }
                let argument_kind = if argument_is_parameter {
                    DirectCallArgumentKind::Parameter
                } else if argument_is_local {
                    DirectCallArgumentKind::Local
                } else if argument_is_binary {
                    DirectCallArgumentKind::Binary
                } else {
                    DirectCallArgumentKind::Literal
                };
                validate_direct_call_source(
                    source,
                    instruction_span,
                    callee_name,
                    argument_span,
                    argument_kind,
                    instruction_cursor,
                )?;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value: ValueId::new(value_index),
                        ty: TypeId::new(0),
                    }),
                    kind: InstructionKind::Call {
                        function: FunctionId::new(callee_index),
                        arguments: vec![ValueId::new(argument_index)],
                    },
                    span: Some(instruction_span),
                });
                value_spans.push(instruction_span);
                direct_call_for_function = true;
                direct_call_count_for_function += 1;
                direct_call_count = direct_call_count
                    .checked_add(1)
                    .ok_or_else(|| invalid_summary("calls_seen", u64::MAX, summary.calls_seen))?;
                instruction_cursor += 1;
                continue;
            }
            if instruction_record.kind != STAGE2_JIR_RECORD_INSTRUCTION {
                return Err(invalid_record(
                    instruction_cursor,
                    "expected bounded instruction or return terminator",
                ));
            }
            if instructions.len() >= 33 {
                return Err(invalid_record(
                    instruction_cursor,
                    "bounded stage-2 expression exceeds thirty-three SSA instructions",
                ));
            }

            let value_index = parameter_count + instructions.len();
            let instruction_span =
                source_span(source, source_id, instruction_record, instruction_cursor)?;
            if instruction_record.opcode == STAGE2_JIR_INSTRUCTION_CONSTANT {
                if saw_binary || constant_spans.len() >= 17 {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded constants must be dense and precede binary instructions",
                    ));
                }
                validate_constant_record(
                    instruction_record,
                    instruction_cursor,
                    function_index,
                    value_index,
                )?;
                validate_literal(
                    source,
                    instruction_span,
                    instruction_record,
                    instruction_cursor,
                )?;
                instructions.push(constant_instruction(
                    instruction_record,
                    instruction_span,
                    value_index,
                ));
                constant_spans.push(instruction_span);
            } else {
                saw_binary = true;
                if binary_shapes.len() >= 16 {
                    return Err(invalid_record(
                        instruction_cursor,
                        "bounded stage-2 expression exceeds sixteen binary instructions",
                    ));
                }
                let (op, left_index, right_index) = validate_binary_record(
                    instruction_record,
                    instruction_cursor,
                    function_index,
                    value_index,
                )?;
                let left_span = value_spans.get(left_index).copied().ok_or_else(|| {
                    invalid_record(instruction_cursor, "binary left operand is not defined")
                })?;
                let right_span = value_spans.get(right_index).copied().ok_or_else(|| {
                    invalid_record(instruction_cursor, "binary right operand is not defined")
                })?;
                if parameter_count == 1 && left_index == 0 {
                    validate_parameter_binary_source(
                        source,
                        &parameters[0].0,
                        right_span,
                        instruction_span,
                        op,
                        instruction_cursor,
                    )?;
                } else if parameter_count == 1 && right_index == 0 {
                    validate_literal_parameter_binary_source(
                        source,
                        &parameters[0].0,
                        left_span,
                        instruction_span,
                        op,
                        instruction_cursor,
                    )?;
                } else if parameter_count == 2 && left_index == 0 && right_index == 1 {
                    validate_parameter_pair_binary_source(
                        source,
                        &parameters[0].0,
                        &parameters[1].0,
                        instruction_span,
                        op,
                        instruction_cursor,
                    )?;
                } else if parameter_count == 2 && left_index == 1 && right_index == 0 {
                    validate_reverse_parameter_pair_binary_source(
                        source,
                        &parameters[0].0,
                        &parameters[1].0,
                        instruction_span,
                        op,
                        instruction_cursor,
                    )?;
                } else if local_binding.is_none()
                    && !records[instruction_cursor + 1..]
                        .iter()
                        .any(|record| record.kind == STAGE2_JIR_RECORD_LOCAL_BINDING_METADATA)
                {
                    validate_binary_source(
                        source,
                        left_span,
                        right_span,
                        instruction_span,
                        op,
                        instruction_cursor,
                    )?;
                }
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value: ValueId::new(value_index),
                        ty: TypeId::new(0),
                    }),
                    kind: InstructionKind::Binary {
                        op,
                        left: ValueId::new(left_index),
                        right: ValueId::new(right_index),
                    },
                    span: Some(instruction_span),
                });
                binary_shapes.push((
                    op,
                    left_index,
                    right_index,
                    instruction_span,
                    instruction_cursor,
                ));
            }
            value_spans.push(instruction_span);
            instruction_cursor += 1;
        }

        if let Some(third) = third_local_binding {
            let second = second_local_binding.ok_or_else(|| {
                invalid_record(record_base, "third local binding has no second binding")
            })?;
            let first = local_binding.ok_or_else(|| {
                invalid_record(record_base, "third local binding has no first binding")
            })?;
            if parameters.is_empty() {
                validate_three_literal_local_binding_shape(
                    source,
                    &first,
                    &second,
                    &third,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            } else {
                validate_parameter_three_local_binding_shape(
                    source,
                    &first,
                    &second,
                    &third,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            }
        } else if let Some(second) = second_local_binding {
            let first = local_binding.ok_or_else(|| {
                invalid_record(record_base, "second local binding has no first binding")
            })?;
            if direct_call_for_function {
                validate_same_function_two_direct_call_result_bindings_shape(
                    source,
                    &first,
                    &second,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
                direct_call_two_result_bindings = true;
            } else if parameters.is_empty() {
                validate_two_literal_local_binding_shape(
                    source,
                    &first,
                    &second,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            } else {
                validate_parameter_two_local_binding_shape(
                    source,
                    &first,
                    &second,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            }
        } else if let Some(binding) = local_binding {
            if direct_call_for_function {
                validate_local_direct_call_binding_shape(
                    source,
                    &binding,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            } else {
                validate_local_binding_shape(
                    source,
                    &binding,
                    &parameters,
                    &constant_spans,
                    &binary_shapes,
                    &value_spans,
                    record_base,
                )?;
            }
        } else if direct_call_for_function {
            // The bounded direct-call subset is itself the complete
            // expression for this function. Its result is validated by the
            // return record/source span below, so no binary-shape grammar is
            // applicable here.
        } else if parameter_count == 0 {
            validate_bounded_expression_shape(
                source,
                &constant_spans,
                &binary_shapes,
                record_base,
            )?;
        } else {
            validate_parameter_expression_shape(
                source,
                &parameters,
                &constant_spans,
                &binary_shapes,
                record_base,
            )?;
        }
        let last_value_index = instructions
            .len()
            .checked_add(parameter_count)
            .and_then(|count| count.checked_sub(1))
            .ok_or_else(|| invalid_record(instruction_cursor, "return has no SSA value"))?;
        let return_record = stage2_record(records, instruction_cursor)?;
        let direct_call_result_binding = direct_call_for_function
            && parameters.is_empty()
            && binary_shapes.is_empty()
            && ((constant_spans.len() == 1 && value_spans.len() == 2)
                || (constant_spans.is_empty() && value_spans.len() == 1)
                || (constant_spans.is_empty() && value_spans.len() == 2))
            && local_binding.is_some_and(|binding| {
                binding.value_index == value_spans.len().saturating_sub(1)
                    || (constant_spans.is_empty()
                        && value_spans.len() == 2
                        && binding.value_index == 0)
            });
        let return_binding = if direct_call_two_result_bindings {
            None
        } else if direct_call_result_binding {
            local_binding
        } else if direct_call_for_function {
            None
        } else {
            third_local_binding
                .or(second_local_binding)
                .or(local_binding)
        };
        let return_value_index = if let Some(binding) = return_binding {
            if return_record.value_index != binding.value_index as u64 {
                return Err(invalid_record(
                    instruction_cursor,
                    "local-binding return must use the bound SSA value",
                ));
            }
            binding.value_index
        } else {
            last_value_index
        };
        validate_return_record(
            return_record,
            instruction_cursor,
            function_index,
            return_value_index,
        )?;
        let return_span = source_span(source, source_id, return_record, instruction_cursor)?;
        let expression_span = if let Some(binding) = return_binding {
            validate_local_return_source(
                source,
                return_span,
                binding.use_span,
                instruction_cursor,
            )?;
            binding.use_span
        } else {
            let expression_span = value_spans[return_value_index];
            validate_return_source(
                source,
                return_span,
                expression_span,
                instruction_cursor,
                "return <bounded Int32 expression>;",
            )?;
            expression_span
        };
        record_cursor = instruction_cursor + 1;
        let return_value = ValueId::new(return_value_index);
        let expression_start = expression_span.start;
        let expression_end = expression_span.end;
        if !binary_shapes.is_empty() && source.as_bytes()[expression_start] == b'(' {
            leading_group_count = leading_group_count
                .checked_add(1)
                .ok_or_else(|| invalid_summary("calls_seen", u64::MAX, summary.calls_seen))?;
        }

        if function_span.start < previous_function_end
            || function_span.end != block_span.end
            || block_span.start <= function_span.start
            || expression_start < block_span.start
            || expression_end > block_span.end
            || return_span.start < block_span.start
            || return_span.end > block_span.end
            || return_span.start > expression_start
            || expression_end > return_span.end
        {
            return Err(invalid_record(
                record_base,
                "function, block, expression and return spans are not properly nested",
            ));
        }

        previous_function_end = function_span.end;
        functions.push(Function {
            id: FunctionId::new(function_index),
            name,
            linkage: Linkage::Export,
            parameters: parameters
                .into_iter()
                .enumerate()
                .map(|(index, (name, _))| jadren_jir::Parameter {
                    value: ValueId::new(index),
                    ty: TypeId::new(0),
                    name: Some(name),
                })
                .collect(),
            result: TypeId::new(0),
            blocks: vec![Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions,
                terminator: Terminator::Return {
                    value: Some(return_value),
                },
                span: Some(block_span),
            }],
            span: Some(function_span),
        });
    }

    if record_cursor != records.len() {
        return Err(Stage2ImportError::RecordCount {
            expected: record_cursor,
            actual: records.len(),
        });
    }

    let expected_calls = summary
        .functions_seen
        .checked_add(leading_group_count)
        .and_then(|calls| calls.checked_add(direct_call_count))
        .ok_or_else(|| invalid_summary("calls_seen", u64::MAX, summary.calls_seen))?;
    require_summary("calls_seen", expected_calls, summary.calls_seen)?;

    let module = Module {
        types: vec![Type::Integer {
            signed: true,
            bits: 32,
        }],
        functions,
    };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(Stage2ImportError::Verification(errors))
    }
}

/// Failure produced while lowering a caller-owned typed expression AST into
/// canonical JIR. This boundary reports unsupported syntax instead of
/// silently dropping it or inventing a weaker type.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum TypedExpressionLowerError {
    InvalidNode { index: usize, message: &'static str },
    InvalidSourceSpan { index: usize, start: u64, end: u64 },
    InvalidBinding { index: usize, message: &'static str },
    InvalidCall { index: usize, message: &'static str },
    UnsupportedType { index: usize, type_kind: u8 },
    Verification(Vec<VerificationError>),
}

impl fmt::Display for TypedExpressionLowerError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidNode { index, message } => {
                write!(
                    formatter,
                    "invalid typed expression node {index}: {message}"
                )
            }
            Self::InvalidSourceSpan { index, start, end } => write!(
                formatter,
                "invalid typed expression span {start}..{end} at node {index}"
            ),
            Self::InvalidBinding { index, message } => {
                write!(
                    formatter,
                    "invalid typed expression binding {index}: {message}"
                )
            }
            Self::InvalidCall { index, message } => {
                write!(
                    formatter,
                    "invalid typed expression call {index}: {message}"
                )
            }
            Self::UnsupportedType { index, type_kind } => write!(
                formatter,
                "typed expression node {index} uses unsupported builtin type kind {type_kind}"
            ),
            Self::Verification(errors) => write!(
                formatter,
                "lowered typed expression failed JIR verification with {} error(s)",
                errors.len()
            ),
        }
    }
}

impl std::error::Error for TypedExpressionLowerError {}

/// Failure produced while lowering the first caller-owned straight-line
/// statement sequence. The sequence is deliberately bounded to `let`, local
/// assignment and `return` over the existing scalar typed-expression AST;
/// control-flow and shadowing are separate contracts.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum TypedStatementLowerError {
    InvalidStatement {
        index: usize,
        message: &'static str,
    },
    InvalidSourceSpan {
        index: usize,
        start: u64,
        end: u64,
    },
    Expression {
        index: usize,
        error: TypedExpressionLowerError,
    },
    Verification(Vec<VerificationError>),
}

impl fmt::Display for TypedStatementLowerError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidStatement { index, message } => {
                write!(formatter, "invalid typed statement {index}: {message}")
            }
            Self::InvalidSourceSpan { index, start, end } => write!(
                formatter,
                "invalid typed statement span {start}..{end} at statement {index}"
            ),
            Self::Expression { index, error } => {
                write!(
                    formatter,
                    "statement {index} expression lowering failed: {error}"
                )
            }
            Self::Verification(errors) => write!(
                formatter,
                "lowered typed statements failed JIR verification with {} error(s)",
                errors.len()
            ),
        }
    }
}

impl std::error::Error for TypedStatementLowerError {}

/// Lowers one resolved caller-owned typed expression AST into a verified JIR
/// module. The generated export function is named `__typed_expression`; name
/// bindings become its parameters in binding-table order and caller-owned call
/// bindings become imported declarations. Supported lowering is explicit:
/// integer/bool/float values, groups, `+ - ! ~`, scalar binary and comparison
/// operators, calls whose caller-owned argument stream is complete, and
/// caller-owned fixed-array or dynamic `Slice`/`Buffer` indexing with an
/// explicit bounds proof. Unresolved nodes, strings/chars and user types remain
/// rejected until their ABI carries enough information for sound lowering.
pub fn lower_typed_expression_ast(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    call_bindings: &[TypedCallBindingHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedExpressionLowerError> {
    lower_typed_expression_ast_with_arrays(
        source,
        source_id,
        ast,
        bindings,
        &[],
        call_bindings,
        &[],
        arguments,
    )
}

/// Lowers the same typed expression AST while selecting calls from the
/// caller-owned bounded overload/generic candidate table. Candidates use the
/// already-stable `TypedCallCandidateHeader` contract: exact builtin parameter
/// types win over family-bound candidates, which win over wildcards; ties are
/// rejected and generic substitution derives only builtin return types. The
/// legacy `call_bindings` table and this candidate table are mutually
/// exclusive; the former remains available for callers that already performed
/// overload selection themselves.
pub fn lower_typed_expression_ast_with_candidates(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedExpressionLowerError> {
    lower_typed_expression_ast_with_arrays(
        source,
        source_id,
        ast,
        bindings,
        &[],
        call_bindings,
        call_candidates,
        arguments,
    )
}

/// Lowers a typed expression with caller-owned fixed-array bindings. An
/// array identifier is represented as a JIR inline array parameter and an
/// index node emits a `BoundsCheck` followed by `ExtractElement`.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_expression_ast_with_arrays(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    array_bindings: &[TypedArrayBindingHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedExpressionLowerError> {
    lower_typed_expression_ast_with_arrays_and_sequences(
        source,
        source_id,
        ast,
        bindings,
        array_bindings,
        &[],
        call_bindings,
        call_candidates,
        arguments,
    )
}

/// Lowers a typed expression with caller-owned fixed arrays and dynamic
/// `Slice`/`Buffer` descriptors. A dynamic sequence identifier is represented
/// as its stable pointer/length(/capacity) JIR struct; an index reads the
/// runtime length, converts the integer index to the descriptor width, emits
/// `BoundsCheck`, then performs pointer offset and load. A node with syntax
/// kind [`TYPED_EXPRESSION_SYNTAX_INDEX_STORE`] uses the same descriptor
/// layout and bounds proof, then emits a caller-authorized `Store`; its result
/// is the stored value so the scalar expression result ABI remains unchanged.
/// This remains bounded to builtin scalar elements and does not imply general
/// user-defined or nested sequence typing.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_expression_ast_with_arrays_and_sequences(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    array_bindings: &[TypedArrayBindingHeader],
    sequence_bindings: &[TypedSequenceBindingHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedExpressionLowerError> {
    if !call_bindings.is_empty() && !call_candidates.is_empty() {
        return Err(TypedExpressionLowerError::InvalidCall {
            index: 0,
            message: "call bindings and overload candidates are mutually exclusive",
        });
    }
    if ast.is_empty() {
        return Err(TypedExpressionLowerError::InvalidNode {
            index: 0,
            message: "typed expression AST is empty",
        });
    }

    let mut spans = Vec::with_capacity(ast.len());
    let mut types = Vec::new();
    let mut node_types = Vec::with_capacity(ast.len());
    for (index, node) in ast.iter().enumerate() {
        let is_call_callee = typed_is_call_callee(ast, index);
        let is_index_base = typed_is_index_base(ast, index);
        if (node.flags != 1 || node.type_kind == 0)
            && !(node.syntax_kind == 1 && (is_call_callee || is_index_base))
        {
            return Err(TypedExpressionLowerError::InvalidNode {
                index,
                message: "node is not resolved",
            });
        }
        let span = typed_expression_span(source, source_id, index, node.start, node.end)?;
        spans.push(span);
        node_types.push(typed_jir_type(&mut types, index, node.type_kind)?);
        match node.syntax_kind {
            1 | 2 => {}
            3 | 6 => {
                typed_child_index(index, node.left, "child index is not post-order")?;
            }
            5 => {
                typed_child_index(index, node.left, "callee index is not post-order")?;
                if node.aux == 1 {
                    typed_child_index(index, node.right, "argument index is not post-order")?;
                }
            }
            7 => {
                typed_child_index(index, node.left, "left index is not post-order")?;
                typed_child_index(index, node.right, "right index is not post-order")?;
            }
            4 => {
                typed_child_index(index, node.left, "index base is not post-order")?;
                typed_child_index(index, node.right, "index operand is not post-order")?;
            }
            TYPED_EXPRESSION_SYNTAX_INDEX_STORE => {
                let index_node =
                    typed_child_index(index, node.left, "store target is not post-order")?;
                typed_child_index(index, node.right, "store value is not post-order")?;
                if ast[index_node].syntax_kind != 4 {
                    return Err(TypedExpressionLowerError::InvalidNode {
                        index,
                        message: "indexed store target must be an index node",
                    });
                }
            }
            _ => {
                return Err(TypedExpressionLowerError::InvalidNode {
                    index,
                    message: "unknown syntax kind",
                });
            }
        }
    }

    let mut used_binding_indices = Vec::new();
    let mut used_array_binding_indices = Vec::new();
    let mut used_sequence_binding_indices = Vec::new();
    let mut node_binding_indices = vec![None; ast.len()];
    let mut node_array_binding_indices = vec![None; ast.len()];
    let mut node_sequence_binding_indices = vec![None; ast.len()];
    for (node_index, node) in ast.iter().enumerate() {
        if node.syntax_kind != 1 || typed_is_call_callee(ast, node_index) {
            continue;
        }
        if typed_is_index_base(ast, node_index) {
            let array_matches: Vec<usize> = array_bindings
                .iter()
                .enumerate()
                .filter(|(_, binding)| {
                    typed_same_source_span(
                        source,
                        spans[node_index],
                        binding.name_start,
                        binding.name_end,
                    )
                })
                .map(|(binding_index, _)| binding_index)
                .collect();
            let sequence_matches: Vec<usize> = sequence_bindings
                .iter()
                .enumerate()
                .filter(|(_, binding)| {
                    typed_same_source_span(
                        source,
                        spans[node_index],
                        binding.name_start,
                        binding.name_end,
                    )
                })
                .map(|(binding_index, _)| binding_index)
                .collect();
            if array_matches.len() + sequence_matches.len() != 1 {
                return Err(TypedExpressionLowerError::InvalidBinding {
                    index: node_index,
                    message: if array_matches.is_empty() && sequence_matches.is_empty() {
                        "indexed identifier has no caller-owned array or sequence binding"
                    } else {
                        "indexed identifier has multiple caller-owned array or sequence bindings"
                    },
                });
            }
            if let Some(&binding_index) = array_matches.first() {
                node_array_binding_indices[node_index] = Some(binding_index);
                if !used_array_binding_indices.contains(&binding_index) {
                    used_array_binding_indices.push(binding_index);
                }
            } else if let Some(&binding_index) = sequence_matches.first() {
                node_sequence_binding_indices[node_index] = Some(binding_index);
                if !used_sequence_binding_indices.contains(&binding_index) {
                    used_sequence_binding_indices.push(binding_index);
                }
            }
            continue;
        }
        let matches: Vec<usize> = bindings
            .iter()
            .enumerate()
            .filter(|(_, binding)| {
                typed_same_source_span(
                    source,
                    spans[node_index],
                    binding.name_start,
                    binding.name_end,
                )
            })
            .map(|(binding_index, _)| binding_index)
            .collect();
        if matches.len() != 1 {
            return Err(TypedExpressionLowerError::InvalidBinding {
                index: node_index,
                message: if matches.is_empty() {
                    "identifier has no caller-owned binding"
                } else {
                    "identifier has multiple caller-owned bindings"
                },
            });
        }
        let binding_index = matches[0];
        node_binding_indices[node_index] = Some(binding_index);
        if !used_binding_indices.contains(&binding_index) {
            used_binding_indices.push(binding_index);
        }
    }

    let mut parameters = Vec::with_capacity(used_binding_indices.len());
    let mut binding_values = vec![None; bindings.len()];
    for binding_index in used_binding_indices {
        let binding = bindings[binding_index];
        let ty = typed_jir_type(&mut types, binding_index, binding.type_kind).map_err(|error| {
            match error {
                TypedExpressionLowerError::UnsupportedType { type_kind, .. } => {
                    TypedExpressionLowerError::InvalidBinding {
                        index: binding_index,
                        message: if type_kind == 4 || type_kind == 5 {
                            "string and char bindings are not representable in scalar JIR yet"
                        } else {
                            "binding has an unsupported type"
                        },
                    }
                }
                other => other,
            }
        })?;
        let span = typed_expression_span(
            source,
            source_id,
            binding_index,
            binding.name_start,
            binding.name_end,
        )?;
        let parameter_value = ValueId::new(parameters.len());
        binding_values[binding_index] = Some(parameter_value);
        parameters.push(Parameter {
            value: parameter_value,
            ty,
            name: Some(source[span.start..span.end].to_owned()),
        });
    }
    let mut array_binding_values = vec![None; array_bindings.len()];
    for binding_index in used_array_binding_indices {
        let binding = array_bindings[binding_index];
        if binding.length == 0 {
            return Err(TypedExpressionLowerError::InvalidBinding {
                index: binding_index,
                message: "indexed array binding must have a non-zero length",
            });
        }
        let element_ty = typed_jir_type(&mut types, binding_index, binding.element_type_kind)
            .map_err(|error| match error {
                TypedExpressionLowerError::UnsupportedType { .. } => {
                    TypedExpressionLowerError::InvalidBinding {
                        index: binding_index,
                        message: "array binding has an unsupported builtin element type",
                    }
                }
                other => other,
            })?;
        let ty = typed_array_jir_type(&mut types, element_ty, binding.length);
        let span = typed_expression_span(
            source,
            source_id,
            binding_index,
            binding.name_start,
            binding.name_end,
        )?;
        let parameter_value = ValueId::new(parameters.len());
        array_binding_values[binding_index] = Some(parameter_value);
        parameters.push(Parameter {
            value: parameter_value,
            ty,
            name: Some(source[span.start..span.end].to_owned()),
        });
    }
    let mut sequence_binding_values = vec![None; sequence_bindings.len()];
    for binding_index in used_sequence_binding_indices {
        let binding = sequence_bindings[binding_index];
        if !matches!(
            binding.reserved[0],
            TYPED_SEQUENCE_ACCESS_READ | TYPED_SEQUENCE_ACCESS_WRITE
        ) {
            return Err(TypedExpressionLowerError::InvalidBinding {
                index: binding_index,
                message: "sequence binding has an unsupported access capability",
            });
        }
        if !matches!(
            binding.sequence_kind,
            TYPED_SEQUENCE_KIND_SLICE | TYPED_SEQUENCE_KIND_BUFFER
        ) {
            return Err(TypedExpressionLowerError::InvalidBinding {
                index: binding_index,
                message: "sequence binding has an unsupported descriptor kind",
            });
        }
        let element_ty = typed_jir_type(&mut types, binding_index, binding.element_type_kind)
            .map_err(|error| match error {
                TypedExpressionLowerError::UnsupportedType { .. } => {
                    TypedExpressionLowerError::InvalidBinding {
                        index: binding_index,
                        message: "sequence binding has an unsupported builtin element type",
                    }
                }
                other => other,
            })?;
        let ty = typed_sequence_jir_type(&mut types, element_ty, binding.sequence_kind).ok_or(
            TypedExpressionLowerError::InvalidBinding {
                index: binding_index,
                message: "sequence binding has an unsupported descriptor kind",
            },
        )?;
        let span = typed_expression_span(
            source,
            source_id,
            binding_index,
            binding.name_start,
            binding.name_end,
        )?;
        let parameter_value = ValueId::new(parameters.len());
        sequence_binding_values[binding_index] = Some(parameter_value);
        parameters.push(Parameter {
            value: parameter_value,
            ty,
            name: Some(source[span.start..span.end].to_owned()),
        });
    }

    let mut imports = Vec::<Function>::new();
    let mut call_functions = vec![None; ast.len()];
    let mut call_argument_nodes = vec![None; ast.len()];
    for (node_index, node) in ast.iter().enumerate() {
        if node.syntax_kind != 5 {
            continue;
        }
        let callee_index = typed_child_index(node_index, node.left, "callee")?;
        if ast[callee_index].syntax_kind != 1 {
            return Err(TypedExpressionLowerError::InvalidCall {
                index: node_index,
                message: "callee must be an identifier",
            });
        }
        let callee_span = spans[callee_index];
        let argument_nodes = typed_call_argument_nodes(ast, &spans, node_index, arguments)?;
        let (argument_types, return_type_kind) = if !call_candidates.is_empty() {
            let selected = typed_select_call_candidate(
                source,
                callee_span,
                ast,
                &argument_nodes,
                call_candidates,
            )
            .map_err(|message| TypedExpressionLowerError::InvalidCall {
                index: node_index,
                message,
            })?;
            let argument_types = selected
                .parameter_type_kinds
                .iter()
                .enumerate()
                .map(|(argument_index, type_kind)| {
                    typed_jir_type(&mut types, argument_index, *type_kind).map_err(|error| {
                        match error {
                            TypedExpressionLowerError::UnsupportedType { .. } => {
                                TypedExpressionLowerError::InvalidCall {
                                    index: node_index,
                                    message: "selected overload uses an unsupported JIR parameter type",
                                }
                            }
                            other => other,
                        }
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            (argument_types, selected.return_type_kind)
        } else {
            let argument_types: Vec<TypeId> = argument_nodes
                .iter()
                .map(|argument_index| node_types[*argument_index])
                .collect();
            let candidates: Vec<&TypedCallBindingHeader> = call_bindings
                .iter()
                .filter(|binding| {
                    binding.parameter_count == node.aux
                        && typed_same_source_span(
                            source,
                            callee_span,
                            binding.name_start,
                            binding.name_end,
                        )
                })
                .collect();
            if candidates.len() != 1 {
                return Err(TypedExpressionLowerError::InvalidCall {
                    index: node_index,
                    message: if candidates.is_empty() {
                        "call has no caller-owned signature"
                    } else {
                        "call has multiple matching caller-owned signatures"
                    },
                });
            }
            (argument_types, candidates[0].return_type_kind)
        };
        if return_type_kind != node.type_kind {
            return Err(TypedExpressionLowerError::InvalidCall {
                index: node_index,
                message: "call return type differs from typed AST",
            });
        }
        let callee_name = source[callee_span.start..callee_span.end].to_owned();
        let existing = imports.iter().find(|function| {
            function.name == callee_name
                && function
                    .parameters
                    .iter()
                    .map(|parameter| parameter.ty)
                    .eq(argument_types.iter().copied())
                && function.result == node_types[node_index]
        });
        let function_id = if let Some(function) = existing {
            function.id
        } else {
            let function_id = FunctionId::new(imports.len() + 1);
            imports.push(Function {
                id: function_id,
                name: callee_name,
                linkage: Linkage::Import,
                parameters: argument_types
                    .iter()
                    .copied()
                    .enumerate()
                    .map(|(index, ty)| Parameter {
                        value: ValueId::new(index),
                        ty,
                        name: None,
                    })
                    .collect(),
                result: node_types[node_index],
                blocks: Vec::new(),
                span: Some(callee_span),
            });
            function_id
        };
        call_functions[node_index] = Some(function_id);
        call_argument_nodes[node_index] = Some(argument_nodes);
    }

    let mut instructions = Vec::new();
    let mut node_values = vec![ValueId::new(0); ast.len()];
    let mut node_index_pointers = vec![None; ast.len()];
    let mut next_value = parameters.len();
    for (node_index, node) in ast.iter().enumerate() {
        let value = match node.syntax_kind {
            1 => {
                if typed_is_call_callee(ast, node_index) {
                    ValueId::new(0)
                } else if let Some(array_binding_index) = node_array_binding_indices[node_index] {
                    array_binding_values[array_binding_index].ok_or(
                        TypedExpressionLowerError::InvalidBinding {
                            index: node_index,
                            message: "array binding has no parameter value",
                        },
                    )?
                } else if let Some(sequence_binding_index) =
                    node_sequence_binding_indices[node_index]
                {
                    sequence_binding_values[sequence_binding_index].ok_or(
                        TypedExpressionLowerError::InvalidBinding {
                            index: node_index,
                            message: "sequence binding has no parameter value",
                        },
                    )?
                } else {
                    let binding_index = node_binding_indices[node_index].ok_or(
                        TypedExpressionLowerError::InvalidBinding {
                            index: node_index,
                            message: "identifier binding was not recorded",
                        },
                    )?;
                    binding_values[binding_index].ok_or(
                        TypedExpressionLowerError::InvalidBinding {
                            index: node_index,
                            message: "identifier binding has no parameter value",
                        },
                    )?
                }
            }
            2 => {
                let literal_text = source[spans[node_index].start..spans[node_index].end].trim();
                let (constant, value_type) = match node.type_kind {
                    TYPE_KIND_INTEGER => {
                        let literal = literal_text.parse::<i128>().map_err(|_| {
                            TypedExpressionLowerError::InvalidNode {
                                index: node_index,
                                message: "integer literal is not representable as i128",
                            }
                        })?;
                        (Constant::Integer { value: literal }, node_types[node_index])
                    }
                    TYPE_KIND_FLOAT => {
                        let numeric_text = literal_text
                            .strip_suffix("f64")
                            .or_else(|| literal_text.strip_suffix("f32"))
                            .unwrap_or(literal_text);
                        let literal = numeric_text.parse::<f64>().map_err(|_| {
                            TypedExpressionLowerError::InvalidNode {
                                index: node_index,
                                message: "float literal is not representable as f64",
                            }
                        })?;
                        (
                            Constant::FloatBits {
                                bits: literal.to_bits(),
                            },
                            node_types[node_index],
                        )
                    }
                    _ => {
                        return Err(TypedExpressionLowerError::InvalidNode {
                            index: node_index,
                            message: "literal uses an unsupported scalar type",
                        });
                    }
                };
                let value = ValueId::new(next_value);
                next_value += 1;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value,
                        ty: value_type,
                    }),
                    kind: InstructionKind::Constant(constant),
                    span: Some(spans[node_index]),
                });
                value
            }
            3 => node_values[typed_child_index(node_index, node.left, "group")?],
            4 => {
                let base_index = typed_child_index(node_index, node.left, "index base")?;
                let index_index = typed_child_index(node_index, node.right, "index operand")?;
                let index_value = node_values[index_index];
                if !matches!(
                    types.get(node_types[index_index].index()),
                    Some(Type::Integer { .. })
                ) {
                    return Err(TypedExpressionLowerError::InvalidNode {
                        index: node_index,
                        message: "sequence index must be an integer",
                    });
                }
                let base_value = node_values[base_index];
                if let Some(array_binding_index) = node_array_binding_indices[base_index] {
                    let binding = array_bindings[array_binding_index];
                    let length_value = ValueId::new(next_value);
                    next_value += 1;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value: length_value,
                            ty: node_types[index_index],
                        }),
                        kind: InstructionKind::Constant(Constant::Integer {
                            value: i128::from(binding.length),
                        }),
                        span: Some(spans[node_index]),
                    });
                    instructions.push(Instruction {
                        result: None,
                        kind: InstructionKind::BoundsCheck {
                            index: index_value,
                            length: length_value,
                        },
                        span: Some(spans[node_index]),
                    });
                    let value = ValueId::new(next_value);
                    next_value += 1;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value,
                            ty: node_types[node_index],
                        }),
                        kind: InstructionKind::ExtractElement {
                            aggregate: base_value,
                            index: index_value,
                        },
                        span: Some(spans[node_index]),
                    });
                    value
                } else if let Some(sequence_binding_index) =
                    node_sequence_binding_indices[base_index]
                {
                    let binding = sequence_bindings[sequence_binding_index];
                    let element_ty = typed_jir_type(
                        &mut types,
                        sequence_binding_index,
                        binding.element_type_kind,
                    )?;
                    let sequence_ty =
                        typed_sequence_jir_type(&mut types, element_ty, binding.sequence_kind)
                            .ok_or(TypedExpressionLowerError::InvalidBinding {
                                index: sequence_binding_index,
                                message: "sequence binding has an unsupported descriptor kind",
                            })?;
                    let (data_ty, size_ty) = typed_sequence_layout(&types, sequence_ty).ok_or(
                        TypedExpressionLowerError::InvalidBinding {
                            index: sequence_binding_index,
                            message: "sequence binding has an invalid descriptor layout",
                        },
                    )?;
                    let data = ValueId::new(next_value);
                    next_value += 1;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value: data,
                            ty: data_ty,
                        }),
                        kind: InstructionKind::ExtractValue {
                            aggregate: base_value,
                            index: 0,
                        },
                        span: Some(spans[node_index]),
                    });
                    let length = ValueId::new(next_value);
                    next_value += 1;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value: length,
                            ty: size_ty,
                        }),
                        kind: InstructionKind::ExtractValue {
                            aggregate: base_value,
                            index: 1,
                        },
                        span: Some(spans[node_index]),
                    });
                    let sized_index = if node_types[index_index] == size_ty {
                        index_value
                    } else {
                        let cast_op = typed_integer_cast_op(
                            &types,
                            node_types[index_index],
                            size_ty,
                        )
                        .ok_or(TypedExpressionLowerError::InvalidNode {
                            index: node_index,
                            message: "sequence index cannot be converted to descriptor size",
                        })?;
                        let cast = ValueId::new(next_value);
                        next_value += 1;
                        instructions.push(Instruction {
                            result: Some(TypedValue {
                                value: cast,
                                ty: size_ty,
                            }),
                            kind: InstructionKind::Cast {
                                op: cast_op,
                                value: index_value,
                                target: size_ty,
                            },
                            span: Some(spans[index_index]),
                        });
                        cast
                    };
                    instructions.push(Instruction {
                        result: None,
                        kind: InstructionKind::BoundsCheck {
                            index: sized_index,
                            length,
                        },
                        span: Some(spans[node_index]),
                    });
                    let pointer = ValueId::new(next_value);
                    next_value += 1;
                    instructions.push(Instruction {
                        result: Some(TypedValue {
                            value: pointer,
                            ty: data_ty,
                        }),
                        kind: InstructionKind::Offset {
                            base: data,
                            indices: vec![sized_index],
                        },
                        span: Some(spans[node_index]),
                    });
                    node_index_pointers[node_index] = Some(pointer);
                    if typed_index_node_is_store_target_only(ast, node_index) {
                        // The index node is only the lvalue address of a
                        // following store. Avoid an observable read and keep
                        // the pointer for the store node instead.
                        ValueId::new(0)
                    } else {
                        let value = ValueId::new(next_value);
                        next_value += 1;
                        instructions.push(Instruction {
                            result: Some(TypedValue {
                                value,
                                ty: node_types[node_index],
                            }),
                            kind: InstructionKind::Load {
                                pointer,
                                alignment: 1,
                                volatile: false,
                            },
                            span: Some(spans[node_index]),
                        });
                        value
                    }
                } else {
                    return Err(TypedExpressionLowerError::InvalidBinding {
                        index: node_index,
                        message: "index base is not a caller-owned array or sequence",
                    });
                }
            }
            TYPED_EXPRESSION_SYNTAX_INDEX_STORE => {
                let index_node = typed_child_index(node_index, node.left, "store target")?;
                let value_index = typed_child_index(node_index, node.right, "store value")?;
                let base_index = typed_child_index(index_node, ast[index_node].left, "index base")?;
                let index_index =
                    typed_child_index(index_node, ast[index_node].right, "index operand")?;
                if node_types[value_index] != node_types[node_index]
                    || node_types[index_node] != node_types[value_index]
                {
                    return Err(TypedExpressionLowerError::InvalidNode {
                        index: node_index,
                        message: "indexed store value type differs from the indexed element type",
                    });
                }
                let Some(sequence_binding_index) = node_sequence_binding_indices[base_index] else {
                    return Err(TypedExpressionLowerError::InvalidBinding {
                        index: node_index,
                        message: "indexed store target is not a caller-owned dynamic sequence",
                    });
                };
                let binding = sequence_bindings[sequence_binding_index];
                if binding.reserved[0] != TYPED_SEQUENCE_ACCESS_WRITE {
                    return Err(TypedExpressionLowerError::InvalidBinding {
                        index: sequence_binding_index,
                        message: "indexed sequence store requires a write-capable sequence binding",
                    });
                }
                if !matches!(
                    types.get(node_types[index_index].index()),
                    Some(Type::Integer { .. })
                ) {
                    return Err(TypedExpressionLowerError::InvalidNode {
                        index: node_index,
                        message: "sequence store index must be an integer",
                    });
                }
                let pointer = node_index_pointers[index_node].ok_or(
                    TypedExpressionLowerError::InvalidBinding {
                        index: node_index,
                        message: "indexed store target did not produce a sequence address",
                    },
                )?;
                instructions.push(Instruction {
                    result: None,
                    kind: InstructionKind::Store {
                        pointer,
                        value: node_values[value_index],
                        alignment: 1,
                        volatile: false,
                    },
                    span: Some(spans[node_index]),
                });
                node_values[value_index]
            }
            6 => {
                let operand_index = typed_child_index(node_index, node.left, "operand")?;
                let operand = node_values[operand_index];
                let operator = source[spans[node_index].start..spans[operand_index].start].trim();
                match operator {
                    "+" => operand,
                    "-" | "!" | "~" => {
                        let op = match operator {
                            "-" => UnaryOp::Negate,
                            "!" => UnaryOp::Not,
                            "~" => UnaryOp::BitNot,
                            _ => unreachable!(),
                        };
                        let value = ValueId::new(next_value);
                        next_value += 1;
                        instructions.push(Instruction {
                            result: Some(TypedValue {
                                value,
                                ty: node_types[node_index],
                            }),
                            kind: InstructionKind::Unary { op, operand },
                            span: Some(spans[node_index]),
                        });
                        value
                    }
                    _ => {
                        return Err(TypedExpressionLowerError::InvalidNode {
                            index: node_index,
                            message: "unsupported unary operator",
                        });
                    }
                }
            }
            7 => {
                let left_index = typed_child_index(node_index, node.left, "left")?;
                let right_index = typed_child_index(node_index, node.right, "right")?;
                let left = node_values[left_index];
                let right = node_values[right_index];
                // A grouped child carries the closing delimiter in its source
                // span. Strip only the delimiters adjacent to the child spans
                // before resolving the actual binary operator; the typed AST
                // still retains the full grouped root span for validation.
                let mut operator = source[spans[left_index].end..spans[right_index].start].trim();
                while let Some(rest) = operator.strip_prefix(')') {
                    operator = rest.trim_start();
                }
                while let Some(rest) = operator.strip_suffix('(') {
                    operator = rest.trim_end();
                }
                let kind = match operator {
                    "+" => InstructionKind::Binary {
                        op: BinaryOp::Add,
                        left,
                        right,
                    },
                    "-" => InstructionKind::Binary {
                        op: BinaryOp::Subtract,
                        left,
                        right,
                    },
                    "*" => InstructionKind::Binary {
                        op: BinaryOp::Multiply,
                        left,
                        right,
                    },
                    "/" => InstructionKind::Binary {
                        op: BinaryOp::Divide,
                        left,
                        right,
                    },
                    "%" => InstructionKind::Binary {
                        op: BinaryOp::Remainder,
                        left,
                        right,
                    },
                    "&" => InstructionKind::Binary {
                        op: BinaryOp::BitAnd,
                        left,
                        right,
                    },
                    "|" => InstructionKind::Binary {
                        op: BinaryOp::BitOr,
                        left,
                        right,
                    },
                    "^" => InstructionKind::Binary {
                        op: BinaryOp::BitXor,
                        left,
                        right,
                    },
                    "<<" => InstructionKind::Binary {
                        op: BinaryOp::ShiftLeft,
                        left,
                        right,
                    },
                    ">>" => InstructionKind::Binary {
                        op: BinaryOp::ShiftRight,
                        left,
                        right,
                    },
                    "==" => InstructionKind::Compare {
                        predicate: ComparePredicate::Equal,
                        left,
                        right,
                    },
                    "!=" => InstructionKind::Compare {
                        predicate: ComparePredicate::NotEqual,
                        left,
                        right,
                    },
                    "<" => InstructionKind::Compare {
                        predicate: ComparePredicate::Less,
                        left,
                        right,
                    },
                    "<=" => InstructionKind::Compare {
                        predicate: ComparePredicate::LessEqual,
                        left,
                        right,
                    },
                    ">" => InstructionKind::Compare {
                        predicate: ComparePredicate::Greater,
                        left,
                        right,
                    },
                    ">=" => InstructionKind::Compare {
                        predicate: ComparePredicate::GreaterEqual,
                        left,
                        right,
                    },
                    _ => {
                        return Err(TypedExpressionLowerError::InvalidNode {
                            index: node_index,
                            message: "unsupported binary operator",
                        });
                    }
                };
                let value = ValueId::new(next_value);
                next_value += 1;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value,
                        ty: node_types[node_index],
                    }),
                    kind,
                    span: Some(spans[node_index]),
                });
                value
            }
            5 => {
                let function_id =
                    call_functions[node_index].ok_or(TypedExpressionLowerError::InvalidCall {
                        index: node_index,
                        message: "call signature was not lowered",
                    })?;
                let argument_nodes = call_argument_nodes[node_index].as_ref().ok_or(
                    TypedExpressionLowerError::InvalidCall {
                        index: node_index,
                        message: "call argument stream was not lowered",
                    },
                )?;
                let arguments = argument_nodes
                    .iter()
                    .map(|argument_index| node_values[*argument_index])
                    .collect();
                let value = ValueId::new(next_value);
                next_value += 1;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value,
                        ty: node_types[node_index],
                    }),
                    kind: InstructionKind::Call {
                        function: function_id,
                        arguments,
                    },
                    span: Some(spans[node_index]),
                });
                value
            }
            _ => unreachable!("validated syntax kind above"),
        };
        node_values[node_index] = value;
    }

    let root = ast.len() - 1;
    let main = Function {
        id: FunctionId::new(0),
        name: "__typed_expression".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: node_types[root],
        blocks: vec![Block {
            id: BlockId::new(0),
            parameters: Vec::new(),
            instructions,
            terminator: Terminator::Return {
                value: Some(node_values[root]),
            },
            span: Some(spans[root]),
        }],
        span: Some(spans[root]),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(main);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedExpressionLowerError::Verification(errors))
    }
}

/// Replaces matching caller-owned call imports with bounded same-module
/// definitions.  Each definition is lowered through the normal typed
/// expression path first, then its verified function body takes the import's
/// stable `FunctionId`. The operation is intentionally allocation-safe and
/// deterministic: a definition must match exactly one module function
/// signature and all body-call targets must resolve to an existing module
/// declaration. Body calls are remapped from temporary expression-module
/// identities to destination-module identities before verification.
///
/// This is the first self-hosting admission step beyond external C helpers;
/// it does not claim generic/control-flow bodies or aggregate values. A body
/// may call an imported or same-module declaration; recursion is accepted only
/// when the caller has already supplied a matching declaration. Callers that
/// do not provide definitions receive the input module unchanged.
pub fn materialize_typed_local_function_definitions(
    source: &str,
    source_id: SourceId,
    mut module: Module,
    definitions: &[TypedLocalFunctionDefinition],
) -> Result<Module, TypedExpressionLowerError> {
    for (definition_index, definition) in definitions.iter().enumerate() {
        let name_span = typed_expression_span(
            source,
            source_id,
            definition_index,
            definition.name_start,
            definition.name_end,
        )?;
        let body_span = typed_expression_span(
            source,
            source_id,
            definition_index,
            definition.body_start,
            definition.body_end,
        )?;
        if definition.return_type_kind != TYPE_KIND_INTEGER {
            return Err(TypedExpressionLowerError::UnsupportedType {
                index: definition_index,
                type_kind: definition.return_type_kind,
            });
        }
        if definition.ast.is_empty() {
            return Err(TypedExpressionLowerError::InvalidNode {
                index: definition_index,
                message: "same-module definition body AST is empty",
            });
        }
        let body_module = lower_typed_expression_ast(
            source,
            source_id,
            &definition.ast,
            &definition.parameters,
            &definition.call_bindings,
            &definition.arguments,
        )?;
        let body_function = &body_module.functions[0];
        let target_name = source[name_span.start..name_span.end].to_owned();
        let target_index = module
            .functions
            .iter()
            .position(|function| {
                function.linkage == Linkage::Import
                    && function.name == target_name
                    && function.parameters.len() == body_function.parameters.len()
                    && function
                        .parameters
                        .iter()
                        .zip(&body_function.parameters)
                        .all(|(target, body)| target.ty == body.ty)
                    && function.result == body_function.result
            })
            .ok_or(TypedExpressionLowerError::InvalidCall {
                index: definition_index,
                message: "same-module definition has no matching call import",
            })?;
        if body_function.result != TypeId::new(0)
            || body_function.result.index() >= module.types.len()
            || !matches!(
                module.types.get(body_function.result.index()),
                Some(Type::Integer {
                    signed: true,
                    bits: 32
                })
            )
        {
            return Err(TypedExpressionLowerError::InvalidCall {
                index: definition_index,
                message: "same-module definition uses an incompatible scalar result",
            });
        }
        let mut function_map = BTreeMap::<FunctionId, FunctionId>::new();
        for imported in body_module.functions.iter().skip(1) {
            let target = module
                .functions
                .iter()
                .find(|function| {
                    function.name == imported.name
                        && function.parameters.len() == imported.parameters.len()
                        && function
                            .parameters
                            .iter()
                            .zip(&imported.parameters)
                            .all(|(target, body)| target.ty == body.ty)
                        && function.result == imported.result
                })
                .ok_or(TypedExpressionLowerError::InvalidCall {
                    index: definition_index,
                    message: "same-module body call has no matching module declaration",
                })?;
            function_map.insert(imported.id, target.id);
        }
        let mut materialized = body_function.clone();
        materialized.id = module.functions[target_index].id;
        materialized.name = target_name;
        materialized.linkage = Linkage::Internal;
        materialized.span = Some(body_span);
        for block in &mut materialized.blocks {
            for instruction in &mut block.instructions {
                if let jadren_jir::InstructionKind::Call { function, .. } = &mut instruction.kind {
                    *function = function_map.get(function).copied().ok_or(
                        TypedExpressionLowerError::InvalidCall {
                            index: definition_index,
                            message: "same-module body call identity was not remapped",
                        },
                    )?;
                }
            }
        }
        module.functions[target_index] = materialized;
    }
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedExpressionLowerError::Verification(errors))
    }
}

/// Lowers a caller-owned straight-line statement sequence into one verified
/// JIR function named `__typed_statements`. The first statement/local slice
/// supports one homogeneous scalar family (`Int32` or `Float64`) with
/// `let name: T = expr;`, `name = expr;` and `return expr;`. Local storage is
/// explicit `StackAlloc` plus `Load`/`Store`, so a later assignment is a real
/// native mutation rather than an SSA-only alias. This compatibility entry
/// point keeps calls disabled; use
/// [`lower_typed_statement_sequence_with_calls`] for the additive call slice.
pub fn lower_typed_statement_sequence(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    statements: &[TypedStatementHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_statement_sequence_with_calls(
        source,
        source_id,
        ast,
        bindings,
        statements,
        &[],
        &[],
        &[],
    )
}

/// Lowers the bounded straight-line statement sequence with caller-owned
/// function signatures and expression argument records. This is an additive
/// extension of [`lower_typed_statement_sequence`]: call expressions may
/// occur in `let`, assignment and return initializers, but the sequence still
/// has no control-flow, shadowing, or user-defined local types. The sequence
/// is homogeneous over the existing `Int32` and `Float64` scalar families;
/// mixing them is rejected before lowering. `arguments` uses the same
/// post-order node indices and source spans as the typed AST; the helper
/// remaps records for each statement subtree before invoking the existing
/// expression lowerer.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_statement_sequence_with_calls(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    statements: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if statements.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "statement sequence is empty",
        });
    }
    if ast.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "statement sequence requires a typed expression AST",
        });
    }

    let value_kind = statements[0].type_kind;
    let (value_name, value_type, value_alignment) = match value_kind {
        TYPE_KIND_INTEGER => (
            "Int32",
            Type::Integer {
                signed: true,
                bits: 32,
            },
            4,
        ),
        TYPE_KIND_FLOAT => ("Float64", Type::Float { bits: 64 }, 8),
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "statement sequence must use Int32 or Float64",
            });
        }
    };
    let value_type_id = TypeId::new(0);
    let mut types = vec![value_type.clone()];
    let mut parameters = Vec::with_capacity(bindings.len());
    let mut parameter_indices = BTreeMap::<String, usize>::new();
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != value_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "statement parameters must match the homogeneous scalar type",
            });
        }
        let span =
            typed_statement_span(source, source_id, binding.name_start, binding.name_end, 0)?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || parameter_indices.insert(name.clone(), index).is_some()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "statement parameter names must be unique ASCII identifiers",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: value_type_id,
            name: Some(name),
        });
    }

    let mut locals = BTreeMap::<String, TypedStatementLocal>::new();
    let mut instructions = Vec::new();
    let mut imports = Vec::<Function>::new();
    let mut next_value = parameters.len();
    let mut return_value = None;
    let mut first_span = None;
    let mut last_span = None;

    for (statement_index, statement) in statements.iter().enumerate() {
        if statement.reserved != 0 {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "statement reserved bytes must be zero",
            });
        }
        let statement_span = typed_statement_span(
            source,
            source_id,
            statement.start,
            statement.end,
            statement_index,
        )?;
        if first_span.is_none() {
            first_span = Some(statement_span);
        }
        last_span = Some(statement_span);
        let expression_index = usize::try_from(statement.expression_node).map_err(|_| {
            TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "statement expression index is not representable",
            }
        })?;
        if expression_index >= ast.len() {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "statement expression index is outside the typed AST",
            });
        }
        let expression_span = typed_statement_span(
            source,
            source_id,
            ast[expression_index].start,
            ast[expression_index].end,
            statement_index,
        )?;
        if expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || ast[expression_index].flags != 1
            || ast[expression_index].type_kind != statement.type_kind
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "statement expression is unresolved, out of range or has a mismatched type",
            });
        }
        if statement.type_kind != value_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "all statements must use the same Int32 or Float64 scalar type",
            });
        }

        let target = match statement.kind {
            TYPED_STATEMENT_KIND_LET | TYPED_STATEMENT_KIND_ASSIGN => {
                let target_span = typed_statement_span(
                    source,
                    source_id,
                    statement.target_start,
                    statement.target_end,
                    statement_index,
                )?;
                if target_span.start < statement_span.start || target_span.end > statement_span.end
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "statement target is outside its statement span",
                    });
                }
                Some((
                    target_span,
                    source[target_span.start..target_span.end].to_owned(),
                ))
            }
            TYPED_STATEMENT_KIND_RETURN => {
                if statement.target_start != 0 || statement.target_end != 0 || statement.flags != 0
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "return statement must not carry a target or flags",
                    });
                }
                None
            }
            _ => {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "unsupported statement kind",
                });
            }
        };

        if statement.kind == TYPED_STATEMENT_KIND_RETURN && statement_index + 1 != statements.len()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "return must be the final straight-line statement",
            });
        }
        if let Some((target_span, target_name)) = target.as_ref() {
            if !typed_statement_identifier(target_name)
                || parameter_indices.contains_key(target_name)
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "statement target must be a unique non-parameter ASCII identifier",
                });
            }
            let prefix = source[statement_span.start..expression_span.start].trim();
            let suffix = source[expression_span.end..statement_span.end].trim();
            let expected_prefix = if statement.kind == TYPED_STATEMENT_KIND_LET {
                format!("let {target_name}: {value_name} =")
            } else {
                format!("{target_name} =")
            };
            if prefix != expected_prefix || suffix != ";" {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "statement source span does not match its declared syntax",
                });
            }
            if statement.kind == TYPED_STATEMENT_KIND_LET {
                if locals.contains_key(target_name) {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "local redeclaration/shadowing is not supported",
                    });
                }
            } else {
                let Some(local) = locals.get(target_name) else {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "assignment target has no preceding local declaration",
                    });
                };
                if !local.mutable {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "assignment target is immutable",
                    });
                }
            }
            let _ = target_span;
        } else {
            let prefix = source[statement_span.start..expression_span.start].trim();
            let suffix = source[expression_span.end..statement_span.end].trim();
            if prefix != "return" || suffix != ";" {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "return source span does not match its declared syntax",
                });
            }
        }

        let mut visible_bindings = bindings.to_vec();
        for local in locals.values() {
            visible_bindings.push(TypedNameBindingHeader {
                name_start: local.declaration.start as u64,
                name_end: local.declaration.end as u64,
                type_kind: value_kind,
            });
        }
        let (expression_ast, subtree_remap) =
            typed_statement_expression_subtree(ast, expression_index, arguments).map_err(
                |error| TypedStatementLowerError::Expression {
                    index: statement_index,
                    error,
                },
            )?;
        let expression_arguments =
            typed_statement_expression_arguments(arguments, &subtree_remap, statement_index)
                .map_err(|error| TypedStatementLowerError::Expression {
                    index: statement_index,
                    error,
                })?;
        let expression_module = lower_typed_expression_ast_with_arrays_and_sequences(
            source,
            source_id,
            &expression_ast,
            &visible_bindings,
            &[],
            &[],
            call_bindings,
            call_candidates,
            &expression_arguments,
        )
        .map_err(|error| TypedStatementLowerError::Expression {
            index: statement_index,
            error,
        })?;
        let expression_function = expression_module.functions.first().ok_or(
            TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "expression lowering returned no function",
            },
        )?;
        let type_map = typed_statement_merge_module_types(&mut types, &expression_module.types);
        let mut value_map = BTreeMap::<ValueId, ValueId>::new();
        for parameter in &expression_function.parameters {
            let Some(name) = parameter.name.as_deref() else {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "expression parameter is missing its source name",
                });
            };
            if let Some(parameter_index) = parameter_indices.get(name).copied() {
                value_map.insert(parameter.value, ValueId::new(parameter_index));
            } else if let Some(local) = locals.get(name) {
                let value = ValueId::new(next_value);
                next_value += 1;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value,
                        ty: value_type_id,
                    }),
                    kind: InstructionKind::Load {
                        pointer: local.pointer,
                        alignment: value_alignment,
                        volatile: false,
                    },
                    span: Some(expression_span),
                });
                value_map.insert(parameter.value, value);
            } else {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "expression references a local that is not visible",
                });
            }
        }

        let mut function_map = BTreeMap::<FunctionId, FunctionId>::new();
        for imported in expression_module.functions.iter().skip(1) {
            let mapped_parameters = imported
                .parameters
                .iter()
                .map(|parameter| Parameter {
                    value: parameter.value,
                    ty: type_map[&parameter.ty],
                    name: parameter.name.clone(),
                })
                .collect::<Vec<_>>();
            let mapped_result = type_map[&imported.result];
            let function_id = if let Some(existing) = imports.iter().find(|function| {
                function.name == imported.name
                    && function.result == mapped_result
                    && function
                        .parameters
                        .iter()
                        .map(|parameter| parameter.ty)
                        .eq(mapped_parameters.iter().map(|parameter| parameter.ty))
            }) {
                existing.id
            } else {
                let id = FunctionId::new(imports.len() + 1);
                imports.push(Function {
                    id,
                    name: imported.name.clone(),
                    linkage: imported.linkage,
                    parameters: mapped_parameters,
                    result: mapped_result,
                    blocks: Vec::new(),
                    span: imported.span,
                });
                id
            };
            function_map.insert(imported.id, function_id);
        }

        for instruction in &expression_function.blocks[0].instructions {
            let kind = typed_statement_remap_instruction(
                &instruction.kind,
                &value_map,
                &function_map,
                &type_map,
                statement_index,
            )?;
            let result = instruction.result.map(|result| {
                let value = ValueId::new(next_value);
                next_value += 1;
                value_map.insert(result.value, value);
                TypedValue {
                    value,
                    ty: type_map[&result.ty],
                }
            });
            instructions.push(Instruction {
                result,
                kind,
                span: instruction.span,
            });
        }
        let expression_value = match expression_function.blocks[0].terminator {
            Terminator::Return { value: Some(value) } => value_map.get(&value).copied().ok_or(
                TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "expression return value was not remapped",
                },
            )?,
            _ => {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "expression lowering did not produce a scalar return",
                });
            }
        };

        match statement.kind {
            TYPED_STATEMENT_KIND_LET => {
                let (declaration, name) = target.expect("let target validated above");
                let pointer = ValueId::new(next_value);
                next_value += 1;
                let pointer_type = typed_statement_merge_type(
                    &mut types,
                    Type::Pointer {
                        pointee: value_type_id,
                        address_space: AddressSpace::Stack,
                    },
                );
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value: pointer,
                        ty: pointer_type,
                    }),
                    kind: InstructionKind::StackAlloc {
                        ty: value_type_id,
                        count: None,
                    },
                    span: Some(statement_span),
                });
                instructions.push(Instruction {
                    result: None,
                    kind: InstructionKind::Store {
                        pointer,
                        value: expression_value,
                        alignment: value_alignment,
                        volatile: false,
                    },
                    span: Some(statement_span),
                });
                locals.insert(
                    name.clone(),
                    TypedStatementLocal {
                        declaration,
                        pointer,
                        mutable: statement.flags == TYPED_STATEMENT_FLAG_MUTABLE,
                    },
                );
            }
            TYPED_STATEMENT_KIND_ASSIGN => {
                let (_, name) = target.expect("assignment target validated above");
                let local = locals.get(&name).expect("assignment local validated above");
                instructions.push(Instruction {
                    result: None,
                    kind: InstructionKind::Store {
                        pointer: local.pointer,
                        value: expression_value,
                        alignment: value_alignment,
                        volatile: false,
                    },
                    span: Some(statement_span),
                });
            }
            TYPED_STATEMENT_KIND_RETURN => return_value = Some(expression_value),
            _ => unreachable!("statement kind validated above"),
        }
    }

    let return_value = return_value.ok_or(TypedStatementLowerError::InvalidStatement {
        index: statements.len() - 1,
        message: "statement sequence must end with return",
    })?;
    let main_span = first_span
        .zip(last_span)
        .and_then(|(first, last)| Span::new(source_id, first.start, last.end));
    let main = Function {
        id: FunctionId::new(0),
        name: "__typed_statements".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: value_type_id,
        blocks: vec![Block {
            id: BlockId::new(0),
            parameters: Vec::new(),
            instructions,
            terminator: Terminator::Return {
                value: Some(return_value),
            },
            span: main_span,
        }],
        span: main_span,
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(main);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers one bounded `if condition { then } else { otherwise }` expression
/// into a three-block JIR function that returns directly from both branches.
/// The condition must be a `Bool`, both branch roots must use one homogeneous
/// `Int32` or `Float64` scalar family, and all
/// expression data remains caller-owned. This is intentionally an additive
/// control-flow slice: it does not yet merge mutable locals, create phi-like
/// block parameters, support loops, or lower a statement after the branch.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_return(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    header: &TypedIfReturnHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if header.kind != TYPED_CONTROL_FLOW_KIND_IF_RETURN {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "unsupported typed control-flow kind",
        });
    }
    if header.reserved != [0; 6] {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed control-flow reserved bytes must be zero",
        });
    }
    if header.type_kind != TYPE_KIND_INTEGER && header.type_kind != TYPE_KIND_FLOAT {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-return result must be Int32 or Float64",
        });
    }
    let header_span = typed_statement_span(source, source_id, header.start, header.end, 0)?;
    if ast.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-return requires a typed expression AST",
        });
    }

    let result_type = match header.type_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => unreachable!("validated typed if-return scalar kind"),
    };
    let bool_type = Type::Bool;
    let result_type_id = TypeId::new(0);
    let bool_type_id = TypeId::new(1);
    let mut types = vec![result_type, bool_type];
    let mut parameters = Vec::with_capacity(bindings.len());
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != header.type_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return parameters must match the selected scalar type",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name) || parameter_values.contains_key(&name) {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return parameter names must be unique ASCII identifiers",
            });
        }
        let value = ValueId::new(parameters.len());
        parameter_values.insert(name.clone(), value);
        parameters.push(Parameter {
            value,
            ty: result_type_id,
            name: Some(name),
        });
    }

    let roots = [header.condition_node, header.then_node, header.else_node];
    let mut root_indices = Vec::with_capacity(roots.len());
    let mut root_spans = Vec::new();
    for (index, root) in roots.into_iter().enumerate() {
        let root =
            usize::try_from(root).map_err(|_| TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return expression node is not representable",
            })?;
        let Some(node) = ast.get(root) else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return expression node is outside the AST",
            });
        };
        if node.flags != 1 {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return expression node is unresolved",
            });
        }
        let span = typed_statement_span(source, source_id, node.start, node.end, index)?;
        if span.start < header_span.start || span.end > header_span.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed if-return expression is outside its control-flow span",
            });
        }
        root_indices.push(root);
        root_spans.push(span);
    }
    if ast[root_indices[0]].type_kind != TYPE_KIND_BOOL {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-return condition must be Bool",
        });
    }
    if ast[root_indices[1]].type_kind != header.type_kind
        || ast[root_indices[2]].type_kind != header.type_kind
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed if-return branches must match the selected scalar type",
        });
    }
    let condition_prefix = source[header_span.start..root_spans[0].start].trim();
    let condition_then = source[root_spans[0].end..root_spans[1].start].trim();
    let then_else = source[root_spans[1].end..root_spans[2].start].trim();
    let else_suffix = source[root_spans[2].end..header_span.end].trim();
    if condition_prefix != "if"
        || condition_then != "{"
        || then_else != "} else {"
        || else_suffix != "}"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "if-return source span does not match `if condition { then } else { otherwise }`",
        });
    }

    let mut imports = Vec::<Function>::new();
    let mut entry_instructions = Vec::new();
    let mut then_instructions = Vec::new();
    let mut else_instructions = Vec::new();
    let mut next_value = parameters.len();
    let condition_value = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        header.condition_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if condition_value.1 != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-return condition lowering did not produce Bool",
        });
    }
    let then_value = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        header.then_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut then_instructions,
        &mut next_value,
        1,
    )?;
    let else_value = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        header.else_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut else_instructions,
        &mut next_value,
        2,
    )?;
    if then_value.1 != result_type_id || else_value.1 != result_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed if-return branch lowering did not produce the selected scalar type",
        });
    }

    let main = Function {
        id: FunctionId::new(0),
        name: "__typed_if_return".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: result_type_id,
        blocks: vec![
            Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions: entry_instructions,
                terminator: Terminator::Branch {
                    condition: condition_value.0,
                    then_target: BlockId::new(1),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(2),
                    else_arguments: Vec::new(),
                },
                span: Some(header_span),
            },
            Block {
                id: BlockId::new(1),
                parameters: Vec::new(),
                instructions: then_instructions,
                terminator: Terminator::Return {
                    value: Some(then_value.0),
                },
                span: Some(root_spans[1]),
            },
            Block {
                id: BlockId::new(2),
                parameters: Vec::new(),
                instructions: else_instructions,
                terminator: Terminator::Return {
                    value: Some(else_value.0),
                },
                span: Some(root_spans[2]),
            },
        ],
        span: Some(header_span),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(main);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers the same bounded `if ... else ...` form through a real join block.
/// Both branch values are passed as edge arguments to one JIR
/// [`BlockParameter`], and the join returns that parameter. This is the first
/// Stage-2 value merge; mutable locals, statements after the join and loops
/// remain separate contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_value(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    header: &TypedIfReturnHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-value header has an unsupported control-flow kind",
        });
    }
    let mut direct_header = *header;
    direct_header.kind = TYPED_CONTROL_FLOW_KIND_IF_RETURN;
    let mut module = lower_typed_if_return(
        source,
        source_id,
        ast,
        bindings,
        &direct_header,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let function =
        module
            .functions
            .first_mut()
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed if-value lowering returned no function",
            })?;
    if function.blocks.len() != 3 {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed if-value lowering expected a three-block CFG",
        });
    }
    let then_value = match function.blocks[1].terminator {
        Terminator::Return { value: Some(value) } => value,
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 1,
                message: "typed if-value then block did not return a value",
            });
        }
    };
    let else_value = match function.blocks[2].terminator {
        Terminator::Return { value: Some(value) } => value,
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 2,
                message: "typed if-value else block did not return a value",
            });
        }
    };
    let mut next_value = function
        .parameters
        .iter()
        .map(|parameter| parameter.value.index() + 1)
        .max()
        .unwrap_or(0);
    for block in &function.blocks {
        for parameter in &block.parameters {
            next_value = next_value.max(parameter.value.index() + 1);
        }
        for instruction in &block.instructions {
            if let Some(result) = instruction.result {
                next_value = next_value.max(result.value.index() + 1);
            }
        }
    }
    let join_value = ValueId::new(next_value);
    let result_type = function.result;
    function.blocks[1].terminator = Terminator::Jump {
        target: BlockId::new(3),
        arguments: vec![then_value],
    };
    function.blocks[2].terminator = Terminator::Jump {
        target: BlockId::new(3),
        arguments: vec![else_value],
    };
    function.blocks.push(Block {
        id: BlockId::new(3),
        parameters: vec![BlockParameter {
            value: join_value,
            ty: result_type,
        }],
        instructions: Vec::new(),
        terminator: Terminator::Return {
            value: Some(join_value),
        },
        span: function.span,
    });
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_if_value`] with one expression evaluated in the join
/// block. When `continuation_binding` is supplied, its source name is mapped
/// to the merged block parameter, allowing a following expression such as
/// `value + 1` to read the branch result without inventing an SSA alias. The
/// continuation must use the same homogeneous `Int32` or `Float64` scalar as
/// the `if` result and its root appears after the `if` span in the caller-owned
/// AST. This remains a single post-join
/// expression, not a general statement list or mutable-local merge.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_value_with_continuation(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    if_header: &TypedIfReturnHeader,
    continuation_binding: Option<&TypedNameBindingHeader>,
    continuation_node: u64,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed continuation requires an if-value header",
        });
    }
    let if_module = lower_typed_if_value(
        source,
        source_id,
        ast,
        bindings,
        if_header,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let continuation_index = usize::try_from(continuation_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed continuation expression node is not representable",
        }
    })?;
    let continuation_ast =
        ast.get(continuation_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed continuation expression node is outside the AST",
            })?;
    if continuation_ast.flags != 1 || continuation_ast.type_kind != if_header.type_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed continuation expression must match the if-value scalar type",
        });
    }
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let continuation_span = typed_statement_span(
        source,
        source_id,
        continuation_ast.start,
        continuation_ast.end,
        1,
    )?;
    if continuation_span.start < if_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed continuation expression must follow the if span",
        });
    }

    let mut module = if_module;
    let mut function =
        module
            .functions
            .drain(..1)
            .next()
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed continuation lowering returned no function",
            })?;
    let mut imports = module.functions;
    let mut types = module.types;
    let join_value = function
        .blocks
        .get(3)
        .and_then(|block| block.parameters.first())
        .map(|parameter| parameter.value)
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed continuation requires a merged join parameter",
        })?;
    let mut next_value = function
        .parameters
        .iter()
        .map(|parameter| parameter.value.index() + 1)
        .max()
        .unwrap_or(0);
    for block in &function.blocks {
        for parameter in &block.parameters {
            next_value = next_value.max(parameter.value.index() + 1);
        }
        for instruction in &block.instructions {
            if let Some(result) = instruction.result {
                next_value = next_value.max(result.value.index() + 1);
            }
        }
    }
    let mut continuation_bindings = bindings.to_vec();
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for parameter in &function.parameters {
        let Some(name) = parameter.name.as_deref() else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed continuation function parameter is missing its source name",
            });
        };
        parameter_values.insert(name.to_owned(), parameter.value);
    }
    if let Some(binding) = continuation_binding {
        if binding.type_kind != if_header.type_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 1,
                message: "typed continuation binding must match the if-value scalar type",
            });
        }
        let span =
            typed_statement_span(source, source_id, binding.name_start, binding.name_end, 1)?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name) || parameter_values.contains_key(&name) {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 1,
                message: "typed continuation binding must be a unique ASCII identifier",
            });
        }
        continuation_bindings.push(*binding);
        parameter_values.insert(name, join_value);
    }
    let mut continuation_instructions = Vec::new();
    let (return_value, return_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        continuation_node,
        &continuation_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut continuation_instructions,
        &mut next_value,
        1,
    )?;
    if return_type != function.result {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed continuation result differs from the if-value result type",
        });
    }
    let join_block =
        function
            .blocks
            .get_mut(3)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed continuation join block is missing",
            })?;
    join_block.instructions = continuation_instructions;
    join_block.terminator = Terminator::Return {
        value: Some(return_value),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    module.types = types;
    module.functions = functions;
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers the bounded `if/else` value through an explicit stack local. Each
/// branch stores its value into the same `StackAlloc`, both edges jump to a
/// join block, and the join performs one `Load` for the function result. This
/// is the first branch-local mutation contract; it deliberately does not yet
/// expose a following assignment or a general statement list.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_value_to_local(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    header: &TypedIfReturnHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local merge requires an if-value header",
        });
    }
    let mut direct_header = *header;
    direct_header.kind = TYPED_CONTROL_FLOW_KIND_IF_RETURN;
    let mut module = lower_typed_if_return(
        source,
        source_id,
        ast,
        bindings,
        &direct_header,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let result_type = module
        .functions
        .first()
        .map(|function| function.result)
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local merge returned no function",
        })?;
    let result_alignment = match module.types.get(result_type.index()) {
        Some(Type::Integer { bits: 32, .. }) => 4,
        Some(Type::Float { bits: 64 }) => 8,
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local merge result must be Int32 or Float64",
            });
        }
    };
    let pointer_type = typed_statement_merge_type(
        &mut module.types,
        Type::Pointer {
            pointee: result_type,
            address_space: AddressSpace::Stack,
        },
    );
    let function =
        module
            .functions
            .first_mut()
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local merge returned no mutable function",
            })?;
    if function.blocks.len() != 3 {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local merge expected a three-block CFG",
        });
    }
    let then_value = match function.blocks[1].terminator {
        Terminator::Return { value: Some(value) } => value,
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 1,
                message: "typed local merge then block did not return a value",
            });
        }
    };
    let else_value = match function.blocks[2].terminator {
        Terminator::Return { value: Some(value) } => value,
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 2,
                message: "typed local merge else block did not return a value",
            });
        }
    };
    let mut next_value = function
        .parameters
        .iter()
        .map(|parameter| parameter.value.index() + 1)
        .max()
        .unwrap_or(0);
    for block in &function.blocks {
        for parameter in &block.parameters {
            next_value = next_value.max(parameter.value.index() + 1);
        }
        for instruction in &block.instructions {
            if let Some(result) = instruction.result {
                next_value = next_value.max(result.value.index() + 1);
            }
        }
    }
    let pointer = ValueId::new(next_value);
    next_value += 1;
    let function_span = function.span;
    let then_span = function.blocks[1].span;
    let else_span = function.blocks[2].span;
    function.blocks[0].instructions.push(Instruction {
        result: Some(TypedValue {
            value: pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: result_type,
            count: None,
        },
        span: function_span,
    });
    function.blocks[1].instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: then_value,
            alignment: result_alignment,
            volatile: false,
        },
        span: then_span,
    });
    function.blocks[1].terminator = Terminator::Jump {
        target: BlockId::new(3),
        arguments: Vec::new(),
    };
    function.blocks[2].instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: else_value,
            alignment: result_alignment,
            volatile: false,
        },
        span: else_span,
    });
    function.blocks[2].terminator = Terminator::Jump {
        target: BlockId::new(3),
        arguments: Vec::new(),
    };
    let loaded = ValueId::new(next_value);
    function.blocks.push(Block {
        id: BlockId::new(3),
        parameters: Vec::new(),
        instructions: vec![Instruction {
            result: Some(TypedValue {
                value: loaded,
                ty: result_type,
            }),
            kind: InstructionKind::Load {
                pointer,
                alignment: result_alignment,
                volatile: false,
            },
            span: function_span,
        }],
        terminator: Terminator::Return {
            value: Some(loaded),
        },
        span: function_span,
    });
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_if_value_to_local`] with one assignment in the join
/// block. The caller-owned continuation expression may read the local name,
/// its result is stored back into the same stack slot, and that result is
/// returned. This is intentionally one assignment; general statement lists,
/// later reads and loops remain separate contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_value_to_local_with_assignment(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    if_header: &TypedIfReturnHeader,
    continuation_binding: Option<&TypedNameBindingHeader>,
    continuation_node: u64,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local assignment requires an if-value header",
        });
    }
    let mut module = lower_typed_if_value_to_local(
        source,
        source_id,
        ast,
        bindings,
        if_header,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let continuation_index = usize::try_from(continuation_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local assignment expression node is not representable",
        }
    })?;
    let continuation_ast =
        ast.get(continuation_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local assignment expression node is outside the AST",
            })?;
    if continuation_ast.flags != 1 || continuation_ast.type_kind != TYPE_KIND_INTEGER {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local assignment expression must resolve to Int32",
        });
    }
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let continuation_span = typed_statement_span(
        source,
        source_id,
        continuation_ast.start,
        continuation_ast.end,
        1,
    )?;
    if continuation_span.start < if_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed local assignment expression must follow the if span",
        });
    }
    let continuation_binding =
        continuation_binding.ok_or(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed local assignment requires a caller-owned local binding",
        })?;

    let mut function =
        module
            .functions
            .drain(..1)
            .next()
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local assignment returned no function",
            })?;
    let mut imports = module.functions;
    let mut types = module.types;
    let pointer = function.blocks[0]
        .instructions
        .iter()
        .find_map(|instruction| match &instruction.kind {
            InstructionKind::StackAlloc { .. } => instruction.result.map(|result| result.value),
            _ => None,
        })
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local assignment could not find its stack slot",
        })?;
    let loaded = function
        .blocks
        .get(3)
        .and_then(|block| {
            block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    InstructionKind::Load {
                        pointer: candidate, ..
                    } if *candidate == pointer => instruction.result.map(|result| result.value),
                    _ => None,
                })
        })
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local assignment could not find the join load",
        })?;
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for parameter in &function.parameters {
        let Some(name) = parameter.name.as_deref() else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local assignment parameter is missing its source name",
            });
        };
        parameter_values.insert(name.to_owned(), parameter.value);
    }
    if continuation_binding.type_kind != TYPE_KIND_INTEGER {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed local assignment binding must be Int32",
        });
    }
    let binding_span = typed_statement_span(
        source,
        source_id,
        continuation_binding.name_start,
        continuation_binding.name_end,
        1,
    )?;
    let binding_name = source[binding_span.start..binding_span.end].to_owned();
    if !typed_statement_identifier(&binding_name) || parameter_values.contains_key(&binding_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed local assignment binding must be a unique ASCII identifier",
        });
    }
    parameter_values.insert(binding_name, loaded);
    let mut continuation_bindings = bindings.to_vec();
    continuation_bindings.push(*continuation_binding);
    let mut next_value = function
        .parameters
        .iter()
        .map(|parameter| parameter.value.index() + 1)
        .max()
        .unwrap_or(0);
    for block in &function.blocks {
        for parameter in &block.parameters {
            next_value = next_value.max(parameter.value.index() + 1);
        }
        for instruction in &block.instructions {
            if let Some(result) = instruction.result {
                next_value = next_value.max(result.value.index() + 1);
            }
        }
    }
    let mut continuation_instructions = Vec::new();
    let (assigned_value, assigned_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        continuation_node,
        &continuation_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut continuation_instructions,
        &mut next_value,
        1,
    )?;
    if assigned_type != function.result {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed local assignment result differs from Int32 local type",
        });
    }
    let join_block =
        function
            .blocks
            .get_mut(3)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local assignment join block is missing",
            })?;
    join_block.instructions.extend(continuation_instructions);
    join_block.instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: assigned_value,
            alignment: 4,
            volatile: false,
        },
        span: join_block.span,
    });
    join_block.terminator = Terminator::Return {
        value: Some(assigned_value),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    module.types = types;
    module.functions = functions;
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_if_value_to_local`] with a bounded post-join
/// statement tail. The tail may contain one or more assignments to the
/// caller-owned merged local and must end with a `return`; each assignment is
/// lowered in source order and stored back into the same stack slot. This is
/// the first multi-statement CFG hand-off; declarations, shadowing, loops and
/// user-defined local types remain separate contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_value_to_local_with_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    if_header: &TypedIfReturnHeader,
    continuation_binding: Option<&TypedNameBindingHeader>,
    statements: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local statement tail requires an if-value header",
        });
    }
    if statements.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local statement tail is empty",
        });
    }
    let continuation_binding =
        continuation_binding.ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local statement tail requires a merged local binding",
        })?;
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let mut module = lower_typed_if_value_to_local(
        source,
        source_id,
        ast,
        bindings,
        if_header,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let mut function =
        module
            .functions
            .drain(..1)
            .next()
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local statement tail returned no function",
            })?;
    let mut imports = module.functions;
    let mut types = module.types;
    let pointer = function.blocks[0]
        .instructions
        .iter()
        .find_map(|instruction| match &instruction.kind {
            InstructionKind::StackAlloc { .. } => instruction.result.map(|result| result.value),
            _ => None,
        })
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local statement tail could not find its stack slot",
        })?;
    let loaded = function
        .blocks
        .get(3)
        .and_then(|block| {
            block
                .instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    InstructionKind::Load {
                        pointer: candidate, ..
                    } if *candidate == pointer => instruction.result.map(|result| result.value),
                    _ => None,
                })
        })
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed local statement tail could not find the join load",
        })?;

    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for parameter in &function.parameters {
        let Some(name) = parameter.name.as_deref() else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local statement tail parameter is missing its source name",
            });
        };
        parameter_values.insert(name.to_owned(), parameter.value);
    }
    if continuation_binding.type_kind != TYPE_KIND_INTEGER {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "merged local binding must be Int32",
        });
    }
    let binding_span = typed_statement_span(
        source,
        source_id,
        continuation_binding.name_start,
        continuation_binding.name_end,
        0,
    )?;
    let binding_name = source[binding_span.start..binding_span.end].to_owned();
    if !typed_statement_identifier(&binding_name) || parameter_values.contains_key(&binding_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "merged local binding must be a unique ASCII identifier",
        });
    }
    parameter_values.insert(binding_name.clone(), loaded);
    let mut visible_bindings = bindings.to_vec();
    visible_bindings.push(*continuation_binding);
    let mut locals = BTreeMap::<String, TypedStatementLocal>::new();
    locals.insert(
        binding_name.clone(),
        TypedStatementLocal {
            declaration: binding_span,
            pointer,
            mutable: true,
        },
    );

    let mut next_value = function
        .parameters
        .iter()
        .map(|parameter| parameter.value.index() + 1)
        .max()
        .unwrap_or(0);
    for block in &function.blocks {
        for parameter in &block.parameters {
            next_value = next_value.max(parameter.value.index() + 1);
        }
        for instruction in &block.instructions {
            if let Some(result) = instruction.result {
                next_value = next_value.max(result.value.index() + 1);
            }
        }
    }

    let mut join_instructions = Vec::new();
    let mut return_value = None;
    for (statement_index, statement) in statements.iter().enumerate() {
        if statement.reserved != 0 {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join statement reserved byte must be zero",
            });
        }
        let statement_span = typed_statement_span(
            source,
            source_id,
            statement.start,
            statement.end,
            statement_index,
        )?;
        if statement_span.start < if_span.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join statement must follow the if span",
            });
        }
        if statement.type_kind != TYPE_KIND_INTEGER {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join statement values must use Int32",
            });
        }
        let expression_index = usize::try_from(statement.expression_node).map_err(|_| {
            TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join expression node is not representable",
            }
        })?;
        let expression_ast =
            ast.get(expression_index)
                .ok_or(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "post-join expression node is outside the AST",
                })?;
        let expression_span = typed_statement_span(
            source,
            source_id,
            expression_ast.start,
            expression_ast.end,
            statement_index,
        )?;
        if expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || expression_ast.flags != 1
            || expression_ast.type_kind != TYPE_KIND_INTEGER
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join expression is unresolved, out of range or has a mismatched type",
            });
        }

        let target = match statement.kind {
            TYPED_STATEMENT_KIND_LET => {
                if statement.flags & !TYPED_STATEMENT_FLAG_MUTABLE != 0 {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join let carries unsupported flags",
                    });
                }
                let target_span = typed_statement_span(
                    source,
                    source_id,
                    statement.target_start,
                    statement.target_end,
                    statement_index,
                )?;
                if target_span.start < statement_span.start || target_span.end > statement_span.end
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join let target is outside its statement span",
                    });
                }
                let target_name = &source[target_span.start..target_span.end];
                if !typed_statement_identifier(target_name)
                    || parameter_values.contains_key(target_name)
                    || locals.contains_key(target_name)
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join let target must be a unique ASCII identifier",
                    });
                }
                let prefix = source[statement_span.start..expression_span.start].trim();
                let suffix = source[expression_span.end..statement_span.end].trim();
                if prefix != format!("let {target_name}: Int32 =") || suffix != ";" {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join let source span does not match its syntax",
                    });
                }
                Some((target_name.to_owned(), target_span))
            }
            TYPED_STATEMENT_KIND_ASSIGN => {
                if statement.flags != 0 {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join assignment flags must be zero",
                    });
                }
                let target_span = typed_statement_span(
                    source,
                    source_id,
                    statement.target_start,
                    statement.target_end,
                    statement_index,
                )?;
                if target_span.start < statement_span.start || target_span.end > statement_span.end
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join assignment target is outside its statement span",
                    });
                }
                let target_name = &source[target_span.start..target_span.end];
                let Some(local) = locals.get(target_name) else {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join assignment target has no preceding local",
                    });
                };
                if !local.mutable {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join assignment target is immutable",
                    });
                }
                let prefix = source[statement_span.start..expression_span.start].trim();
                let suffix = source[expression_span.end..statement_span.end].trim();
                if prefix != format!("{target_name} =") || suffix != ";" {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join assignment source span does not match its syntax",
                    });
                }
                Some((target_name.to_owned(), target_span))
            }
            TYPED_STATEMENT_KIND_RETURN => {
                if statement.flags != 0 || statement.target_start != 0 || statement.target_end != 0
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join return must not carry a target or flags",
                    });
                }
                if statement_index + 1 != statements.len() {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join return must be the final statement",
                    });
                }
                let prefix = source[statement_span.start..expression_span.start].trim();
                let suffix = source[expression_span.end..statement_span.end].trim();
                if prefix != "return" || suffix != ";" {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "post-join return source span does not match its syntax",
                    });
                }
                None
            }
            _ => {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "post-join tail supports only assignment and return",
                });
            }
        };

        let (value, value_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            statement.expression_node,
            &visible_bindings,
            call_bindings,
            call_candidates,
            arguments,
            &parameter_values,
            &mut types,
            &mut imports,
            &mut join_instructions,
            &mut next_value,
            statement_index,
        )?;
        if value_type != function.result {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: statement_index,
                message: "post-join expression result differs from Int32 function type",
            });
        }
        match statement.kind {
            TYPED_STATEMENT_KIND_LET => {
                let (name, declaration) = target.expect("post-join let target validated above");
                let pointer_type = typed_statement_merge_type(
                    &mut types,
                    Type::Pointer {
                        pointee: function.result,
                        address_space: AddressSpace::Stack,
                    },
                );
                let local_pointer = ValueId::new(next_value);
                next_value += 1;
                join_instructions.push(Instruction {
                    result: Some(TypedValue {
                        value: local_pointer,
                        ty: pointer_type,
                    }),
                    kind: InstructionKind::StackAlloc {
                        ty: function.result,
                        count: None,
                    },
                    span: Some(statement_span),
                });
                join_instructions.push(Instruction {
                    result: None,
                    kind: InstructionKind::Store {
                        pointer: local_pointer,
                        value,
                        alignment: 4,
                        volatile: false,
                    },
                    span: Some(statement_span),
                });
                parameter_values.insert(name.clone(), value);
                locals.insert(
                    name,
                    TypedStatementLocal {
                        declaration,
                        pointer: local_pointer,
                        mutable: statement.flags & TYPED_STATEMENT_FLAG_MUTABLE != 0,
                    },
                );
                visible_bindings.push(TypedNameBindingHeader {
                    name_start: declaration.start as u64,
                    name_end: declaration.end as u64,
                    type_kind: TYPE_KIND_INTEGER,
                });
            }
            TYPED_STATEMENT_KIND_ASSIGN => {
                let (name, _) = target.expect("post-join assignment target validated above");
                let pointer = locals
                    .get(&name)
                    .expect("post-join assignment local validated above")
                    .pointer;
                join_instructions.push(Instruction {
                    result: None,
                    kind: InstructionKind::Store {
                        pointer,
                        value,
                        alignment: 4,
                        volatile: false,
                    },
                    span: Some(statement_span),
                });
                parameter_values.insert(name, value);
            }
            TYPED_STATEMENT_KIND_RETURN => return_value = Some(value),
            _ => unreachable!("post-join statement kind validated above"),
        }
    }

    let return_value = return_value.ok_or(TypedStatementLowerError::InvalidStatement {
        index: statements.len() - 1,
        message: "post-join statement tail must end with return",
    })?;
    let join_block =
        function
            .blocks
            .get_mut(3)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed local statement tail join block is missing",
            })?;
    join_block.instructions.extend(join_instructions);
    join_block.terminator = Terminator::Return {
        value: Some(return_value),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    module.types = types;
    module.functions = functions;
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers a bounded statement-shaped `if` that mutates one local in both
/// branches and returns that local after the join. The accepted source form is
/// `var value: Int32 = init; if condition { value = then_expr; } else { value =
/// else_expr; } return value;`. The local uses one explicit stack slot and the
/// branch edges are verified as a four-block JIR CFG. This is the first
/// statement branch contract; arbitrary branch statement lists and nested
/// scopes remain additive follow-up contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_local(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_assignment: &TypedStatementHeader,
    else_assignment: &TypedStatementHeader,
    return_statement: &TypedStatementHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE
        || if_header.type_kind != TYPE_KIND_INTEGER
        || if_header.reserved != [0; 6]
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement requires an Int32 if-value header",
        });
    }
    if ast.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement requires a typed expression AST",
        });
    }
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let local_span = typed_statement_span(
        source,
        source_id,
        local_binding.name_start,
        local_binding.name_end,
        0,
    )?;
    if local_binding.type_kind != TYPE_KIND_INTEGER {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch local must be Int32",
        });
    }
    let local_name = source[local_span.start..local_span.end].to_owned();
    if !typed_statement_identifier(&local_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch local must be an ASCII identifier",
        });
    }

    let ast_span = |node: u64, index: usize| -> Result<(usize, Span), TypedStatementLowerError> {
        let node_index =
            usize::try_from(node).map_err(|_| TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch expression node is not representable",
            })?;
        let expression = ast
            .get(node_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch expression node is outside the AST",
            })?;
        if expression.flags != 1 {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch expression node is unresolved",
            });
        }
        let span =
            typed_statement_span(source, source_id, expression.start, expression.end, index)?;
        Ok((node_index, span))
    };
    let (condition_index, condition_span) = ast_span(if_header.condition_node, 0)?;
    let (then_index, then_expression_span) = ast_span(if_header.then_node, 1)?;
    let (else_index, else_expression_span) = ast_span(if_header.else_node, 2)?;
    if ast[condition_index].type_kind != TYPE_KIND_BOOL
        || ast[then_index].type_kind != TYPE_KIND_INTEGER
        || ast[else_index].type_kind != TYPE_KIND_INTEGER
        || condition_span.start < if_span.start
        || condition_span.end > if_span.end
        || then_expression_span.start < if_span.start
        || then_expression_span.end > if_span.end
        || else_expression_span.start < if_span.start
        || else_expression_span.end > if_span.end
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch expression types or spans are invalid",
        });
    }

    let initializer_span =
        typed_statement_span(source, source_id, initializer.start, initializer.end, 0)?;
    let initializer_index = usize::try_from(initializer.expression_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch initializer node is not representable",
        }
    })?;
    let initializer_ast =
        ast.get(initializer_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed branch initializer node is outside the AST",
            })?;
    let initializer_expression_span = typed_statement_span(
        source,
        source_id,
        initializer_ast.start,
        initializer_ast.end,
        0,
    )?;
    if initializer.kind != TYPED_STATEMENT_KIND_LET
        || initializer.flags != TYPED_STATEMENT_FLAG_MUTABLE
        || initializer.type_kind != TYPE_KIND_INTEGER
        || initializer.target_start != local_binding.name_start
        || initializer.target_end != local_binding.name_end
        || initializer_span.end > if_span.start
        || initializer_expression_span.start < initializer_span.start
        || initializer_expression_span.end > initializer_span.end
        || initializer_ast.flags != 1
        || initializer_ast.type_kind != TYPE_KIND_INTEGER
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch initializer must be a mutable Int32 var before the if",
        });
    }
    if source[initializer_span.start..initializer_expression_span.start].trim()
        != format!("var {local_name}: Int32 =")
        || source[initializer_expression_span.end..initializer_span.end].trim() != ";"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch initializer span does not match var syntax",
        });
    }

    let validate_assignment = |statement: &TypedStatementHeader,
                               expression_span: Span,
                               index: usize|
     -> Result<Span, TypedStatementLowerError> {
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, index)?;
        let target_span = typed_statement_span(
            source,
            source_id,
            statement.target_start,
            statement.target_end,
            index,
        )?;
        if statement.kind != TYPED_STATEMENT_KIND_ASSIGN
            || statement.flags != 0
            || statement.type_kind != TYPE_KIND_INTEGER
            || statement.reserved != 0
            || target_span.start < statement_span.start
            || target_span.end > statement_span.end
            || expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || source[target_span.start..target_span.end] != local_name
            || source[statement_span.start..expression_span.start].trim()
                != format!("{local_name} =")
            || source[expression_span.end..statement_span.end].trim() != ";"
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch assignment does not match its local expression",
            });
        }
        Ok(statement_span)
    };
    let then_span = validate_assignment(then_assignment, then_expression_span, 1)?;
    let else_span = validate_assignment(else_assignment, else_expression_span, 2)?;
    if then_span.start < if_span.start
        || then_span.end > if_span.end
        || else_span.start < if_span.start
        || else_span.end > if_span.end
        || condition_span.end > then_span.start
        || then_span.end > else_span.start
        || source[if_span.start..condition_span.start].trim() != "if"
        || source[condition_span.end..then_span.start].trim() != "{"
        || source[then_span.end..else_span.start].trim() != "} else {"
        || source[else_span.end..if_span.end].trim() != "}"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch source span does not match if assignment syntax",
        });
    }

    let return_span = typed_statement_span(
        source,
        source_id,
        return_statement.start,
        return_statement.end,
        3,
    )?;
    let return_index = usize::try_from(return_statement.expression_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 3,
            message: "typed branch return node is not representable",
        }
    })?;
    let return_ast = ast
        .get(return_index)
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 3,
            message: "typed branch return node is outside the AST",
        })?;
    let return_expression_span =
        typed_statement_span(source, source_id, return_ast.start, return_ast.end, 3)?;
    if return_statement.kind != TYPED_STATEMENT_KIND_RETURN
        || return_statement.flags != 0
        || return_statement.type_kind != TYPE_KIND_INTEGER
        || return_statement.target_start != 0
        || return_statement.target_end != 0
        || return_span.start < if_span.end
        || return_ast.syntax_kind != 1
        || return_ast.flags != 1
        || return_ast.type_kind != TYPE_KIND_INTEGER
        || source[return_expression_span.start..return_expression_span.end] != local_name
        || source[return_span.start..return_expression_span.start].trim() != "return"
        || source[return_expression_span.end..return_span.end].trim() != ";"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 3,
            message: "typed branch return must return the merged local",
        });
    }

    let int_type = Type::Integer {
        signed: true,
        bits: 32,
    };
    let bool_type = Type::Bool;
    let int_type_id = TypeId::new(0);
    let bool_type_id = TypeId::new(1);
    let mut types = vec![int_type, bool_type];
    let pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: int_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut parameters = Vec::with_capacity(bindings.len());
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != TYPE_KIND_INTEGER {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch parameters must use Int32",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || name == local_name
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch parameter names must be unique and not shadow the local",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: int_type_id,
            name: Some(name),
        });
    }

    let mut next_value = parameters.len();
    let pointer = ValueId::new(next_value);
    next_value += 1;
    let mut imports = Vec::<Function>::new();
    let mut entry_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: int_type_id,
            count: None,
        },
        span: Some(initializer_span),
    }];
    let (initializer_value, initializer_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        initializer.expression_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if initializer_type != int_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch initializer must lower to Int32",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: initializer_value,
            alignment: 4,
            volatile: false,
        },
        span: Some(initializer_span),
    });
    let condition_local_value = ValueId::new(next_value);
    next_value += 1;
    entry_instructions.push(Instruction {
        result: Some(TypedValue {
            value: condition_local_value,
            ty: int_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: 4,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut condition_values = parameter_values.clone();
    condition_values.insert(local_name.clone(), condition_local_value);
    let mut condition_bindings = bindings.to_vec();
    condition_bindings.push(*local_binding);
    let (condition_value, condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        if_header.condition_node,
        &condition_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &condition_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch condition must lower to Bool",
        });
    }

    let mut lower_branch = |expression_node: u64,
                            statement_span: Span,
                            next_value: &mut usize|
     -> Result<Vec<Instruction>, TypedStatementLowerError> {
        let loaded = ValueId::new(*next_value);
        *next_value += 1;
        let mut instructions = vec![Instruction {
            result: Some(TypedValue {
                value: loaded,
                ty: int_type_id,
            }),
            kind: InstructionKind::Load {
                pointer,
                alignment: 4,
                volatile: false,
            },
            span: Some(statement_span),
        }];
        let mut values = parameter_values.clone();
        values.insert(local_name.clone(), loaded);
        let (assigned, assigned_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            expression_node,
            &{
                let mut visible = bindings.to_vec();
                visible.push(*local_binding);
                visible
            },
            call_bindings,
            call_candidates,
            arguments,
            &values,
            &mut types,
            &mut imports,
            &mut instructions,
            next_value,
            1,
        )?;
        if assigned_type != int_type_id {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 1,
                message: "typed branch assignment expression must lower to Int32",
            });
        }
        instructions.push(Instruction {
            result: None,
            kind: InstructionKind::Store {
                pointer,
                value: assigned,
                alignment: 4,
                volatile: false,
            },
            span: Some(statement_span),
        });
        Ok(instructions)
    };
    let then_instructions = lower_branch(if_header.then_node, then_span, &mut next_value)?;
    let else_instructions = lower_branch(if_header.else_node, else_span, &mut next_value)?;
    let loaded = ValueId::new(next_value);
    let function_span = Span::new(source_id, initializer_span.start, return_span.end)
        .expect("validated typed branch function span");
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_if_statement".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: int_type_id,
        blocks: vec![
            Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions: entry_instructions,
                terminator: Terminator::Branch {
                    condition: condition_value,
                    then_target: BlockId::new(1),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(2),
                    else_arguments: Vec::new(),
                },
                span: Some(function_span),
            },
            Block {
                id: BlockId::new(1),
                parameters: Vec::new(),
                instructions: then_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(then_span),
            },
            Block {
                id: BlockId::new(2),
                parameters: Vec::new(),
                instructions: else_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(else_span),
            },
            Block {
                id: BlockId::new(3),
                parameters: Vec::new(),
                instructions: vec![Instruction {
                    result: Some(TypedValue {
                        value: loaded,
                        ty: int_type_id,
                    }),
                    kind: InstructionKind::Load {
                        pointer,
                        alignment: 4,
                        volatile: false,
                    },
                    span: Some(return_span),
                }],
                terminator: Terminator::Return {
                    value: Some(loaded),
                },
                span: Some(return_span),
            },
        ],
        span: Some(function_span),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_if_statement_to_local`] with ordered assignment
/// lists in both branches and an ordered post-join tail. The branch arrays and
/// tail are caller-owned typed statements; every statement must target the
/// same mutable scalar local and the tail must end in `return local;`. This
/// keeps the first general statement-list CFG bounded while preserving the
/// explicit stack-slot ownership model.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_local_with_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_assignments: &[TypedStatementHeader],
    else_assignments: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        if_header,
        then_assignments,
        else_assignments,
        tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
    )
}

/// Float64 counterpart of [`lower_typed_if_statement_to_local_with_statements`].
/// The source shape and caller-owned ABI are identical; only the homogeneous
/// scalar family and its native stack alignment differ.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_float_local_with_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_assignments: &[TypedStatementHeader],
    else_assignments: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        if_header,
        then_assignments,
        else_assignments,
        tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
    )
}

#[allow(clippy::too_many_arguments)]
fn lower_typed_if_statement_to_local_with_statements_scalar(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_assignments: &[TypedStatementHeader],
    else_assignments: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
    scalar_kind: u8,
    scalar_name: &'static str,
    scalar_alignment: u32,
) -> Result<Module, TypedStatementLowerError> {
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE
        || if_header.type_kind != scalar_kind
        || if_header.reserved != [0; 6]
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement list requires a supported scalar if-value header",
        });
    }
    if ast.is_empty() || then_assignments.is_empty() || else_assignments.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement lists require a typed AST and both branch lists",
        });
    }
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let local_span = typed_statement_span(
        source,
        source_id,
        local_binding.name_start,
        local_binding.name_end,
        0,
    )?;
    if local_binding.type_kind != scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list local must match the scalar type",
        });
    }
    let local_name = source[local_span.start..local_span.end].to_owned();
    if !typed_statement_identifier(&local_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list local must be an ASCII identifier",
        });
    }
    let ast_span = |node: u64,
                    expected_type: u8,
                    region: Span,
                    index: usize|
     -> Result<Span, TypedStatementLowerError> {
        let node_index =
            usize::try_from(node).map_err(|_| TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list expression node is not representable",
            })?;
        let expression = ast
            .get(node_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list expression node is outside the AST",
            })?;
        if expression.flags != 1 || expression.type_kind != expected_type {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list expression is unresolved or mismatched",
            });
        }
        let span =
            typed_statement_span(source, source_id, expression.start, expression.end, index)?;
        if span.start < region.start || span.end > region.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list expression is outside its region",
            });
        }
        Ok(span)
    };
    let condition_span = ast_span(if_header.condition_node, TYPE_KIND_BOOL, if_span, 0)?;
    if usize::try_from(if_header.then_node).ok()
        != then_assignments
            .first()
            .and_then(|statement| usize::try_from(statement.expression_node).ok())
        || usize::try_from(if_header.else_node).ok()
            != else_assignments
                .first()
                .and_then(|statement| usize::try_from(statement.expression_node).ok())
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list header roots must match first assignments",
        });
    }

    let initializer_span =
        typed_statement_span(source, source_id, initializer.start, initializer.end, 0)?;
    let initializer_ast = ast
        .get(usize::try_from(initializer.expression_node).map_err(|_| {
            TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed branch statement-list initializer node is not representable",
            }
        })?)
        .ok_or(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list initializer node is outside the AST",
        })?;
    let initializer_expression_span = typed_statement_span(
        source,
        source_id,
        initializer_ast.start,
        initializer_ast.end,
        0,
    )?;
    if initializer.kind != TYPED_STATEMENT_KIND_LET
        || initializer.flags != TYPED_STATEMENT_FLAG_MUTABLE
        || initializer.type_kind != scalar_kind
        || initializer.reserved != 0
        || initializer.target_start != local_binding.name_start
        || initializer.target_end != local_binding.name_end
        || initializer_span.end > if_span.start
        || initializer_expression_span.start < initializer_span.start
        || initializer_expression_span.end > initializer_span.end
        || initializer_ast.flags != 1
        || initializer_ast.type_kind != scalar_kind
        || source[initializer_span.start..initializer_expression_span.start].trim()
            != format!("var {local_name}: {scalar_name} =")
        || source[initializer_expression_span.end..initializer_span.end].trim() != ";"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list initializer is invalid",
        });
    }

    let validate_assignment = |statement: &TypedStatementHeader,
                               region: Span,
                               index: usize|
     -> Result<(Span, Span), TypedStatementLowerError> {
        if statement.kind != TYPED_STATEMENT_KIND_ASSIGN
            || statement.flags != 0
            || statement.type_kind != scalar_kind
            || statement.reserved != 0
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list entries must match the scalar type",
            });
        }
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, index)?;
        let target_span = typed_statement_span(
            source,
            source_id,
            statement.target_start,
            statement.target_end,
            index,
        )?;
        let expression_span = ast_span(statement.expression_node, scalar_kind, region, index)?;
        if statement_span.start < region.start
            || statement_span.end > region.end
            || target_span.start < statement_span.start
            || target_span.end > statement_span.end
            || expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || source[target_span.start..target_span.end] != local_name
            || source[statement_span.start..expression_span.start].trim()
                != format!("{local_name} =")
            || source[expression_span.end..statement_span.end].trim() != ";"
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list assignment span is invalid",
            });
        }
        Ok((statement_span, expression_span))
    };

    let mut then_ranges = Vec::with_capacity(then_assignments.len());
    let mut previous_end = condition_span.end;
    for (index, statement) in then_assignments.iter().enumerate() {
        let range = validate_assignment(statement, if_span, index + 1)?;
        if range.0.start < previous_end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: index + 1,
                message: "then branch assignments must be ordered",
            });
        }
        previous_end = range.0.end;
        then_ranges.push(range);
    }
    let mut else_ranges = Vec::with_capacity(else_assignments.len());
    previous_end = then_ranges
        .last()
        .map_or(condition_span.end, |range| range.0.end);
    for (index, statement) in else_assignments.iter().enumerate() {
        let range = validate_assignment(statement, if_span, then_assignments.len() + index + 1)?;
        if range.0.start < previous_end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: then_assignments.len() + index + 1,
                message: "else branch assignments must be ordered",
            });
        }
        previous_end = range.0.end;
        else_ranges.push(range);
    }
    if source[if_span.start..condition_span.start].trim() != "if"
        || source[condition_span.end..then_ranges[0].0.start].trim() != "{"
        || then_ranges
            .windows(2)
            .any(|ranges| !source[ranges[0].0.end..ranges[1].0.start].trim().is_empty())
        || source[then_ranges.last().expect("then list is non-empty").0.end..else_ranges[0].0.start]
            .trim()
            != "} else {"
        || else_ranges
            .windows(2)
            .any(|ranges| !source[ranges[0].0.end..ranges[1].0.start].trim().is_empty())
        || source[else_ranges.last().expect("else list is non-empty").0.end..if_span.end].trim()
            != "}"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list source span does not match if syntax",
        });
    }

    if tail.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list tail must end in return",
        });
    }
    let mut tail_ranges = Vec::with_capacity(tail.len().saturating_sub(1));
    previous_end = if_span.end;
    for (index, statement) in tail.iter().enumerate() {
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, index)?;
        if statement_span.start < previous_end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list tail statements must be ordered",
            });
        }
        if index + 1 == tail.len() {
            let expression = ast.get(usize::try_from(statement.expression_node).map_err(|_| {
                TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "typed branch statement-list return node is not representable",
                }
            })?);
            let expression = expression.ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list return node is outside the AST",
            })?;
            let expression_span =
                typed_statement_span(source, source_id, expression.start, expression.end, index)?;
            if statement.kind != TYPED_STATEMENT_KIND_RETURN
                || statement.flags != 0
                || statement.type_kind != scalar_kind
                || statement.target_start != 0
                || statement.target_end != 0
                || expression.syntax_kind != 1
                || expression.flags != 1
                || expression.type_kind != scalar_kind
                || source[expression_span.start..expression_span.end] != local_name
                || source[statement_span.start..expression_span.start].trim() != "return"
                || source[expression_span.end..statement_span.end].trim() != ";"
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "typed branch statement-list tail must end in return local",
                });
            }
        } else {
            let range = validate_assignment(
                statement,
                Span {
                    source: source_id,
                    start: if_span.end,
                    end: source.len(),
                },
                index,
            )?;
            tail_ranges.push(range);
        }
        previous_end = statement_span.end;
    }

    // scalar layout for ordered branch statement lists
    let scalar_type = match scalar_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => unreachable!("validated branch statement scalar kind"),
    };
    let bool_type = Type::Bool;
    let scalar_type_id = TypeId::new(0);
    let bool_type_id = TypeId::new(1);
    let mut types = vec![scalar_type, bool_type];
    let pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: scalar_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut parameters = Vec::with_capacity(bindings.len());
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != scalar_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list parameters must match the scalar type",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || name == local_name
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed branch statement-list parameter names are invalid",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: scalar_type_id,
            name: Some(name),
        });
    }
    let mut next_value = parameters.len();
    let pointer = ValueId::new(next_value);
    next_value += 1;
    let mut imports = Vec::<Function>::new();
    let mut entry_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: scalar_type_id,
            count: None,
        },
        span: Some(initializer_span),
    }];
    let (initializer_value, initializer_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        initializer.expression_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if initializer_type != scalar_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list initializer must match the scalar type",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: initializer_value,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(initializer_span),
    });
    let condition_local_value = ValueId::new(next_value);
    next_value += 1;
    entry_instructions.push(Instruction {
        result: Some(TypedValue {
            value: condition_local_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut condition_values = parameter_values.clone();
    condition_values.insert(local_name.clone(), condition_local_value);
    let mut visible_bindings = bindings.to_vec();
    visible_bindings.push(*local_binding);
    let (condition_value, condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        if_header.condition_node,
        &visible_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &condition_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed branch statement-list condition must be Bool",
        });
    }

    let mut lower_branch = |statements: &[TypedStatementHeader],
                            ranges: &[(Span, Span)]|
     -> Result<Vec<Instruction>, TypedStatementLowerError> {
        let loaded = ValueId::new(next_value);
        next_value += 1;
        let mut instructions = vec![Instruction {
            result: Some(TypedValue {
                value: loaded,
                ty: scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(ranges[0].0),
        }];
        let mut values = parameter_values.clone();
        values.insert(local_name.clone(), loaded);
        for (statement, range) in statements.iter().zip(ranges.iter()) {
            let (value, value_type) = typed_statement_lower_expression_for_cfg(
                source,
                source_id,
                ast,
                statement.expression_node,
                &visible_bindings,
                call_bindings,
                call_candidates,
                arguments,
                &values,
                &mut types,
                &mut imports,
                &mut instructions,
                &mut next_value,
                1,
            )?;
            if value_type != scalar_type_id {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: 1,
                    message: "typed branch statement-list assignment must produce the scalar type",
                });
            }
            instructions.push(Instruction {
                result: None,
                kind: InstructionKind::Store {
                    pointer,
                    value,
                    alignment: scalar_alignment,
                    volatile: false,
                },
                span: Some(range.0),
            });
            values.insert(local_name.clone(), value);
        }
        Ok(instructions)
    };
    let then_instructions = lower_branch(then_assignments, &then_ranges)?;
    let else_instructions = lower_branch(else_assignments, &else_ranges)?;
    let join_loaded = ValueId::new(next_value);
    next_value += 1;
    let mut join_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: join_loaded,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(if_span),
    }];
    let mut join_values = parameter_values;
    join_values.insert(local_name.clone(), join_loaded);
    for (statement, range) in tail.iter().take(tail.len() - 1).zip(tail_ranges.iter()) {
        let (value, value_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            statement.expression_node,
            &visible_bindings,
            call_bindings,
            call_candidates,
            arguments,
            &join_values,
            &mut types,
            &mut imports,
            &mut join_instructions,
            &mut next_value,
            2,
        )?;
        if value_type != scalar_type_id {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 2,
                message: "typed branch statement-list tail assignment must produce the scalar type",
            });
        }
        join_instructions.push(Instruction {
            result: None,
            kind: InstructionKind::Store {
                pointer,
                value,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(range.0),
        });
        join_values.insert(local_name.clone(), value);
    }
    let final_value =
        *join_values
            .get(&local_name)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: tail.len() - 1,
                message: "typed branch statement-list final local value is missing",
            })?;
    let return_span = typed_statement_span(
        source,
        source_id,
        tail.last().expect("tail is non-empty").start,
        tail.last().expect("tail is non-empty").end,
        tail.len() - 1,
    )?;
    let function_span = Span::new(source_id, initializer_span.start, return_span.end)
        .expect("validated typed branch statement-list function span");
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_if_statement_list".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: scalar_type_id,
        blocks: vec![
            Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions: entry_instructions,
                terminator: Terminator::Branch {
                    condition: condition_value,
                    then_target: BlockId::new(1),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(2),
                    else_arguments: Vec::new(),
                },
                span: Some(function_span),
            },
            Block {
                id: BlockId::new(1),
                parameters: Vec::new(),
                instructions: then_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(then_ranges[0].0),
            },
            Block {
                id: BlockId::new(2),
                parameters: Vec::new(),
                instructions: else_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(else_ranges[0].0),
            },
            Block {
                id: BlockId::new(3),
                parameters: Vec::new(),
                instructions: join_instructions,
                terminator: Terminator::Return {
                    value: Some(final_value),
                },
                span: Some(return_span),
            },
        ],
        span: Some(function_span),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_if_statement_to_local_with_statements`] with scoped
/// `let`/`var` declarations inside each branch. Branch locals are allocated in
/// the entry block, but their values become visible only after their source
/// declaration; they never leak into the post-join tail. Branch statements are
/// still bounded to one homogeneous scalar family (`Int32` or `Float64`),
/// while the tail keeps the existing assignment-plus-final-return contract.
#[allow(clippy::too_many_arguments)]
#[allow(clippy::type_complexity)]
pub fn lower_typed_if_statement_to_local_with_branch_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_statements: &[TypedStatementHeader],
    else_statements: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_branch_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        if_header,
        then_statements,
        else_statements,
        tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
    )
}

/// Float64 counterpart of [`lower_typed_if_statement_to_local_with_branch_statements`].
/// Branch-local declarations use the same caller-owned statement ABI and
/// receive native 8-byte storage.
#[allow(clippy::too_many_arguments)]
#[allow(clippy::type_complexity)]
pub fn lower_typed_if_statement_to_float_local_with_branch_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_statements: &[TypedStatementHeader],
    else_statements: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_branch_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        if_header,
        then_statements,
        else_statements,
        tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
    )
}

#[allow(clippy::too_many_arguments)]
#[allow(clippy::type_complexity)]
fn lower_typed_if_statement_to_local_with_branch_statements_scalar(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    if_header: &TypedIfReturnHeader,
    then_statements: &[TypedStatementHeader],
    else_statements: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
    scalar_kind: u8,
    scalar_name: &'static str,
    scalar_alignment: u32,
) -> Result<Module, TypedStatementLowerError> {
    if then_statements
        .iter()
        .chain(else_statements.iter())
        .all(|statement| statement.kind == TYPED_STATEMENT_KIND_ASSIGN)
    {
        return lower_typed_if_statement_to_local_with_statements_scalar(
            source,
            source_id,
            ast,
            bindings,
            initializer,
            local_binding,
            if_header,
            then_statements,
            else_statements,
            tail,
            call_bindings,
            call_candidates,
            arguments,
            scalar_kind,
            scalar_name,
            scalar_alignment,
        );
    }
    if if_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE
        || if_header.type_kind != scalar_kind
        || if_header.reserved != [0; 6]
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch requires a supported scalar if-value header",
        });
    }
    if ast.is_empty() || then_statements.is_empty() || else_statements.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch requires an AST and both branch lists",
        });
    }
    let if_span = typed_statement_span(source, source_id, if_header.start, if_header.end, 0)?;
    let local_span = typed_statement_span(
        source,
        source_id,
        local_binding.name_start,
        local_binding.name_end,
        0,
    )?;
    if local_binding.type_kind != scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch local must match the scalar type",
        });
    }
    let local_name = source[local_span.start..local_span.end].to_owned();
    if !typed_statement_identifier(&local_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch local must be an ASCII identifier",
        });
    }
    let ast_span = |node: u64,
                    expected_type: u8,
                    region: Span,
                    index: usize|
     -> Result<(Span, &TypedExpressionAstNodeHeader), TypedStatementLowerError> {
        let node_index =
            usize::try_from(node).map_err(|_| TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch expression node is not representable",
            })?;
        let expression = ast
            .get(node_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch expression node is outside the AST",
            })?;
        if expression.flags != 1 || expression.type_kind != expected_type {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch expression is unresolved or mismatched",
            });
        }
        let span =
            typed_statement_span(source, source_id, expression.start, expression.end, index)?;
        if span.start < region.start || span.end > region.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch expression is outside its region",
            });
        }
        Ok((span, expression))
    };

    let initializer_span = {
        let statement_span =
            typed_statement_span(source, source_id, initializer.start, initializer.end, 0)?;
        let (expression_span, _) =
            ast_span(initializer.expression_node, scalar_kind, statement_span, 0)?;
        if initializer.kind != TYPED_STATEMENT_KIND_LET
            || initializer.flags != TYPED_STATEMENT_FLAG_MUTABLE
            || initializer.type_kind != scalar_kind
            || initializer.reserved != 0
            || initializer.target_start != local_binding.name_start
            || initializer.target_end != local_binding.name_end
            || statement_span.end > if_span.start
            || source[statement_span.start..expression_span.start].trim()
                != format!("var {local_name}: {scalar_name} =")
            || source[expression_span.end..statement_span.end].trim() != ";"
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed scoped branch initializer is invalid",
            });
        }
        statement_span
    };
    let (condition_span, _) = ast_span(if_header.condition_node, TYPE_KIND_BOOL, if_span, 0)?;
    if if_header.then_node != then_statements[0].expression_node
        || if_header.else_node != else_statements[0].expression_node
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch roots must match first statements",
        });
    }

    let scalar_type = match scalar_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => unreachable!("validated scoped branch scalar kind"),
    };
    let scalar_type_id = TypeId::new(0);
    let bool_type_id = TypeId::new(1);
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    let mut parameters = Vec::with_capacity(bindings.len());
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != scalar_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch parameters must match the scalar type",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || name == local_name
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch parameter names are invalid",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: scalar_type_id,
            name: Some(name),
        });
    }

    let validate_branch = |statements: &[TypedStatementHeader],
                           index_offset: usize|
     -> Result<
        (Vec<(usize, Span)>, BTreeMap<String, (Span, bool)>),
        TypedStatementLowerError,
    > {
        let mut ranges = Vec::with_capacity(statements.len());
        let mut locals = BTreeMap::<String, (Span, bool)>::new();
        let mut previous_end = condition_span.end;
        for (index, statement) in statements.iter().enumerate() {
            let statement_index = index_offset + index;
            if statement.reserved != 0
                || statement.type_kind != scalar_kind
                || (statement.kind == TYPED_STATEMENT_KIND_LET
                    && statement.flags & !TYPED_STATEMENT_FLAG_MUTABLE != 0)
                || (statement.kind == TYPED_STATEMENT_KIND_ASSIGN && statement.flags != 0)
                || !matches!(
                    statement.kind,
                    TYPED_STATEMENT_KIND_LET | TYPED_STATEMENT_KIND_ASSIGN
                )
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "typed scoped branch statements must match the scalar type",
                });
            }
            let statement_span = typed_statement_span(
                source,
                source_id,
                statement.start,
                statement.end,
                statement_index,
            )?;
            if statement_span.start < previous_end
                || statement_span.start < if_span.start
                || statement_span.end > if_span.end
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "typed scoped branch statements must be ordered inside the if span",
                });
            }
            let target_span = typed_statement_span(
                source,
                source_id,
                statement.target_start,
                statement.target_end,
                statement_index,
            )?;
            let target_name = source[target_span.start..target_span.end].to_owned();
            if target_span.start < statement_span.start
                || target_span.end > statement_span.end
                || !typed_statement_identifier(&target_name)
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: statement_index,
                    message: "typed scoped branch target is invalid or out of range",
                });
            }
            let (expression_span, _) = ast_span(
                statement.expression_node,
                scalar_kind,
                statement_span,
                statement_index,
            )?;
            let prefix = source[statement_span.start..expression_span.start].trim();
            let suffix = source[expression_span.end..statement_span.end].trim();
            if statement.kind == TYPED_STATEMENT_KIND_LET {
                let expected_let = format!("let {target_name}: {scalar_name} =");
                let expected_var = format!("var {target_name}: {scalar_name} =");
                let prefix_matches = if statement.flags == TYPED_STATEMENT_FLAG_MUTABLE {
                    prefix == expected_let || prefix == expected_var
                } else {
                    prefix == expected_let
                };
                if !prefix_matches
                    || suffix != ";"
                    || target_name == local_name
                    || parameter_values.contains_key(&target_name)
                    || locals.contains_key(&target_name)
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "typed scoped branch let declaration is invalid or shadows a visible binding",
                    });
                }
                locals.insert(
                    target_name,
                    (target_span, statement.flags == TYPED_STATEMENT_FLAG_MUTABLE),
                );
            } else {
                let prefix_matches = prefix == format!("{target_name} =") && suffix == ";";
                let target_is_outer = target_name == local_name;
                let target_is_mutable_local = locals
                    .get(&target_name)
                    .is_some_and(|(_, mutable)| *mutable);
                if !prefix_matches || (!target_is_outer && !target_is_mutable_local) {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: statement_index,
                        message: "typed scoped branch assignment target is not mutable or visible",
                    });
                }
            }
            previous_end = statement_span.end;
            ranges.push((index, statement_span));
        }
        Ok((ranges, locals))
    };
    let (then_ranges, then_locals) = validate_branch(then_statements, 1)?;
    let (else_ranges, else_locals) = validate_branch(else_statements, 1 + then_statements.len())?;
    if source[if_span.start..condition_span.start].trim() != "if"
        || source[condition_span.end..then_ranges[0].1.start].trim() != "{"
        || source[then_ranges[then_ranges.len() - 1].1.end..else_ranges[0].1.start].trim()
            != "} else {"
        || source[else_ranges[else_ranges.len() - 1].1.end..if_span.end].trim() != "}"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch source span does not match if syntax",
        });
    }

    if tail.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch tail must end in return",
        });
    }
    let mut tail_ranges = Vec::<(usize, Span)>::with_capacity(tail.len().saturating_sub(1));
    let mut previous_end = if_span.end;
    for (index, statement) in tail.iter().enumerate() {
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, index)?;
        if statement_span.start < previous_end || statement.reserved != 0 {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch tail statements must be ordered",
            });
        }
        let (expression_span, expression) = ast_span(
            statement.expression_node,
            scalar_kind,
            statement_span,
            index,
        )?;
        if statement.kind == TYPED_STATEMENT_KIND_ASSIGN {
            if statement.flags != 0 {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "typed scoped branch tail assignment flags must be zero",
                });
            }
            let target_span = typed_statement_span(
                source,
                source_id,
                statement.target_start,
                statement.target_end,
                index,
            )?;
            let target_name = source[target_span.start..target_span.end].to_owned();
            if target_name != local_name
                || source[statement_span.start..expression_span.start].trim()
                    != format!("{local_name} =")
                || source[expression_span.end..statement_span.end].trim() != ";"
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "typed scoped branch tail assignment must target the outer local",
                });
            }
            tail_ranges.push((index, statement_span));
        } else if statement.kind == TYPED_STATEMENT_KIND_RETURN {
            if index + 1 != tail.len()
                || statement.flags != 0
                || statement.target_start != 0
                || statement.target_end != 0
                || expression.syntax_kind != 1
                || source[expression_span.start..expression_span.end] != local_name
                || source[statement_span.start..expression_span.start].trim() != "return"
                || source[expression_span.end..statement_span.end].trim() != ";"
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "typed scoped branch tail must end in return local",
                });
            }
        } else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed scoped branch tail supports only assignment and return",
            });
        }
        previous_end = statement_span.end;
    }
    if tail
        .last()
        .is_none_or(|statement| statement.kind != TYPED_STATEMENT_KIND_RETURN)
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: tail.len() - 1,
            message: "typed scoped branch tail must end in return",
        });
    }

    let bool_type = Type::Bool;
    let mut types = vec![scalar_type, bool_type];
    let pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: scalar_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut next_value = parameters.len();
    let outer_pointer = ValueId::new(next_value);
    next_value += 1;
    let mut entry_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: outer_pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: scalar_type_id,
            count: None,
        },
        span: Some(initializer_span),
    }];
    let allocate_branch_locals =
        |locals: &BTreeMap<String, (Span, bool)>,
         next_value: &mut usize,
         instructions: &mut Vec<Instruction>| {
            let mut result = BTreeMap::<String, TypedStatementLocal>::new();
            for (name, (declaration, mutable)) in locals {
                let pointer = ValueId::new(*next_value);
                *next_value += 1;
                instructions.push(Instruction {
                    result: Some(TypedValue {
                        value: pointer,
                        ty: pointer_type,
                    }),
                    kind: InstructionKind::StackAlloc {
                        ty: scalar_type_id,
                        count: None,
                    },
                    span: Some(*declaration),
                });
                result.insert(
                    name.clone(),
                    TypedStatementLocal {
                        declaration: *declaration,
                        pointer,
                        mutable: *mutable,
                    },
                );
            }
            result
        };
    let then_local_bindings =
        allocate_branch_locals(&then_locals, &mut next_value, &mut entry_instructions);
    let else_local_bindings =
        allocate_branch_locals(&else_locals, &mut next_value, &mut entry_instructions);
    let mut imports = Vec::<Function>::new();
    let (initializer_value, initializer_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        initializer.expression_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if initializer_type != scalar_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch initializer must match the scalar type",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer: outer_pointer,
            value: initializer_value,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(initializer_span),
    });
    let condition_local_value = ValueId::new(next_value);
    next_value += 1;
    entry_instructions.push(Instruction {
        result: Some(TypedValue {
            value: condition_local_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut condition_values = parameter_values.clone();
    condition_values.insert(local_name.clone(), condition_local_value);
    let mut visible_bindings = bindings.to_vec();
    visible_bindings.push(*local_binding);
    let (condition_value, condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        if_header.condition_node,
        &visible_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &condition_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed scoped branch condition must be Bool",
        });
    }

    let mut lower_branch = |statements: &[TypedStatementHeader],
                            ranges: &[(usize, Span)],
                            locals: &BTreeMap<String, TypedStatementLocal>|
     -> Result<Vec<Instruction>, TypedStatementLowerError> {
        let loaded = ValueId::new(next_value);
        next_value += 1;
        let mut instructions = vec![Instruction {
            result: Some(TypedValue {
                value: loaded,
                ty: scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: outer_pointer,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(ranges[0].1),
        }];
        let mut values = parameter_values.clone();
        values.insert(local_name.clone(), loaded);
        let mut branch_bindings = visible_bindings.clone();
        for local in locals.values() {
            branch_bindings.push(TypedNameBindingHeader {
                name_start: local.declaration.start as u64,
                name_end: local.declaration.end as u64,
                type_kind: scalar_kind,
            });
        }
        for (index, statement_span) in ranges {
            typed_statement_lower_while_body_range(
                source,
                source_id,
                ast,
                &statements[*index],
                *statement_span,
                *index,
                &branch_bindings,
                call_bindings,
                call_candidates,
                arguments,
                &mut values,
                &mut types,
                &mut imports,
                &mut instructions,
                &mut next_value,
                locals,
                &local_name,
                outer_pointer,
                scalar_type_id,
            )?;
        }
        Ok(instructions)
    };
    let then_instructions = lower_branch(then_statements, &then_ranges, &then_local_bindings)?;
    let else_instructions = lower_branch(else_statements, &else_ranges, &else_local_bindings)?;
    let join_loaded = ValueId::new(next_value);
    next_value += 1;
    let mut join_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: join_loaded,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(if_span),
    }];
    let mut join_values = parameter_values;
    join_values.insert(local_name.clone(), join_loaded);
    for (index, statement_span) in &tail_ranges {
        let statement = &tail[*index];
        let (value, value_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            statement.expression_node,
            &visible_bindings,
            call_bindings,
            call_candidates,
            arguments,
            &join_values,
            &mut types,
            &mut imports,
            &mut join_instructions,
            &mut next_value,
            *index,
        )?;
        if value_type != scalar_type_id {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: *index,
                message: "typed scoped branch tail assignment must produce the scalar type",
            });
        }
        join_instructions.push(Instruction {
            result: None,
            kind: InstructionKind::Store {
                pointer: outer_pointer,
                value,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(*statement_span),
        });
        join_values.insert(local_name.clone(), value);
    }
    let final_value =
        *join_values
            .get(&local_name)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: tail.len() - 1,
                message: "typed scoped branch final local value is missing",
            })?;
    let return_statement = tail.last().expect("tail is non-empty");
    let return_span = typed_statement_span(
        source,
        source_id,
        return_statement.start,
        return_statement.end,
        tail.len() - 1,
    )?;
    let function_span = Span::new(source_id, initializer_span.start, return_span.end)
        .expect("validated typed scoped branch function span");
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_if_scoped_statement_list".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: scalar_type_id,
        blocks: vec![
            Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions: entry_instructions,
                terminator: Terminator::Branch {
                    condition: condition_value,
                    then_target: BlockId::new(1),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(2),
                    else_arguments: Vec::new(),
                },
                span: Some(function_span),
            },
            Block {
                id: BlockId::new(1),
                parameters: Vec::new(),
                instructions: then_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(then_ranges[0].1),
            },
            Block {
                id: BlockId::new(2),
                parameters: Vec::new(),
                instructions: else_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(3),
                    arguments: Vec::new(),
                },
                span: Some(else_ranges[0].1),
            },
            Block {
                id: BlockId::new(3),
                parameters: Vec::new(),
                instructions: join_instructions,
                terminator: Terminator::Return {
                    value: Some(final_value),
                },
                span: Some(return_span),
            },
        ],
        span: Some(function_span),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers one bounded nested statement-shaped `if` into an explicit six-block
/// CFG. The outer `if` owns one nested `if` in its then branch; every leaf
/// assigns the same mutable Int32 local and the join returns that local. This
/// is deliberately narrower than arbitrary nested statement lists, but it
/// makes nested control a first-class Stage-2 lowering contract instead of an
/// expression-only workaround.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_local_with_nested_branch(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    outer_header: &TypedIfReturnHeader,
    nested_header: &TypedIfReturnHeader,
    nested_then: &TypedStatementHeader,
    nested_else: &TypedStatementHeader,
    outer_else: &TypedStatementHeader,
    tail: &TypedStatementHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_nested_branch_statements(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        outer_header,
        nested_header,
        std::slice::from_ref(nested_then),
        std::slice::from_ref(nested_else),
        std::slice::from_ref(outer_else),
        tail,
        call_bindings,
        call_candidates,
        arguments,
    )
}

/// Extends [`lower_typed_if_statement_to_local_with_nested_branch`] with
/// ordered Int32 assignment lists in each leaf. Each leaf keeps one mutable
/// outer local, so the nested CFG remains six blocks while the value in its
/// stack slot is updated in source order.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_local_with_nested_branch_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    outer_header: &TypedIfReturnHeader,
    nested_header: &TypedIfReturnHeader,
    nested_then: &[TypedStatementHeader],
    nested_else: &[TypedStatementHeader],
    outer_else: &[TypedStatementHeader],
    tail: &TypedStatementHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_if_statement_to_local_with_nested_branch_statements_and_tail(
        source,
        source_id,
        ast,
        bindings,
        initializer,
        local_binding,
        outer_header,
        nested_header,
        nested_then,
        nested_else,
        outer_else,
        std::slice::from_ref(tail),
        call_bindings,
        call_candidates,
        arguments,
    )
}

/// Extends nested branch assignment lists with an ordered post-join tail. The
/// tail accepts zero or more mutable-local Int32 assignments followed by the
/// required `return local;`; all tail expressions execute in the common join
/// block and see the newest value from the preceding statement.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_if_statement_to_local_with_nested_branch_statements_and_tail(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer: &TypedStatementHeader,
    local_binding: &TypedNameBindingHeader,
    outer_header: &TypedIfReturnHeader,
    nested_header: &TypedIfReturnHeader,
    nested_then: &[TypedStatementHeader],
    nested_else: &[TypedStatementHeader],
    outer_else: &[TypedStatementHeader],
    tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if ast.is_empty()
        || outer_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE
        || nested_header.kind != TYPED_CONTROL_FLOW_KIND_IF_VALUE
        || outer_header.type_kind != TYPE_KIND_INTEGER
        || nested_header.type_kind != TYPE_KIND_INTEGER
        || outer_header.reserved != [0; 6]
        || nested_header.reserved != [0; 6]
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if requires Int32 if-value headers and an AST",
        });
    }
    if nested_then.is_empty() || nested_else.is_empty() || outer_else.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested statement if requires non-empty assignment leaves",
        });
    }
    if local_binding.type_kind != TYPE_KIND_INTEGER {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if local must be Int32",
        });
    }
    let local_span = typed_statement_span(
        source,
        source_id,
        local_binding.name_start,
        local_binding.name_end,
        0,
    )?;
    let local_name = source[local_span.start..local_span.end].to_owned();
    if !typed_statement_identifier(&local_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if local must be an ASCII identifier",
        });
    }
    let outer_span =
        typed_statement_span(source, source_id, outer_header.start, outer_header.end, 0)?;
    let nested_span =
        typed_statement_span(source, source_id, nested_header.start, nested_header.end, 1)?;
    if nested_span.start <= outer_span.start || nested_span.end >= outer_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested statement if must be contained in the outer if",
        });
    }
    let ast_span = |node: u64,
                    expected_type: u8,
                    region: Span,
                    index: usize|
     -> Result<Span, TypedStatementLowerError> {
        let node_index =
            usize::try_from(node).map_err(|_| TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if AST node is not representable",
            })?;
        let expression = ast
            .get(node_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if AST node is outside the AST",
            })?;
        if expression.flags != 1 || expression.type_kind != expected_type {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if expression is unresolved or mismatched",
            });
        }
        let span =
            typed_statement_span(source, source_id, expression.start, expression.end, index)?;
        if span.start < region.start || span.end > region.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if expression is outside its region",
            });
        }
        Ok(span)
    };
    let initializer_span =
        typed_statement_span(source, source_id, initializer.start, initializer.end, 0)?;
    let initializer_expression = ast_span(
        initializer.expression_node,
        TYPE_KIND_INTEGER,
        initializer_span,
        0,
    )?;
    if initializer.kind != TYPED_STATEMENT_KIND_LET
        || initializer.flags != TYPED_STATEMENT_FLAG_MUTABLE
        || initializer.type_kind != TYPE_KIND_INTEGER
        || initializer.reserved != 0
        || initializer.target_start != local_binding.name_start
        || initializer.target_end != local_binding.name_end
        || initializer_span.end > outer_span.start
        || source[initializer_span.start..initializer_expression.start].trim()
            != format!("var {local_name}: Int32 =")
        || source[initializer_expression.end..initializer_span.end].trim() != ";"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if initializer is invalid",
        });
    }
    let outer_condition = ast_span(outer_header.condition_node, TYPE_KIND_BOOL, outer_span, 0)?;
    let nested_condition = ast_span(nested_header.condition_node, TYPE_KIND_BOOL, nested_span, 1)?;
    if outer_header.then_node != nested_header.condition_node
        || nested_header.then_node != nested_then[0].expression_node
        || nested_header.else_node != nested_else[0].expression_node
        || outer_header.else_node != outer_else[0].expression_node
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested statement if roots do not match their statements",
        });
    }
    let validate_assignment = |statement: &TypedStatementHeader,
                               expression_index: usize,
                               region: Span|
     -> Result<(Span, Span), TypedStatementLowerError> {
        if statement.kind != TYPED_STATEMENT_KIND_ASSIGN
            || statement.flags != 0
            || statement.type_kind != TYPE_KIND_INTEGER
            || statement.reserved != 0
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: expression_index,
                message: "nested statement if leaves accept only Int32 assignments",
            });
        }
        let statement_span = typed_statement_span(
            source,
            source_id,
            statement.start,
            statement.end,
            expression_index,
        )?;
        let target_span = typed_statement_span(
            source,
            source_id,
            statement.target_start,
            statement.target_end,
            expression_index,
        )?;
        let expression_span = ast_span(
            statement.expression_node,
            TYPE_KIND_INTEGER,
            region,
            expression_index,
        )?;
        if target_span.start < statement_span.start
            || target_span.end > statement_span.end
            || expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || source[target_span.start..target_span.end] != local_name
            || source[statement_span.start..expression_span.start].trim()
                != format!("{local_name} =")
            || source[expression_span.end..statement_span.end].trim() != ";"
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: expression_index,
                message: "nested statement if assignment does not match local syntax",
            });
        }
        Ok((statement_span, expression_span))
    };
    let validate_assignments = |statements: &[TypedStatementHeader],
                                index_base: usize,
                                region: Span|
     -> Result<Vec<(Span, Span)>, TypedStatementLowerError> {
        let mut ranges = Vec::with_capacity(statements.len());
        let mut previous_end = region.start;
        for (offset, statement) in statements.iter().enumerate() {
            let range = validate_assignment(statement, index_base + offset, region)?;
            if range.0.start < previous_end {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index_base + offset,
                    message: "nested statement if leaf assignments must be ordered",
                });
            }
            previous_end = range.0.end;
            ranges.push(range);
        }
        Ok(ranges)
    };
    let nested_then_ranges = validate_assignments(nested_then, 2, nested_span)?;
    let nested_else_ranges = validate_assignments(nested_else, 2 + nested_then.len(), nested_span)?;
    let outer_else_ranges = validate_assignments(
        outer_else,
        2 + nested_then.len() + nested_else.len(),
        outer_span,
    )?;
    if tail.is_empty()
        || tail
            .last()
            .is_none_or(|statement| statement.kind != TYPED_STATEMENT_KIND_RETURN)
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 5,
            message: "nested statement if tail must end in return",
        });
    }
    let tail_region = Span {
        source: source_id,
        start: outer_span.end,
        end: source.len(),
    };
    let mut tail_ranges = Vec::<(Span, Span)>::with_capacity(tail.len().saturating_sub(1));
    let mut previous_tail_end = outer_span.end;
    for (index, statement) in tail.iter().enumerate() {
        if statement.reserved != 0
            || statement.type_kind != TYPE_KIND_INTEGER
            || statement.flags != 0
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 5 + index,
                message: "nested statement if tail flags and type must be zero/Int32",
            });
        }
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, 5 + index)?;
        if statement_span.start < previous_tail_end || statement_span.end > tail_region.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 5 + index,
                message: "nested statement if tail statements must be ordered after the join",
            });
        }
        let expression_span = ast_span(
            statement.expression_node,
            TYPE_KIND_INTEGER,
            statement_span,
            5 + index,
        )?;
        let target_span = if statement.kind == TYPED_STATEMENT_KIND_ASSIGN {
            typed_statement_span(
                source,
                source_id,
                statement.target_start,
                statement.target_end,
                5 + index,
            )?
        } else {
            Span {
                source: source_id,
                start: statement_span.start,
                end: statement_span.start,
            }
        };
        if statement.kind == TYPED_STATEMENT_KIND_ASSIGN {
            if target_span.start < statement_span.start
                || target_span.end > statement_span.end
                || source[target_span.start..target_span.end] != local_name
                || source[statement_span.start..expression_span.start].trim()
                    != format!("{local_name} =")
                || source[expression_span.end..statement_span.end].trim() != ";"
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: 5 + index,
                    message: "nested statement if tail assignment is invalid",
                });
            }
            tail_ranges.push((statement_span, expression_span));
        } else if statement.kind == TYPED_STATEMENT_KIND_RETURN {
            if index + 1 != tail.len()
                || statement.target_start != 0
                || statement.target_end != 0
                || source[expression_span.start..expression_span.end] != local_name
                || source[statement_span.start..expression_span.start].trim() != "return"
                || source[expression_span.end..statement_span.end].trim() != ";"
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: 5 + index,
                    message: "nested statement if tail return is invalid",
                });
            }
        } else {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 5 + index,
                message: "nested statement if tail supports assignment and return only",
            });
        }
        previous_tail_end = statement_span.end;
    }
    let return_statement = tail.last().expect("tail is non-empty");
    let tail_span = typed_statement_span(
        source,
        source_id,
        return_statement.start,
        return_statement.end,
        5 + tail.len() - 1,
    )?;
    if source[outer_span.start..outer_condition.start].trim() != "if"
        || source[outer_condition.end..nested_span.start].trim() != "{"
        || source[nested_span.start..nested_condition.start].trim() != "if"
        || source[nested_condition.end..nested_then_ranges[0].0.start].trim() != "{"
        || source
            [nested_then_ranges[nested_then_ranges.len() - 1].0.end..nested_else_ranges[0].0.start]
            .trim()
            != "} else {"
        || source[nested_else_ranges[nested_else_ranges.len() - 1].0.end..nested_span.end].trim()
            != "}"
        || source[nested_span.end..outer_else_ranges[0].0.start].trim() != "} else {"
        || source[outer_else_ranges[outer_else_ranges.len() - 1].0.end..outer_span.end].trim()
            != "}"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if source span does not match syntax",
        });
    }

    let int_type_id = TypeId::new(0);
    let bool_type_id = TypeId::new(1);
    let int_type = Type::Integer {
        signed: true,
        bits: 32,
    };
    let bool_type = Type::Bool;
    let mut types = vec![int_type, bool_type];
    let pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: int_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    let mut parameters = Vec::with_capacity(bindings.len());
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != TYPE_KIND_INTEGER {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if parameters must use Int32",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || name == local_name
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested statement if parameter names are invalid",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: int_type_id,
            name: Some(name),
        });
    }
    let mut next_value = parameters.len();
    let outer_pointer = ValueId::new(next_value);
    next_value += 1;
    let mut entry_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: outer_pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: int_type_id,
            count: None,
        },
        span: Some(initializer_span),
    }];
    let mut imports = Vec::<Function>::new();
    let (initializer_value, initializer_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        initializer.expression_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if initializer_type != int_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if initializer must produce Int32",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer: outer_pointer,
            value: initializer_value,
            alignment: 4,
            volatile: false,
        },
        span: Some(initializer_span),
    });
    let visible = {
        let mut value = bindings.to_vec();
        value.push(*local_binding);
        value
    };
    let loaded_outer = ValueId::new(next_value);
    next_value += 1;
    entry_instructions.push(Instruction {
        result: Some(TypedValue {
            value: loaded_outer,
            ty: int_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: 4,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut outer_values = parameter_values.clone();
    outer_values.insert(local_name.clone(), loaded_outer);
    let (outer_condition_value, outer_condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        outer_header.condition_node,
        &visible,
        call_bindings,
        call_candidates,
        arguments,
        &outer_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if outer_condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested statement if outer condition must be Bool",
        });
    }
    let mut nested_instructions = Vec::new();
    let nested_loaded = ValueId::new(next_value);
    next_value += 1;
    nested_instructions.push(Instruction {
        result: Some(TypedValue {
            value: nested_loaded,
            ty: int_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: 4,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut nested_values = parameter_values.clone();
    nested_values.insert(local_name.clone(), nested_loaded);
    let (nested_condition_value, nested_condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        nested_header.condition_node,
        &visible,
        call_bindings,
        call_candidates,
        arguments,
        &nested_values,
        &mut types,
        &mut imports,
        &mut nested_instructions,
        &mut next_value,
        1,
    )?;
    if nested_condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested statement if inner condition must be Bool",
        });
    }
    let mut outer_else_instructions = Vec::new();
    let outer_else_loaded = ValueId::new(next_value);
    next_value += 1;
    outer_else_instructions.push(Instruction {
        result: Some(TypedValue {
            value: outer_else_loaded,
            ty: int_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: 4,
            volatile: false,
        },
        span: Some(local_span),
    });
    let mut lower_leaf = |statements: &[TypedStatementHeader],
                          ranges: &[(Span, Span)],
                          index_base: usize,
                          block_values: &mut BTreeMap<String, ValueId>,
                          instructions: &mut Vec<Instruction>|
     -> Result<(), TypedStatementLowerError> {
        for (offset, statement) in statements.iter().enumerate() {
            let index = index_base + offset;
            let (value, value_type) = typed_statement_lower_expression_for_cfg(
                source,
                source_id,
                ast,
                statement.expression_node,
                &visible,
                call_bindings,
                call_candidates,
                arguments,
                block_values,
                &mut types,
                &mut imports,
                instructions,
                &mut next_value,
                index,
            )?;
            if value_type != int_type_id {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "nested statement if leaf must produce Int32",
                });
            }
            instructions.push(Instruction {
                result: None,
                kind: InstructionKind::Store {
                    pointer: outer_pointer,
                    value,
                    alignment: 4,
                    volatile: false,
                },
                span: Some(ranges[offset].1),
            });
            block_values.insert(local_name.clone(), value);
        }
        Ok(())
    };
    let mut then_leaf_instructions = Vec::new();
    let mut then_values = parameter_values.clone();
    then_values.insert(local_name.clone(), nested_loaded);
    lower_leaf(
        nested_then,
        &nested_then_ranges,
        2,
        &mut then_values,
        &mut then_leaf_instructions,
    )?;
    let mut nested_else_instructions = Vec::new();
    let mut nested_else_values = parameter_values.clone();
    nested_else_values.insert(local_name.clone(), nested_loaded);
    lower_leaf(
        nested_else,
        &nested_else_ranges,
        2 + nested_then.len(),
        &mut nested_else_values,
        &mut nested_else_instructions,
    )?;
    let mut outer_else_values = parameter_values.clone();
    outer_else_values.insert(local_name.clone(), outer_else_loaded);
    lower_leaf(
        outer_else,
        &outer_else_ranges,
        2 + nested_then.len() + nested_else.len(),
        &mut outer_else_values,
        &mut outer_else_instructions,
    )?;
    let join_loaded = ValueId::new(next_value);
    next_value += 1;
    let mut join_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: join_loaded,
            ty: int_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: 4,
            volatile: false,
        },
        span: Some(tail_span),
    }];
    let mut join_values = parameter_values;
    join_values.insert(local_name.clone(), join_loaded);
    for (index, (statement_span, _expression_span)) in tail_ranges.iter().enumerate() {
        let statement = &tail[index];
        let (value, value_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            statement.expression_node,
            &visible,
            call_bindings,
            call_candidates,
            arguments,
            &join_values,
            &mut types,
            &mut imports,
            &mut join_instructions,
            &mut next_value,
            5 + index,
        )?;
        if value_type != int_type_id {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 5 + index,
                message: "nested statement if tail assignment must produce Int32",
            });
        }
        join_instructions.push(Instruction {
            result: None,
            kind: InstructionKind::Store {
                pointer: outer_pointer,
                value,
                alignment: 4,
                volatile: false,
            },
            span: Some(*statement_span),
        });
        join_values.insert(local_name.clone(), value);
    }
    let final_value = *join_values
        .get(&local_name)
        .expect("join local is initialized before tail");
    let function_span = Span::new(source_id, initializer_span.start, tail_span.end)
        .expect("validated nested statement if function span");
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_if_nested_statement".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: int_type_id,
        blocks: vec![
            Block {
                id: BlockId::new(0),
                parameters: Vec::new(),
                instructions: entry_instructions,
                terminator: Terminator::Branch {
                    condition: outer_condition_value,
                    then_target: BlockId::new(1),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(4),
                    else_arguments: Vec::new(),
                },
                span: Some(function_span),
            },
            Block {
                id: BlockId::new(1),
                parameters: Vec::new(),
                instructions: nested_instructions,
                terminator: Terminator::Branch {
                    condition: nested_condition_value,
                    then_target: BlockId::new(2),
                    then_arguments: Vec::new(),
                    else_target: BlockId::new(3),
                    else_arguments: Vec::new(),
                },
                span: Some(nested_span),
            },
            Block {
                id: BlockId::new(2),
                parameters: Vec::new(),
                instructions: then_leaf_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(5),
                    arguments: Vec::new(),
                },
                span: Some(nested_then_ranges[0].0),
            },
            Block {
                id: BlockId::new(3),
                parameters: Vec::new(),
                instructions: nested_else_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(5),
                    arguments: Vec::new(),
                },
                span: Some(nested_else_ranges[0].0),
            },
            Block {
                id: BlockId::new(4),
                parameters: Vec::new(),
                instructions: outer_else_instructions,
                terminator: Terminator::Jump {
                    target: BlockId::new(5),
                    arguments: Vec::new(),
                },
                span: Some(outer_else_ranges[0].0),
            },
            Block {
                id: BlockId::new(5),
                parameters: Vec::new(),
                instructions: join_instructions,
                terminator: Terminator::Return {
                    value: Some(final_value),
                },
                span: Some(tail_span),
            },
        ],
        span: Some(function_span),
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers one bounded `while` loop over an Int32 stack local. The entry block
/// initializes the local, the header loads it and branches on a Bool
/// condition, the body assigns a new Int32 value and jumps back, and the exit
/// block loads the final value. This explicit memory loop is additive: nested
/// loops, `break`/`continue`, shadowing and user-defined loop locals remain
/// separate contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_while_local(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer_node: u64,
    local_binding: &TypedNameBindingHeader,
    while_header: &TypedWhileHeader,
    body_statement: &TypedStatementHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_while_local_with_statements(
        source,
        source_id,
        ast,
        bindings,
        initializer_node,
        local_binding,
        while_header,
        std::slice::from_ref(body_statement),
        call_bindings,
        call_candidates,
        arguments,
    )
}

/// Lowers one bounded `while` loop whose body is an ordered caller-owned list
/// of Int32 `let`/assignment statements plus optional terminal loop control.
/// Body-local storage is allocated once in `entry` and initialized in the body
/// on every iteration, while the loop local keeps its original stack slot.
/// This additive form preserves the original one-statement wrapper; nested
/// scopes and general control statements remain separate contracts.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_while_local_with_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer_node: u64,
    local_binding: &TypedNameBindingHeader,
    while_header: &TypedWhileHeader,
    body_statements: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_while_local_with_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer_node,
        local_binding,
        while_header,
        body_statements,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
    )
}

/// Float64 counterpart of [`lower_typed_while_local_with_statements`].
/// The loop local and body-local declarations use native 8-byte storage while
/// the condition remains Bool and the loop control contract stays unchanged.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_while_float_local_with_statements(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer_node: u64,
    local_binding: &TypedNameBindingHeader,
    while_header: &TypedWhileHeader,
    body_statements: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_while_local_with_statements_scalar(
        source,
        source_id,
        ast,
        bindings,
        initializer_node,
        local_binding,
        while_header,
        body_statements,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
    )
}

#[allow(clippy::too_many_arguments)]
fn lower_typed_while_local_with_statements_scalar(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    initializer_node: u64,
    local_binding: &TypedNameBindingHeader,
    while_header: &TypedWhileHeader,
    body_statements: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
    scalar_kind: u8,
    scalar_name: &'static str,
    scalar_alignment: u32,
) -> Result<Module, TypedStatementLowerError> {
    let scalar_type = match scalar_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed while scalar must be Int32 or Float64",
            });
        }
    };
    let scalar_type_id = TypeId::new(0);
    if while_header.kind != TYPED_CONTROL_FLOW_KIND_WHILE {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while lowering requires a while header",
        });
    }
    if while_header.reserved != [0; 6] {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while reserved bytes must be zero",
        });
    }
    if while_header.type_kind != scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while local must use the selected scalar type",
        });
    }
    if body_statements.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed while body requires at least one statement",
        });
    }
    let mut terminal_control = None;
    let mut conditional_controls = Vec::new();
    for (index, body_statement) in body_statements.iter().enumerate() {
        match body_statement.kind {
            TYPED_STATEMENT_KIND_ASSIGN
                if body_statement.flags == 0
                    && body_statement.type_kind == scalar_kind
                    && body_statement.reserved == 0 => {}
            TYPED_STATEMENT_KIND_LET
                if body_statement.flags & !TYPED_STATEMENT_FLAG_MUTABLE == 0
                    && body_statement.type_kind == scalar_kind
                    && body_statement.reserved == 0
                    && body_statement.target_start != 0
                    && body_statement.target_end != 0 => {}
            TYPED_STATEMENT_KIND_BREAK
                if index + 1 == body_statements.len()
                    && body_statement.flags == 0
                    && body_statement.type_kind == 0
                    && body_statement.reserved == 0
                    && body_statement.target_start == 0
                    && body_statement.target_end == 0
                    && body_statement.expression_node == 0 =>
            {
                terminal_control = Some(body_statement.kind);
            }
            TYPED_STATEMENT_KIND_BREAK | TYPED_STATEMENT_KIND_CONTINUE
                if body_statement.flags == TYPED_STATEMENT_FLAG_CONDITIONAL
                    && body_statement.type_kind == TYPE_KIND_BOOL
                    && body_statement.reserved == 0
                    && body_statement.target_start == 0
                    && body_statement.target_end == 0 =>
            {
                conditional_controls.push((
                    index,
                    body_statement.kind,
                    body_statement.expression_node,
                ));
            }
            TYPED_STATEMENT_KIND_CONTINUE
                if index + 1 == body_statements.len()
                    && body_statement.flags == 0
                    && body_statement.type_kind == 0
                    && body_statement.reserved == 0
                    && body_statement.target_start == 0
                    && body_statement.target_end == 0
                    && body_statement.expression_node == 0 =>
            {
                terminal_control = Some(body_statement.kind);
            }
            _ => {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body must contain assignments and loop control",
                });
            }
        }
    }
    if !conditional_controls.is_empty() && terminal_control.is_some() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed while body may not mix terminal and conditional loop control",
        });
    }
    if ast.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while requires a typed expression AST",
        });
    }
    let while_span =
        typed_statement_span(source, source_id, while_header.start, while_header.end, 0)?;
    if local_binding.type_kind != scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while binding must use the selected scalar type",
        });
    }
    let local_span = typed_statement_span(
        source,
        source_id,
        local_binding.name_start,
        local_binding.name_end,
        0,
    )?;
    let local_name = source[local_span.start..local_span.end].to_owned();
    if !typed_statement_identifier(&local_name) {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while binding must be an ASCII identifier",
        });
    }
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    let mut parameters = Vec::with_capacity(bindings.len());
    for (index, binding) in bindings.iter().enumerate() {
        if binding.type_kind != scalar_kind {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed while parameters must match the selected scalar type",
            });
        }
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
            || name == local_name
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "typed while parameter names must be unique and not shadow the local",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: scalar_type_id,
            name: Some(name),
        });
    }
    let initializer_index = usize::try_from(initializer_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while initializer node is not representable",
        }
    })?;
    let initializer_ast =
        ast.get(initializer_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed while initializer node is outside the AST",
            })?;
    if initializer_ast.flags != 1 || initializer_ast.type_kind != scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while initializer must resolve to the selected scalar type",
        });
    }
    let initializer_span = typed_statement_span(
        source,
        source_id,
        initializer_ast.start,
        initializer_ast.end,
        0,
    )?;
    if initializer_span.end > while_span.start {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while initializer must precede the loop",
        });
    }
    let condition_index = usize::try_from(while_header.condition_node).map_err(|_| {
        TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while condition node is not representable",
        }
    })?;
    let condition_ast =
        ast.get(condition_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "typed while condition node is outside the AST",
            })?;
    if condition_ast.flags != 1 || condition_ast.type_kind != TYPE_KIND_BOOL {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while condition must resolve to Bool",
        });
    }
    let mut body_ranges = Vec::with_capacity(body_statements.len());
    let mut body_local_declarations = BTreeMap::<String, (Span, bool)>::new();
    let mut previous_end = while_span.start;
    for (index, body_statement) in body_statements.iter().enumerate() {
        let statement_span = typed_statement_span(
            source,
            source_id,
            body_statement.start,
            body_statement.end,
            index + 1,
        )?;
        if statement_span.start < while_span.start
            || statement_span.end > while_span.end
            || statement_span.start < previous_end
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: index + 1,
                message: "typed while body statements must be ordered inside the while span",
            });
        }
        if body_statement.kind == TYPED_STATEMENT_KIND_BREAK
            || body_statement.kind == TYPED_STATEMENT_KIND_CONTINUE
        {
            if body_statement.flags == TYPED_STATEMENT_FLAG_CONDITIONAL {
                let condition_index =
                    usize::try_from(body_statement.expression_node).map_err(|_| {
                        TypedStatementLowerError::InvalidStatement {
                            index: index + 1,
                            message: "typed while conditional control node is not representable",
                        }
                    })?;
                let condition_ast =
                    ast.get(condition_index)
                        .ok_or(TypedStatementLowerError::InvalidStatement {
                            index: index + 1,
                            message: "typed while conditional control node is outside the AST",
                        })?;
                if condition_ast.flags != 1 || condition_ast.type_kind != TYPE_KIND_BOOL {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: index + 1,
                        message: "typed while conditional control must resolve to Bool",
                    });
                }
                let condition_span = typed_statement_span(
                    source,
                    source_id,
                    condition_ast.start,
                    condition_ast.end,
                    index + 1,
                )?;
                if condition_span.start < statement_span.start
                    || condition_span.end > statement_span.end
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: index + 1,
                        message: "typed while conditional control expression is outside its span",
                    });
                }
                let prefix = source[statement_span.start..condition_span.start].trim();
                let suffix = source[condition_span.end..statement_span.end].trim();
                let keyword = if body_statement.kind == TYPED_STATEMENT_KIND_BREAK {
                    "break"
                } else {
                    "continue"
                };
                let expected_suffix = format!("{{ {keyword} }}");
                let expected_suffix_semicolon = format!("{{ {keyword}; }}");
                if prefix != "if"
                    || (suffix != expected_suffix && suffix != expected_suffix_semicolon)
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: index + 1,
                        message: "typed while conditional control span must match if <Bool> { break/continue }",
                    });
                }
            } else {
                let keyword = if body_statement.kind == TYPED_STATEMENT_KIND_BREAK {
                    "break"
                } else {
                    "continue"
                };
                if source[statement_span.start..statement_span.end].trim() != format!("{keyword};")
                {
                    return Err(TypedStatementLowerError::InvalidStatement {
                        index: index + 1,
                        message: "typed while loop-control span must match break; or continue;",
                    });
                }
            }
            previous_end = statement_span.end;
            continue;
        }
        let body_target_span = typed_statement_span(
            source,
            source_id,
            body_statement.target_start,
            body_statement.target_end,
            index + 1,
        )?;
        let body_target = &source[body_target_span.start..body_target_span.end];
        if body_target_span.start < statement_span.start
            || body_target_span.end > statement_span.end
            || !typed_statement_identifier(body_target)
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: index + 1,
                message: "typed while body target is invalid or out of range",
            });
        }
        let body_expression_index =
            usize::try_from(body_statement.expression_node).map_err(|_| {
                TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body expression node is not representable",
                }
            })?;
        let body_expression_ast =
            ast.get(body_expression_index)
                .ok_or(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body expression node is outside the AST",
                })?;
        let body_expression_span = typed_statement_span(
            source,
            source_id,
            body_expression_ast.start,
            body_expression_ast.end,
            index + 1,
        )?;
        if body_expression_span.start < statement_span.start
            || body_expression_span.end > statement_span.end
            || body_expression_ast.flags != 1
            || body_expression_ast.type_kind != scalar_kind
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: index + 1,
                message: "typed while body expression is unresolved or out of range",
            });
        }
        let body_prefix = source[statement_span.start..body_expression_span.start].trim();
        let body_suffix = source[body_expression_span.end..statement_span.end].trim();
        if body_statement.kind == TYPED_STATEMENT_KIND_LET {
            let expected_let_prefix = format!("let {body_target}: {scalar_name} =");
            let expected_var_prefix = format!("var {body_target}: {scalar_name} =");
            let declaration_matches = if body_statement.flags == TYPED_STATEMENT_FLAG_MUTABLE {
                body_prefix == expected_let_prefix || body_prefix == expected_var_prefix
            } else {
                body_prefix == expected_let_prefix
            };
            if !declaration_matches || body_suffix != ";" {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body source span does not match let/var syntax",
                });
            }
            if body_target == local_name
                || body_local_declarations.contains_key(body_target)
                || bindings.iter().any(|binding| {
                    typed_statement_span(
                        source,
                        source_id,
                        binding.name_start,
                        binding.name_end,
                        index + 1,
                    )
                    .ok()
                    .is_some_and(|span| &source[span.start..span.end] == body_target)
                })
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body let must not shadow an existing binding",
                });
            }
            body_local_declarations.insert(
                body_target.to_owned(),
                (
                    body_target_span,
                    body_statement.flags == TYPED_STATEMENT_FLAG_MUTABLE,
                ),
            );
        } else {
            if body_prefix != format!("{body_target} =") || body_suffix != ";" {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body source span does not match assignment syntax",
                });
            }
            if body_target != local_name
                && !body_local_declarations
                    .get(body_target)
                    .is_some_and(|(_, mutable)| *mutable)
            {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index: index + 1,
                    message: "typed while body assignment target must be a mutable visible local",
                });
            }
        }
        previous_end = statement_span.end;
        body_ranges.push((index, body_statement, statement_span, body_expression_span));
    }
    if body_ranges.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "typed while body must contain an assignment before loop control",
        });
    }
    let body_span = typed_statement_span(
        source,
        source_id,
        body_statements[0].start,
        body_statements[body_statements.len() - 1].end,
        1,
    )?;

    let bool_type = Type::Bool;
    let bool_type_id = TypeId::new(1);
    let mut types = vec![scalar_type, bool_type];
    let pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: scalar_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut next_value = parameters.len();
    let pointer = ValueId::new(next_value);
    next_value += 1;
    let mut imports = Vec::<Function>::new();
    let mut entry_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: pointer,
            ty: pointer_type,
        }),
        kind: InstructionKind::StackAlloc {
            ty: scalar_type_id,
            count: None,
        },
        span: Some(while_span),
    }];
    let mut body_local_bindings = BTreeMap::<String, TypedStatementLocal>::new();
    for (name, (declaration, mutable)) in &body_local_declarations {
        let local_pointer = ValueId::new(next_value);
        next_value += 1;
        entry_instructions.push(Instruction {
            result: Some(TypedValue {
                value: local_pointer,
                ty: pointer_type,
            }),
            kind: InstructionKind::StackAlloc {
                ty: scalar_type_id,
                count: None,
            },
            span: Some(*declaration),
        });
        body_local_bindings.insert(
            name.clone(),
            TypedStatementLocal {
                declaration: *declaration,
                pointer: local_pointer,
                mutable: *mutable,
            },
        );
    }
    let (initializer_value, initializer_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        initializer_node,
        bindings,
        call_bindings,
        call_candidates,
        arguments,
        &parameter_values,
        &mut types,
        &mut imports,
        &mut entry_instructions,
        &mut next_value,
        0,
    )?;
    if initializer_type != scalar_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while initializer type does not match the selected scalar type",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer,
            value: initializer_value,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(initializer_span),
    });
    let mut header_instructions = Vec::new();
    let header_loaded = ValueId::new(next_value);
    next_value += 1;
    header_instructions.push(Instruction {
        result: Some(TypedValue {
            value: header_loaded,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(while_span),
    });
    let mut visible_bindings = bindings.to_vec();
    visible_bindings.push(*local_binding);
    let mut body_visible_bindings = visible_bindings.clone();
    for local in body_local_bindings.values() {
        body_visible_bindings.push(TypedNameBindingHeader {
            name_start: local.declaration.start as u64,
            name_end: local.declaration.end as u64,
            type_kind: scalar_kind,
        });
    }
    let mut condition_values = parameter_values.clone();
    condition_values.insert(local_name.clone(), header_loaded);
    let (condition_value, condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        while_header.condition_node,
        &visible_bindings,
        call_bindings,
        call_candidates,
        arguments,
        &condition_values,
        &mut types,
        &mut imports,
        &mut header_instructions,
        &mut next_value,
        0,
    )?;
    if condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "typed while condition lowering did not produce Bool",
        });
    }
    let mut body_instructions = Vec::new();
    let body_loaded = ValueId::new(next_value);
    next_value += 1;
    body_instructions.push(Instruction {
        result: Some(TypedValue {
            value: body_loaded,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(body_span),
    });
    let mut segment_instructions = body_instructions;
    let mut segment_values = parameter_values;
    segment_values.insert(local_name.clone(), body_loaded);
    let mut segment_start = 0usize;
    let mut segment_id = BlockId::new(2);
    let mut segments = Vec::<(BlockId, Vec<Instruction>, Terminator)>::new();
    for (control_position, &(control_index, control_kind, condition_node)) in
        conditional_controls.iter().enumerate()
    {
        for (statement_index, body_statement, statement_span, _body_expression_span) in body_ranges
            .iter()
            .filter(|(index, _, _, _)| *index >= segment_start && *index < control_index)
        {
            typed_statement_lower_while_body_range(
                source,
                source_id,
                ast,
                body_statement,
                *statement_span,
                *statement_index,
                &body_visible_bindings,
                call_bindings,
                call_candidates,
                arguments,
                &mut segment_values,
                &mut types,
                &mut imports,
                &mut segment_instructions,
                &mut next_value,
                &body_local_bindings,
                &local_name,
                pointer,
                scalar_type_id,
            )?;
        }
        let (condition_value, condition_type) = typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            condition_node,
            &body_visible_bindings,
            call_bindings,
            call_candidates,
            arguments,
            &segment_values,
            &mut types,
            &mut imports,
            &mut segment_instructions,
            &mut next_value,
            control_index + 1,
        )?;
        if condition_type != bool_type_id {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: control_index + 1,
                message: "typed while conditional control lowering did not produce Bool",
            });
        }
        let then_target = if control_kind == TYPED_STATEMENT_KIND_BREAK {
            BlockId::new(3)
        } else {
            BlockId::new(1)
        };
        let is_final_control = control_index + 1 == body_statements.len();
        let else_target = if is_final_control {
            BlockId::new(1)
        } else {
            BlockId::new(4 + control_position)
        };
        segments.push((
            segment_id,
            std::mem::take(&mut segment_instructions),
            Terminator::Branch {
                condition: condition_value,
                then_target,
                then_arguments: Vec::new(),
                else_target,
                else_arguments: Vec::new(),
            },
        ));
        if is_final_control {
            break;
        }
        segment_start = control_index + 1;
        segment_id = BlockId::new(4 + control_position);
    }
    let last_control_is_final = conditional_controls
        .last()
        .is_some_and(|(index, _, _)| *index + 1 == body_statements.len());
    if conditional_controls.is_empty() || !last_control_is_final {
        for (statement_index, body_statement, statement_span, _body_expression_span) in body_ranges
            .iter()
            .filter(|(index, _, _, _)| *index >= segment_start)
        {
            typed_statement_lower_while_body_range(
                source,
                source_id,
                ast,
                body_statement,
                *statement_span,
                *statement_index,
                &body_visible_bindings,
                call_bindings,
                call_candidates,
                arguments,
                &mut segment_values,
                &mut types,
                &mut imports,
                &mut segment_instructions,
                &mut next_value,
                &body_local_bindings,
                &local_name,
                pointer,
                scalar_type_id,
            )?;
        }
        let target = if conditional_controls.is_empty()
            && terminal_control == Some(TYPED_STATEMENT_KIND_BREAK)
        {
            BlockId::new(3)
        } else {
            BlockId::new(1)
        };
        segments.push((
            segment_id,
            segment_instructions,
            Terminator::Jump {
                target,
                arguments: Vec::new(),
            },
        ));
    }
    let exit_value = ValueId::new(next_value);
    let exit_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: exit_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(while_span),
    }];
    let function_span = Span::new(source_id, 0, source.len());
    let (first_segment_id, first_segment_instructions, first_segment_terminator) =
        segments.remove(0);
    let mut blocks = vec![
        Block {
            id: BlockId::new(0),
            parameters: Vec::new(),
            instructions: entry_instructions,
            terminator: Terminator::Jump {
                target: BlockId::new(1),
                arguments: Vec::new(),
            },
            span: function_span,
        },
        Block {
            id: BlockId::new(1),
            parameters: Vec::new(),
            instructions: header_instructions,
            terminator: Terminator::Branch {
                condition: condition_value,
                then_target: BlockId::new(2),
                then_arguments: Vec::new(),
                else_target: BlockId::new(3),
                else_arguments: Vec::new(),
            },
            span: Some(while_span),
        },
        Block {
            id: first_segment_id,
            parameters: Vec::new(),
            instructions: first_segment_instructions,
            terminator: first_segment_terminator,
            span: Some(body_span),
        },
        Block {
            id: BlockId::new(3),
            parameters: Vec::new(),
            instructions: exit_instructions,
            terminator: Terminator::Return {
                value: Some(exit_value),
            },
            span: Some(while_span),
        },
    ];
    for (segment_id, segment_instructions, segment_terminator) in segments {
        blocks.push(Block {
            id: segment_id,
            parameters: Vec::new(),
            instructions: segment_instructions,
            terminator: segment_terminator,
            span: Some(body_span),
        });
    }
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_while".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: scalar_type_id,
        blocks,
        span: function_span,
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Lowers the first nested-loop Stage-2 slice without changing the existing
/// `TypedStatementHeader` layout. The contract intentionally keeps the shape
/// explicit: an outer Int32 loop has an assignment prefix, a mutable inner
/// Int32 loop with an assignment body, and an assignment tail. Both loop
/// conditions and all expressions use the same caller-owned typed AST.
///
/// This is an additive self-hosting boundary. It proves nested CFG ownership
/// and per-iteration inner initialization while leaving arbitrary nested
/// statement lists and nested loop-control targets for a later contract.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_nested_while_local(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    outer_tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_nested_while_local_scalar(
        source,
        source_id,
        ast,
        bindings,
        outer_initializer_node,
        outer_local_binding,
        outer_header,
        outer_prefix,
        inner_initializer,
        inner_local_binding,
        inner_header,
        inner_body,
        outer_tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
    )
}

/// Float64 counterpart of [`lower_typed_nested_while_local`].
/// Both nested loop locals use native 8-byte storage; conditions remain Bool
/// and the bounded assignment-only CFG contract is unchanged.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_nested_while_float_local(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    outer_tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_nested_while_local_scalar(
        source,
        source_id,
        ast,
        bindings,
        outer_initializer_node,
        outer_local_binding,
        outer_header,
        outer_prefix,
        inner_initializer,
        inner_local_binding,
        inner_header,
        inner_body,
        outer_tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
    )
}

/// Mixed scalar counterpart of [`lower_typed_nested_while_local`]. The outer
/// loop owns an Int32 local and the nested loop owns a Float64 local; all
/// expressions and storage remain in the native typed CFG.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_nested_while_mixed_scalar(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    outer_tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    lower_typed_nested_while_local_scalar(
        source,
        source_id,
        ast,
        bindings,
        outer_initializer_node,
        outer_local_binding,
        outer_header,
        outer_prefix,
        inner_initializer,
        inner_local_binding,
        inner_header,
        inner_body,
        outer_tail,
        call_bindings,
        call_candidates,
        arguments,
        TYPE_KIND_INTEGER,
        "Int32",
        4,
        TYPE_KIND_FLOAT,
        "Float64",
        8,
    )
}

#[allow(clippy::too_many_arguments)]
fn lower_typed_nested_while_local_scalar(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    outer_tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
    scalar_kind: u8,
    _scalar_name: &'static str,
    scalar_alignment: u32,
    inner_scalar_kind: u8,
    inner_scalar_name: &'static str,
    inner_scalar_alignment: u32,
) -> Result<Module, TypedStatementLowerError> {
    let scalar_type = match scalar_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "nested typed while scalar must be Int32 or Float64",
            });
        }
    };
    let inner_scalar_type = match inner_scalar_kind {
        TYPE_KIND_INTEGER => Type::Integer {
            signed: true,
            bits: 32,
        },
        TYPE_KIND_FLOAT => Type::Float { bits: 64 },
        _ => {
            return Err(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "nested typed while inner scalar must be Int32 or Float64",
            });
        }
    };
    let scalar_type_id = TypeId::new(0);
    let inner_scalar_type_id = if scalar_type == inner_scalar_type {
        scalar_type_id
    } else {
        TypeId::new(1)
    };
    let bool_type_id = if inner_scalar_type_id == scalar_type_id {
        TypeId::new(1)
    } else {
        TypeId::new(2)
    };
    if ast.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while requires a typed expression AST",
        });
    }
    if outer_header.kind != TYPED_CONTROL_FLOW_KIND_WHILE
        || inner_header.kind != TYPED_CONTROL_FLOW_KIND_WHILE
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while lowering requires while headers",
        });
    }
    if outer_header.reserved != [0; 6] || inner_header.reserved != [0; 6] {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while reserved bytes must be zero",
        });
    }
    if outer_header.type_kind != scalar_kind || inner_header.type_kind != inner_scalar_kind {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while headers must use the selected scalar type",
        });
    }
    if outer_prefix.is_empty() || inner_body.is_empty() || outer_tail.is_empty() {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested typed while requires prefix, inner body and tail assignments",
        });
    }

    let outer_span =
        typed_statement_span(source, source_id, outer_header.start, outer_header.end, 0)?;
    let inner_span =
        typed_statement_span(source, source_id, inner_header.start, inner_header.end, 0)?;
    if inner_span.start <= outer_span.start || inner_span.end >= outer_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while must be fully contained in the outer loop",
        });
    }

    let outer_local_span = typed_statement_span(
        source,
        source_id,
        outer_local_binding.name_start,
        outer_local_binding.name_end,
        0,
    )?;
    let inner_local_span = typed_statement_span(
        source,
        source_id,
        inner_local_binding.name_start,
        inner_local_binding.name_end,
        0,
    )?;
    if outer_local_binding.type_kind != scalar_kind
        || inner_local_binding.type_kind != inner_scalar_kind
        || !typed_statement_identifier(&source[outer_local_span.start..outer_local_span.end])
        || !typed_statement_identifier(&source[inner_local_span.start..inner_local_span.end])
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while bindings must be ASCII selected-scalar identifiers",
        });
    }
    let outer_name = source[outer_local_span.start..outer_local_span.end].to_owned();
    let inner_name = source[inner_local_span.start..inner_local_span.end].to_owned();
    if outer_name == inner_name {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while locals must have distinct names",
        });
    }

    let initializer_index = |node: u64, index: usize| {
        usize::try_from(node).map_err(|_| TypedStatementLowerError::InvalidStatement {
            index,
            message: "nested typed while expression node is not representable",
        })
    };
    let checked_expression = |node: u64,
                              expected_type: u8,
                              region: Span,
                              index: usize|
     -> Result<Span, TypedStatementLowerError> {
        let node_index = initializer_index(node, index)?;
        let expression = ast
            .get(node_index)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while expression node is outside the AST",
            })?;
        if expression.flags != 1 || expression.type_kind != expected_type {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while expression is unresolved or has a mismatched type",
            });
        }
        let span =
            typed_statement_span(source, source_id, expression.start, expression.end, index)?;
        if span.start < region.start || span.end > region.end {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while expression is outside its region",
            });
        }
        Ok(span)
    };
    let outer_initializer_ast_span = checked_expression(
        outer_initializer_node,
        scalar_kind,
        Span {
            source: source_id,
            start: 0,
            end: outer_span.start,
        },
        0,
    )?;
    let _outer_condition_span =
        checked_expression(outer_header.condition_node, TYPE_KIND_BOOL, outer_span, 0)?;
    if outer_initializer_ast_span.end > outer_span.start {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while outer initializer must precede the loop",
        });
    }
    let _inner_condition_span =
        checked_expression(inner_header.condition_node, TYPE_KIND_BOOL, inner_span, 0)?;

    let validate_assignment = |statement: &TypedStatementHeader,
                               index: usize,
                               region: Span,
                               expected_target: &str,
                               expected_kind: u8,
                               previous_end: &mut usize|
     -> Result<(Span, Span), TypedStatementLowerError> {
        if statement.kind != TYPED_STATEMENT_KIND_ASSIGN
            || statement.flags != 0
            || statement.type_kind != expected_kind
            || statement.reserved != 0
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while segments must use the selected scalar type",
            });
        }
        let statement_span =
            typed_statement_span(source, source_id, statement.start, statement.end, index)?;
        if statement_span.start < region.start
            || statement_span.end > region.end
            || statement_span.start < *previous_end
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while assignments must be ordered inside their region",
            });
        }
        let target_span = typed_statement_span(
            source,
            source_id,
            statement.target_start,
            statement.target_end,
            index,
        )?;
        let target = &source[target_span.start..target_span.end];
        let expression_span =
            checked_expression(statement.expression_node, expected_kind, region, index)?;
        if target != expected_target
            || target_span.start < statement_span.start
            || target_span.end > statement_span.end
            || expression_span.start < statement_span.start
            || expression_span.end > statement_span.end
            || source[statement_span.start..expression_span.start].trim() != format!("{target} =")
            || source[expression_span.end..statement_span.end].trim() != ";"
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while assignment span does not match target syntax",
            });
        }
        *previous_end = statement_span.end;
        Ok((statement_span, expression_span))
    };

    let inner_initializer_span = typed_statement_span(
        source,
        source_id,
        inner_initializer.start,
        inner_initializer.end,
        1,
    )?;
    let inner_initializer_expression_span = checked_expression(
        inner_initializer.expression_node,
        inner_scalar_kind,
        outer_span,
        1,
    )?;
    if inner_initializer.kind != TYPED_STATEMENT_KIND_LET
        || inner_initializer.flags != TYPED_STATEMENT_FLAG_MUTABLE
        || inner_initializer.type_kind != inner_scalar_kind
        || inner_initializer.reserved != 0
        || inner_initializer.target_start != inner_local_binding.name_start
        || inner_initializer.target_end != inner_local_binding.name_end
        || inner_initializer_span.start < outer_span.start
        || inner_initializer_span.end > inner_span.start
        || inner_initializer_span.start
            < outer_prefix
                .last()
                .map_or(outer_span.start, |s| s.end as usize)
        || inner_initializer_expression_span.start < inner_initializer_span.start
        || inner_initializer_expression_span.end > inner_initializer_span.end
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested typed while inner initializer is invalid or out of order",
        });
    }
    let inner_prefix = if inner_initializer.flags == TYPED_STATEMENT_FLAG_MUTABLE {
        format!("var {inner_name}: {inner_scalar_name} =")
    } else {
        format!("let {inner_name}: {inner_scalar_name} =")
    };
    if source[inner_initializer_span.start..inner_initializer_expression_span.start].trim()
        != inner_prefix
        || source[inner_initializer_expression_span.end..inner_initializer_span.end].trim() != ";"
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested typed while inner initializer span does not match var syntax",
        });
    }

    let mut outer_prefix_ranges = Vec::with_capacity(outer_prefix.len());
    let mut previous_end = outer_span.start;
    for (index, statement) in outer_prefix.iter().enumerate() {
        let (statement_span, expression_span) = validate_assignment(
            statement,
            index + 2,
            Span {
                source: source_id,
                start: outer_span.start,
                end: inner_initializer_span.start,
            },
            &outer_name,
            scalar_kind,
            &mut previous_end,
        )?;
        outer_prefix_ranges.push((*statement, statement_span, expression_span));
    }
    let mut inner_body_ranges = Vec::with_capacity(inner_body.len());
    previous_end = inner_span.start;
    for (index, statement) in inner_body.iter().enumerate() {
        let (statement_span, expression_span) = validate_assignment(
            statement,
            index + 3,
            inner_span,
            &inner_name,
            inner_scalar_kind,
            &mut previous_end,
        )?;
        inner_body_ranges.push((*statement, statement_span, expression_span));
    }
    let mut outer_tail_ranges = Vec::with_capacity(outer_tail.len());
    previous_end = inner_span.end;
    for (index, statement) in outer_tail.iter().enumerate() {
        let (statement_span, expression_span) = validate_assignment(
            statement,
            index + 4,
            outer_span,
            &outer_name,
            scalar_kind,
            &mut previous_end,
        )?;
        outer_tail_ranges.push((*statement, statement_span, expression_span));
    }
    if outer_prefix_ranges
        .last()
        .is_some_and(|(_, span, _)| span.end > inner_initializer_span.start)
        || outer_tail_ranges
            .first()
            .is_some_and(|(_, span, _)| span.start < inner_span.end)
        || inner_body_ranges
            .last()
            .is_some_and(|(_, span, _)| span.end > inner_span.end)
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested typed while segment ordering is invalid",
        });
    }

    let bool_type = Type::Bool;
    let mut types = vec![scalar_type];
    if inner_scalar_type_id != scalar_type_id {
        types.push(inner_scalar_type);
    }
    types.push(bool_type);
    let outer_pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: scalar_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let inner_pointer_type = typed_statement_merge_type(
        &mut types,
        Type::Pointer {
            pointee: inner_scalar_type_id,
            address_space: AddressSpace::Stack,
        },
    );
    let mut parameter_values = BTreeMap::<String, ValueId>::new();
    let mut parameters = Vec::with_capacity(bindings.len());
    for (index, binding) in bindings.iter().enumerate() {
        let binding_type = match binding.type_kind {
            kind if kind == scalar_kind => scalar_type_id,
            kind if kind == inner_scalar_kind => inner_scalar_type_id,
            _ => {
                return Err(TypedStatementLowerError::InvalidStatement {
                    index,
                    message: "nested typed while parameters must use Int32 or Float64",
                });
            }
        };
        let span = typed_statement_span(
            source,
            source_id,
            binding.name_start,
            binding.name_end,
            index,
        )?;
        let name = source[span.start..span.end].to_owned();
        if !typed_statement_identifier(&name)
            || parameter_values
                .insert(name.clone(), ValueId::new(index))
                .is_some()
            || name == outer_name
            || name == inner_name
        {
            return Err(TypedStatementLowerError::InvalidStatement {
                index,
                message: "nested typed while parameter names must be unique and not shadow locals",
            });
        }
        parameters.push(Parameter {
            value: ValueId::new(index),
            ty: binding_type,
            name: Some(name),
        });
    }
    let mut next_value = parameters.len();
    let outer_pointer = ValueId::new(next_value);
    next_value += 1;
    let inner_pointer = ValueId::new(next_value);
    next_value += 1;
    let function_span = Span::new(source_id, 0, source.len());
    let mut entry_instructions = vec![
        Instruction {
            result: Some(TypedValue {
                value: outer_pointer,
                ty: outer_pointer_type,
            }),
            kind: InstructionKind::StackAlloc {
                ty: scalar_type_id,
                count: None,
            },
            span: Some(outer_span),
        },
        Instruction {
            result: Some(TypedValue {
                value: inner_pointer,
                ty: inner_pointer_type,
            }),
            kind: InstructionKind::StackAlloc {
                ty: inner_scalar_type_id,
                count: None,
            },
            span: Some(inner_span),
        },
    ];
    let mut imports = Vec::<Function>::new();
    let outer_visible = {
        let mut visible = bindings.to_vec();
        visible.push(*outer_local_binding);
        visible
    };
    let all_visible = {
        let mut visible = outer_visible.clone();
        visible.push(*inner_local_binding);
        visible
    };
    let (outer_initializer_value, outer_initializer_type) =
        typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            outer_initializer_node,
            bindings,
            call_bindings,
            call_candidates,
            arguments,
            &parameter_values,
            &mut types,
            &mut imports,
            &mut entry_instructions,
            &mut next_value,
            0,
        )?;
    if outer_initializer_type != scalar_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while outer initializer must produce the selected scalar type",
        });
    }
    entry_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer: outer_pointer,
            value: outer_initializer_value,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(outer_initializer_ast_span),
    });

    let mut outer_header_instructions = Vec::new();
    let outer_header_value = ValueId::new(next_value);
    next_value += 1;
    outer_header_instructions.push(Instruction {
        result: Some(TypedValue {
            value: outer_header_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(outer_span),
    });
    let mut outer_condition_values = parameter_values.clone();
    outer_condition_values.insert(outer_name.clone(), outer_header_value);
    let (outer_condition_value, outer_condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        outer_header.condition_node,
        &outer_visible,
        call_bindings,
        call_candidates,
        arguments,
        &outer_condition_values,
        &mut types,
        &mut imports,
        &mut outer_header_instructions,
        &mut next_value,
        0,
    )?;
    if outer_condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 0,
            message: "nested typed while outer condition must produce Bool",
        });
    }

    let mut outer_body_instructions = Vec::new();
    let outer_body_value = ValueId::new(next_value);
    next_value += 1;
    outer_body_instructions.push(Instruction {
        result: Some(TypedValue {
            value: outer_body_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(outer_prefix_ranges[0].1),
    });
    let mut outer_body_values = parameter_values.clone();
    outer_body_values.insert(outer_name.clone(), outer_body_value);
    let mut body_local_bindings = BTreeMap::new();
    body_local_bindings.insert(
        inner_name.clone(),
        TypedStatementLocal {
            declaration: inner_local_span,
            pointer: inner_pointer,
            mutable: true,
        },
    );
    for (index, (statement, statement_span, _)) in outer_prefix_ranges.iter().enumerate() {
        typed_statement_lower_while_body_range(
            source,
            source_id,
            ast,
            statement,
            *statement_span,
            index,
            &all_visible,
            call_bindings,
            call_candidates,
            arguments,
            &mut outer_body_values,
            &mut types,
            &mut imports,
            &mut outer_body_instructions,
            &mut next_value,
            &body_local_bindings,
            &outer_name,
            outer_pointer,
            scalar_type_id,
        )?;
    }
    let mut inner_initializer_values = outer_body_values.clone();
    let (inner_initializer_value, inner_initializer_type) =
        typed_statement_lower_expression_for_cfg(
            source,
            source_id,
            ast,
            inner_initializer.expression_node,
            &outer_visible,
            call_bindings,
            call_candidates,
            arguments,
            &inner_initializer_values,
            &mut types,
            &mut imports,
            &mut outer_body_instructions,
            &mut next_value,
            1,
        )?;
    if inner_initializer_type != inner_scalar_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 1,
            message: "nested typed while inner initializer must produce the selected scalar type",
        });
    }
    outer_body_instructions.push(Instruction {
        result: None,
        kind: InstructionKind::Store {
            pointer: inner_pointer,
            value: inner_initializer_value,
            alignment: inner_scalar_alignment,
            volatile: false,
        },
        span: Some(inner_initializer_span),
    });
    inner_initializer_values.insert(inner_name.clone(), inner_initializer_value);

    let mut inner_header_instructions = Vec::new();
    let inner_outer_value = ValueId::new(next_value);
    next_value += 1;
    let inner_header_value = ValueId::new(next_value);
    next_value += 1;
    inner_header_instructions.extend([
        Instruction {
            result: Some(TypedValue {
                value: inner_outer_value,
                ty: scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: outer_pointer,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
        Instruction {
            result: Some(TypedValue {
                value: inner_header_value,
                ty: inner_scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: inner_pointer,
                alignment: inner_scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
    ]);
    let mut inner_condition_values = parameter_values.clone();
    inner_condition_values.insert(outer_name.clone(), inner_outer_value);
    inner_condition_values.insert(inner_name.clone(), inner_header_value);
    let (inner_condition_value, inner_condition_type) = typed_statement_lower_expression_for_cfg(
        source,
        source_id,
        ast,
        inner_header.condition_node,
        &all_visible,
        call_bindings,
        call_candidates,
        arguments,
        &inner_condition_values,
        &mut types,
        &mut imports,
        &mut inner_header_instructions,
        &mut next_value,
        2,
    )?;
    if inner_condition_type != bool_type_id {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: 2,
            message: "nested typed while inner condition must produce Bool",
        });
    }

    let mut inner_body_instructions = Vec::new();
    let inner_body_outer_value = ValueId::new(next_value);
    next_value += 1;
    let inner_body_value = ValueId::new(next_value);
    next_value += 1;
    inner_body_instructions.extend([
        Instruction {
            result: Some(TypedValue {
                value: inner_body_outer_value,
                ty: scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: outer_pointer,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
        Instruction {
            result: Some(TypedValue {
                value: inner_body_value,
                ty: inner_scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: inner_pointer,
                alignment: inner_scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
    ]);
    let mut inner_body_values = parameter_values.clone();
    inner_body_values.insert(outer_name.clone(), inner_body_outer_value);
    inner_body_values.insert(inner_name.clone(), inner_body_value);
    for (index, (statement, statement_span, _)) in inner_body_ranges.iter().enumerate() {
        typed_statement_lower_while_body_range(
            source,
            source_id,
            ast,
            statement,
            *statement_span,
            index,
            &all_visible,
            call_bindings,
            call_candidates,
            arguments,
            &mut inner_body_values,
            &mut types,
            &mut imports,
            &mut inner_body_instructions,
            &mut next_value,
            &BTreeMap::from([(
                inner_name.clone(),
                TypedStatementLocal {
                    declaration: inner_local_span,
                    pointer: inner_pointer,
                    mutable: true,
                },
            )]),
            &inner_name,
            inner_pointer,
            inner_scalar_type_id,
        )?;
    }

    let mut inner_exit_instructions = Vec::new();
    let inner_exit_outer_value = ValueId::new(next_value);
    next_value += 1;
    let inner_exit_value = ValueId::new(next_value);
    next_value += 1;
    inner_exit_instructions.extend([
        Instruction {
            result: Some(TypedValue {
                value: inner_exit_outer_value,
                ty: scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: outer_pointer,
                alignment: scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
        Instruction {
            result: Some(TypedValue {
                value: inner_exit_value,
                ty: inner_scalar_type_id,
            }),
            kind: InstructionKind::Load {
                pointer: inner_pointer,
                alignment: inner_scalar_alignment,
                volatile: false,
            },
            span: Some(inner_span),
        },
    ]);
    let mut outer_tail_values = parameter_values.clone();
    outer_tail_values.insert(outer_name.clone(), inner_exit_outer_value);
    outer_tail_values.insert(inner_name.clone(), inner_exit_value);
    let empty_locals = BTreeMap::from([(
        inner_name.clone(),
        TypedStatementLocal {
            declaration: inner_local_span,
            pointer: inner_pointer,
            mutable: true,
        },
    )]);
    for (index, (statement, statement_span, _)) in outer_tail_ranges.iter().enumerate() {
        typed_statement_lower_while_body_range(
            source,
            source_id,
            ast,
            statement,
            *statement_span,
            index,
            &all_visible,
            call_bindings,
            call_candidates,
            arguments,
            &mut outer_tail_values,
            &mut types,
            &mut imports,
            &mut inner_exit_instructions,
            &mut next_value,
            &empty_locals,
            &outer_name,
            outer_pointer,
            scalar_type_id,
        )?;
    }

    let outer_exit_value = ValueId::new(next_value);
    let outer_exit_instructions = vec![Instruction {
        result: Some(TypedValue {
            value: outer_exit_value,
            ty: scalar_type_id,
        }),
        kind: InstructionKind::Load {
            pointer: outer_pointer,
            alignment: scalar_alignment,
            volatile: false,
        },
        span: Some(outer_span),
    }];
    let blocks = vec![
        Block {
            id: BlockId::new(0),
            parameters: Vec::new(),
            instructions: entry_instructions,
            terminator: Terminator::Jump {
                target: BlockId::new(1),
                arguments: Vec::new(),
            },
            span: function_span,
        },
        Block {
            id: BlockId::new(1),
            parameters: Vec::new(),
            instructions: outer_header_instructions,
            terminator: Terminator::Branch {
                condition: outer_condition_value,
                then_target: BlockId::new(2),
                then_arguments: Vec::new(),
                else_target: BlockId::new(6),
                else_arguments: Vec::new(),
            },
            span: Some(outer_span),
        },
        Block {
            id: BlockId::new(2),
            parameters: Vec::new(),
            instructions: outer_body_instructions,
            terminator: Terminator::Jump {
                target: BlockId::new(3),
                arguments: Vec::new(),
            },
            span: Some(outer_prefix_ranges[0].1),
        },
        Block {
            id: BlockId::new(3),
            parameters: Vec::new(),
            instructions: inner_header_instructions,
            terminator: Terminator::Branch {
                condition: inner_condition_value,
                then_target: BlockId::new(4),
                then_arguments: Vec::new(),
                else_target: BlockId::new(5),
                else_arguments: Vec::new(),
            },
            span: Some(inner_span),
        },
        Block {
            id: BlockId::new(4),
            parameters: Vec::new(),
            instructions: inner_body_instructions,
            terminator: Terminator::Jump {
                target: BlockId::new(3),
                arguments: Vec::new(),
            },
            span: Some(inner_body_ranges[0].1),
        },
        Block {
            id: BlockId::new(5),
            parameters: Vec::new(),
            instructions: inner_exit_instructions,
            terminator: Terminator::Jump {
                target: BlockId::new(1),
                arguments: Vec::new(),
            },
            span: Some(inner_span),
        },
        Block {
            id: BlockId::new(6),
            parameters: Vec::new(),
            instructions: outer_exit_instructions,
            terminator: Terminator::Return {
                value: Some(outer_exit_value),
            },
            span: Some(outer_span),
        },
    ];
    let function = Function {
        id: FunctionId::new(0),
        name: "__typed_nested_while".to_owned(),
        linkage: Linkage::Export,
        parameters,
        result: scalar_type_id,
        blocks,
        span: function_span,
    };
    let mut functions = Vec::with_capacity(imports.len() + 1);
    functions.push(function);
    functions.extend(imports);
    let module = Module { types, functions };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

/// Extends [`lower_typed_nested_while_local`] with one unconditional terminal
/// `break;` or `continue;` in the inner loop body. The assignment prefix is
/// still lowered by the bounded nested-loop contract; the control statement
/// only changes the inner body edge (`break` -> inner exit, `continue` -> inner
/// header). Conditional control and control in the outer loop remain separate
/// contracts so the target loop is explicit and cannot be inferred from a
/// flattened statement stream.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_nested_while_local_with_terminal_control(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    inner_terminal_control: &TypedStatementHeader,
    outer_tail: &[TypedStatementHeader],
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    if !matches!(
        inner_terminal_control.kind,
        TYPED_STATEMENT_KIND_BREAK | TYPED_STATEMENT_KIND_CONTINUE
    ) || inner_terminal_control.flags != 0
        || inner_terminal_control.type_kind != 0
        || inner_terminal_control.reserved != 0
        || inner_terminal_control.target_start != 0
        || inner_terminal_control.target_end != 0
        || inner_terminal_control.expression_node != 0
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: inner_body.len() + 1,
            message: "nested typed while terminal control must be an unconditional break or continue",
        });
    }
    let terminal_span = typed_statement_span(
        source,
        source_id,
        inner_terminal_control.start,
        inner_terminal_control.end,
        inner_body.len() + 1,
    )?;
    let inner_span =
        typed_statement_span(source, source_id, inner_header.start, inner_header.end, 0)?;
    let previous_end = inner_body
        .last()
        .map(|statement| statement.end as usize)
        .unwrap_or(inner_span.start);
    if terminal_span.start < previous_end || terminal_span.end > inner_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: inner_body.len() + 1,
            message: "nested typed while terminal control must follow the inner body",
        });
    }
    let keyword = if inner_terminal_control.kind == TYPED_STATEMENT_KIND_BREAK {
        "break"
    } else {
        "continue"
    };
    if source[terminal_span.start..terminal_span.end].trim() != format!("{keyword};") {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: inner_body.len() + 1,
            message: "nested typed while terminal control span must match break; or continue;",
        });
    }

    let mut module = lower_typed_nested_while_local(
        source,
        source_id,
        ast,
        bindings,
        outer_initializer_node,
        outer_local_binding,
        outer_header,
        outer_prefix,
        inner_initializer,
        inner_local_binding,
        inner_header,
        inner_body,
        outer_tail,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let function =
        module
            .functions
            .get_mut(0)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "nested typed while function is missing",
            })?;
    let inner_body_block =
        function
            .blocks
            .get_mut(4)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: inner_body.len() + 1,
                message: "nested typed while inner body block is missing",
            })?;
    inner_body_block.span = Some(terminal_span);
    inner_body_block.terminator = Terminator::Jump {
        target: if inner_terminal_control.kind == TYPED_STATEMENT_KIND_BREAK {
            BlockId::new(5)
        } else {
            BlockId::new(3)
        },
        arguments: Vec::new(),
    };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

