/// Extends the nested-loop contract with one unconditional terminal control
/// statement in the outer loop, after the inner loop and its assignment tail.
/// The control target is explicit: `break;` exits the outer loop, while
/// `continue;` jumps to the outer header. Inner-loop control remains owned by
/// the separate nested control entry points so a flat statement stream cannot
/// accidentally target the wrong loop.
#[allow(clippy::too_many_arguments)]
pub fn lower_typed_nested_while_local_with_outer_terminal_control(
    source: &str,
    source_id: SourceId,
    ast: &[TypedExpressionAstNodeHeader],
    bindings: &[TypedNameBindingHeader],
    outer_initializer_node: u64,
    outer_local_binding: &TypedNameBindingHeader,
    outer_header: &TypedWhileHeader,
    outer_prefix: &[TypedStatementHeader],
    inner_initializer: &TypedStatementHeader,
    inner_local_binding: &TypedNameBindingHeader,
    inner_header: &TypedWhileHeader,
    inner_body: &[TypedStatementHeader],
    outer_tail: &[TypedStatementHeader],
    outer_terminal_control: &TypedStatementHeader,
    call_bindings: &[TypedCallBindingHeader],
    call_candidates: &[TypedCallCandidateHeader],
    arguments: &[ExpressionAstArgumentHeader],
) -> Result<Module, TypedStatementLowerError> {
    let control_index = outer_tail.len() + inner_body.len() + 2;
    if !matches!(
        outer_terminal_control.kind,
        TYPED_STATEMENT_KIND_BREAK | TYPED_STATEMENT_KIND_CONTINUE
    ) || outer_terminal_control.flags != 0
        || outer_terminal_control.type_kind != 0
        || outer_terminal_control.reserved != 0
        || outer_terminal_control.target_start != 0
        || outer_terminal_control.target_end != 0
        || outer_terminal_control.expression_node != 0
    {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: control_index,
            message: "nested typed while outer control must be an unconditional break or continue",
        });
    }
    let control_span = typed_statement_span(
        source,
        source_id,
        outer_terminal_control.start,
        outer_terminal_control.end,
        control_index,
    )?;
    let outer_span =
        typed_statement_span(source, source_id, outer_header.start, outer_header.end, 0)?;
    let previous_end = outer_tail
        .last()
        .map(|statement| statement.end as usize)
        .unwrap_or(outer_span.start);
    if control_span.start < previous_end || control_span.end > outer_span.end {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: control_index,
            message: "nested typed while outer control must follow the outer tail",
        });
    }
    let keyword = if outer_terminal_control.kind == TYPED_STATEMENT_KIND_BREAK {
        "break"
    } else {
        "continue"
    };
    if source[control_span.start..control_span.end].trim() != format!("{keyword};") {
        return Err(TypedStatementLowerError::InvalidStatement {
            index: control_index,
            message: "nested typed while outer control span must match break; or continue;",
        });
    }

    let mut module = lower_typed_nested_while_local(
        source,
        source_id,
        ast,
        bindings,
        outer_initializer_node,
        outer_local_binding,
        outer_header,
        outer_prefix,
        inner_initializer,
        inner_local_binding,
        inner_header,
        inner_body,
        outer_tail,
        call_bindings,
        call_candidates,
        arguments,
    )?;
    let function =
        module
            .functions
            .get_mut(0)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: 0,
                message: "nested typed while function is missing",
            })?;
    let outer_tail_block =
        function
            .blocks
            .get_mut(5)
            .ok_or(TypedStatementLowerError::InvalidStatement {
                index: control_index,
                message: "nested typed while outer tail block is missing",
            })?;
    outer_tail_block.span = Some(control_span);
    outer_tail_block.terminator = Terminator::Jump {
        target: if outer_terminal_control.kind == TYPED_STATEMENT_KIND_BREAK {
            BlockId::new(6)
        } else {
            BlockId::new(1)
        },
        arguments: Vec::new(),
    };
    let errors = verify(&module);
    if errors.is_empty() {
        Ok(module)
    } else {
        Err(TypedStatementLowerError::Verification(errors))
    }
}

