    #[test]
    fn rejects_invalid_magic_and_impossible_capture_record_count() {
        let mut invalid_magic = capture_bytes();
        invalid_magic[0] = b'X';
        assert!(decode_stage2_capture(&invalid_magic).is_err());

        let mut impossible_count = capture_bytes();
        let count_offset = 8 + 8 + SOURCE.len() + 8 * 8;
        impossible_count[count_offset..count_offset + 8].copy_from_slice(&u64::MAX.to_le_bytes());
        assert!(decode_stage2_capture(&impossible_count).is_err());
    }

    #[test]
    fn decodes_typed_while_local_capture() {
        let source = "fn local_value() -> Int32 { var counter: Int32 = 0; while counter < 3 { counter = counter + 1; } return counter; }";
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"JST2WHL1");
        bytes.extend_from_slice(&(source.len() as u64).to_le_bytes());
        bytes.extend_from_slice(source.as_bytes());
        for value in [source.len() as u64, 1, 1, 8, 8, 0, 7, 0] {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes.extend_from_slice(&0u64.to_le_bytes());
        bytes.extend_from_slice(&1u64.to_le_bytes());
        for value in [3u64, 40, 96] {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes.extend_from_slice(&[3, 2, 0, 0, 0, 0, 0, 0]);
        bytes.extend_from_slice(&1u64.to_le_bytes());
        for value in [44u64, 51] {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes.extend_from_slice(&[2, 0, 0, 0, 0, 0, 0, 0]);
        bytes.extend_from_slice(&1u64.to_le_bytes());
        bytes.extend_from_slice(&[2, 0, 2, 0]);
        for value in [44u64, 51, 6, 44, 60] {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        bytes.extend_from_slice(&8u64.to_le_bytes());
        for node in 0..8u64 {
            bytes.extend_from_slice(&[if node == 3 || node == 6 { 7 } else { 2 }, 2, 1, 0]);
            for value in [0u64, 0, 0, node, node + 1] {
                bytes.extend_from_slice(&value.to_le_bytes());
            }
        }
        let capture = decode_typed_while_local_capture(&bytes).expect("typed while capture");
        assert_eq!(capture.summary.ast_nodes_required, 8);
        assert_eq!(capture.control.condition_node, 3);
        assert_eq!(capture.binding.type_kind, 2);
        assert_eq!(capture.body.expression_node, 6);
        assert_eq!(capture.ast.len(), 8);
    }

