    #[test]
    fn imports_four_bounded_zero_argument_direct_calls_in_distinct_functions() {
        let source = FOUR_ZERO_ARGUMENT_DIRECT_CALL_SOURCE;
        let span = |needle: &str| {
            let start = source.find(needle).expect("four-call fixture span");
            [start as u64, (start + needle.len()) as u64]
        };
        let declaration_names = ["main", "first", "second", "third", "fourth"];
        let call_names = ["first()", "second()", "third()", "fourth()"];
        let return_names = [
            "return first();",
            "return second();",
            "return third();",
            "return fourth();",
        ];
        let mut bounds = Vec::new();
        for declaration in declaration_names {
            let name = source
                .find(&format!("fn {declaration}"))
                .map(|offset| offset + 3)
                .expect("function declaration");
            let body = source[name..]
                .find('{')
                .map(|offset| name + offset)
                .expect("function body");
            let end = source[body..]
                .find('}')
                .map(|offset| body + offset + 1)
                .expect("function end");
            bounds.push((name, body, end));
        }
        let summary = Stage2JirSummary {
            functions_seen: 5,
            statements_seen: 5,
            calls_seen: 9,
            records_required: 21,
            records_emitted: 21,
            functions_lowered: 5,
            errors: 0,
            status_flags: 7,
        };
        let mut records = vec![record([1, 1, 2, 1], [0, 0, 0], 32, [0, 0])];
        for function_index in 0..4usize {
            let (name, body, end) = bounds[function_index];
            records.push(record(
                [2, 1, 2, 1],
                [function_index as u64, 0, 0],
                0,
                [name as u64, end as u64],
            ));
            records.push(record(
                [3, 1, 0, 0],
                [function_index as u64, 0, 0],
                0,
                [body as u64, end as u64],
            ));
            records.push(record_with_operands(
                [STAGE2_JIR_RECORD_DIRECT_CALL, 1, 2, 1],
                [function_index as u64, 0, 0],
                [(function_index + 1) as u64, 0],
                span(call_names[function_index]),
            ));
            records.push(record(
                [5, 1, 2, 1],
                [function_index as u64, 0, 0],
                0,
                span(return_names[function_index]),
            ));
        }
        let (fourth_name, fourth_body, fourth_end) = bounds[4];
        records.push(record(
            [2, 1, 2, 1],
            [4, 0, 0],
            0,
            [fourth_name as u64, fourth_end as u64],
        ));
        records.push(record(
            [3, 1, 0, 0],
            [4, 0, 0],
            0,
            [fourth_body as u64, fourth_end as u64],
        ));
        records.push(record([4, 1, 2, 0], [4, 0, 0], 42, span("42")));
        records.push(record([5, 1, 2, 1], [4, 0, 0], 0, span("return 42;")));
        let module = import_stage2_jir(source, source_id_for(source), summary, &records)
            .expect("four bounded direct calls should import");
        assert!(verify(&module).is_empty());
        assert_eq!(module.functions.len(), 5);
        for function in &module.functions[..4] {
            assert!(
                function.blocks[0]
                    .instructions
                    .iter()
                    .any(|instruction| matches!(
                        instruction.kind,
                        jadren_jir::InstructionKind::Call { .. }
                    ))
            );
        }
    }

