    #[test]
    fn imports_two_zero_argument_direct_call_result_bindings_in_one_function() {
        let source = "fn helper() -> Int32 { return 42; }\n\nfn main() -> Int32 { let result: Int32 = helper(); let other: Int32 = helper(); return result + other; }";
        let span = |needle: &str| {
            let start = source
                .find(needle)
                .expect("same-function result-binding span");
            [start as u64, (start + needle.len()) as u64]
        };
        let helper_start = source.find("helper").expect("helper name");
        let helper_end = source.find("}\n\nfn main").expect("helper end") + 1;
        let helper_open = source[helper_start..]
            .find('{')
            .map(|offset| helper_start + offset)
            .expect("helper block");
        let main_start = source.rfind("main").expect("main name");
        let main_open = source[main_start..]
            .find('{')
            .map(|offset| main_start + offset)
            .expect("main block");
        let result_start = source.find("result").expect("result declaration");
        let result_use = source.find("return result").expect("result use") + 7;
        let other_start = source.find("other").expect("other declaration");
        let other_use = source.rfind("other").expect("other use");
        let first_call = source.find("helper();").expect("first call");
        let second_call = source.rfind("helper();").expect("second call");
        let binary = span("result + other");
        let return_span = span("return result + other;");
        let summary = Stage2JirSummary {
            functions_seen: 2,
            statements_seen: 4,
            calls_seen: 4,
            records_required: 13,
            records_emitted: 13,
            functions_lowered: 2,
            errors: 0,
            status_flags: 7,
        };
        let records = vec![
            record([1, 1, 2, 1], [0, 0, 0], 32, [0, 0]),
            record(
                [2, 1, 2, 1],
                [0, 0, 0],
                0,
                [helper_start as u64, helper_end as u64],
            ),
            record(
                [3, 1, 0, 0],
                [0, 0, 0],
                0,
                [helper_open as u64, helper_end as u64],
            ),
            record([4, 1, 2, 0], [0, 0, 0], 42, span("42")),
            record([5, 1, 2, 1], [0, 0, 0], 0, span("return 42;")),
            record(
                [2, 1, 2, 1],
                [1, 0, 0],
                0,
                [main_start as u64, source.len() as u64],
            ),
            record(
                [3, 1, 0, 0],
                [1, 0, 0],
                0,
                [main_open as u64, source.len() as u64],
            ),
            record_with_operands(
                [STAGE2_JIR_RECORD_DIRECT_CALL, 1, 2, 1],
                [1, 0, 0],
                [0, 0],
                [first_call as u64, (first_call + 8) as u64],
            ),
            record_with_operands(
                [STAGE2_JIR_RECORD_LOCAL_BINDING_METADATA, 1, 2, 1],
                [1, 0, 0],
                [result_use as u64, (result_use + "result".len()) as u64],
                [result_start as u64, (result_start + "result".len()) as u64],
            ),
            record_with_operands(
                [STAGE2_JIR_RECORD_DIRECT_CALL, 1, 2, 1],
                [1, 0, 1],
                [0, 0],
                [second_call as u64, (second_call + 8) as u64],
            ),
            record_with_operands(
                [STAGE2_JIR_RECORD_LOCAL_BINDING_METADATA, 1, 2, 1],
                [1, 0, 1],
                [other_use as u64, (other_use + "other".len()) as u64],
                [other_start as u64, (other_start + "other".len()) as u64],
            ),
            record_with_operands(
                [4, STAGE2_JIR_INSTRUCTION_ADD, 2, 0],
                [1, 0, 2],
                [0, 1],
                binary,
            ),
            record([5, 1, 2, 1], [1, 0, 2], 0, return_span),
        ];
        let module = import_stage2_jir(source, source_id_for(source), summary, &records)
            .expect("same-function direct-call result bindings should import");
        assert!(verify(&module).is_empty());
        assert_eq!(module.functions[1].blocks[0].instructions.len(), 3);
    }

