    #[test]
    fn materializes_recursive_same_module_body_call() {
        let source = "recurse(1)\nfn recurse(value: Int32) -> Int32 { return recurse(value - 1); }";
        let source_id = source_id_for(source);
        let main_ast = [
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: TYPE_KIND_INTEGER,
                flags: 2,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: 0,
                end: 7,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 2,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: 8,
                end: 9,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 5,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 1,
                aux: 1,
                start: 0,
                end: 10,
            },
        ];
        let main_call = [TypedCallBindingHeader {
            name_start: 0,
            name_end: 7,
            parameter_count: 1,
            return_type_kind: TYPE_KIND_INTEGER,
        }];
        let mut module =
            lower_typed_expression_ast(source, source_id, &main_ast, &[], &main_call, &[])
                .expect("recursive destination import should lower");

        let definition_name_start = source.find("fn recurse").expect("definition") + 3;
        let body_start = source[definition_name_start..]
            .find('{')
            .map(|offset| definition_name_start + offset)
            .expect("body start");
        let body_end = source.rfind('}').expect("body end") + 1;
        let body_call_start = source[body_start..]
            .find("recurse(value")
            .map(|offset| body_start + offset)
            .expect("recursive call");
        let value_start = body_call_start + "recurse(".len();
        let value_end = value_start + "value".len();
        let literal_start = body_call_start
            + source[body_call_start..body_end]
                .rfind('1')
                .expect("recursive decrement literal");
        let literal_end = literal_start + 1;
        let call_end = body_call_start
            + source[body_call_start..body_end]
                .find(')')
                .expect("recursive call close")
            + 1;
        let parameter_start = source[definition_name_start..body_start]
            .find("value")
            .map(|offset| definition_name_start + offset)
            .expect("parameter");
        let body_ast = [
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: TYPE_KIND_INTEGER,
                flags: 2,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: body_call_start as u64,
                end: (body_call_start + "recurse".len()) as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: value_start as u64,
                end: value_end as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 2,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: literal_start as u64,
                end: literal_end as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 7,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 1,
                right: 2,
                aux: 8,
                start: value_start as u64,
                end: literal_end as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 5,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 3,
                aux: 1,
                start: body_call_start as u64,
                end: call_end as u64,
            },
        ];
        let definition = TypedLocalFunctionDefinition {
            name_start: definition_name_start as u64,
            name_end: (definition_name_start + "recurse".len()) as u64,
            body_start: body_start as u64,
            body_end: body_end as u64,
            return_type_kind: TYPE_KIND_INTEGER,
            parameters: vec![TypedNameBindingHeader {
                name_start: parameter_start as u64,
                name_end: (parameter_start + "value".len()) as u64,
                type_kind: TYPE_KIND_INTEGER,
            }],
            ast: body_ast.to_vec(),
            call_bindings: vec![TypedCallBindingHeader {
                name_start: body_call_start as u64,
                name_end: (body_call_start + "recurse".len()) as u64,
                parameter_count: 1,
                return_type_kind: TYPE_KIND_INTEGER,
            }],
            arguments: vec![ExpressionAstArgumentHeader {
                call_node: 4,
                ordinal: 0,
                node: 3,
                start: value_start as u64,
                end: literal_end as u64,
            }],
        };
        module =
            materialize_typed_local_function_definitions(source, source_id, module, &[definition])
                .expect("recursive same-module body should materialize");
        let recursive = module
            .functions
            .iter()
            .find(|function| function.name == "recurse")
            .expect("recursive definition");
        assert_eq!(recursive.linkage, jadren_jir::Linkage::Internal);
        assert!(recursive.blocks[0].instructions.iter().any(|instruction| {
            matches!(
                instruction.kind,
                jadren_jir::InstructionKind::Call { function, .. } if function == recursive.id
            )
        }));
        assert!(verify(&module).is_empty());
    }

    #[test]
    fn lowers_typed_expression_ast_with_exact_overload_before_generic_fallback() {
        let source = "pick(1) [Integer]";
        let mut sources = SourceManager::new();
        let source_id = sources
            .add("typed-expression-overload.jdn", source)
            .expect("source ID should fit");
        let ast = [
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: 0,
                flags: 2,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: 0,
                end: 4,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 2,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: 5,
                end: 6,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 5,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 1,
                aux: 1,
                start: 0,
                end: 7,
            },
        ];
        let type_list_start = source.find("[Integer]").expect("candidate type list");
        let candidates = [
            TypedCallCandidateHeader {
                name_start: 0,
                name_end: 4,
                parameter_count: 1,
                generic_parameter_count: 0,
                return_type_kind: TYPE_KIND_INTEGER,
                parameter_type_kind: 0,
                parameter_type_start: type_list_start as u16,
                parameter_type_end: (type_list_start + "[Integer]".len()) as u16,
                generic_bound_kind: 0,
                generic_substitution_kind: 0,
            },
            TypedCallCandidateHeader {
                name_start: 0,
                name_end: 4,
                parameter_count: 1,
                generic_parameter_count: 1,
                return_type_kind: 0,
                parameter_type_kind: 0,
                parameter_type_start: 0,
                parameter_type_end: 0,
                generic_bound_kind: 1,
                generic_substitution_kind: 1,
            },
        ];
        let module = lower_typed_expression_ast_with_candidates(
            source,
            source_id,
            &ast,
            &[],
            &[],
            &candidates,
            &[],
        )
        .expect("exact overload should beat generic fallback");
        assert_eq!(module.functions.len(), 2);
        assert_eq!(
            module.functions[1].parameters[0].ty,
            jadren_jir::TypeId::new(1)
        );
        assert!(verify(&module).is_empty());
    }

