    #[test]
    fn lowers_straight_line_mutable_local_assignment_and_return() {
        let source = "let value: Int32 = 1;\nvalue = value + 2;\nreturn value;";
        let mut sources = SourceManager::new();
        let source_id = sources
            .add("typed-statements-local-mutation.jdn", source)
            .expect("source ID should fit");
        let value_spans = source
            .match_indices("value")
            .map(|(start, _)| (start as u64, (start + "value".len()) as u64))
            .collect::<Vec<_>>();
        assert_eq!(value_spans.len(), 4);
        let first_newline = source.find('\n').expect("first newline");
        let second_newline = source[first_newline + 1..]
            .find('\n')
            .map(|offset| first_newline + 1 + offset)
            .expect("second newline");
        let literal_one = source.find('1').expect("literal one");
        let literal_two = source.rfind('2').expect("literal two");
        let ast = [
            TypedExpressionAstNodeHeader {
                syntax_kind: 2,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: literal_one as u64,
                end: (literal_one + 1) as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: value_spans[2].0,
                end: value_spans[2].1,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 2,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: literal_two as u64,
                end: (literal_two + 1) as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 7,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 1,
                right: 2,
                aux: 0,
                start: value_spans[2].0,
                end: (literal_two + 1) as u64,
            },
            TypedExpressionAstNodeHeader {
                syntax_kind: 1,
                type_kind: TYPE_KIND_INTEGER,
                flags: 1,
                reserved: 0,
                left: 0,
                right: 0,
                aux: 0,
                start: value_spans[3].0,
                end: value_spans[3].1,
            },
        ];
        let statements = [
            TypedStatementHeader {
                kind: TYPED_STATEMENT_KIND_LET,
                flags: TYPED_STATEMENT_FLAG_MUTABLE,
                type_kind: TYPE_KIND_INTEGER,
                reserved: 0,
                target_start: value_spans[0].0,
                target_end: value_spans[0].1,
                expression_node: 0,
                start: 0,
                end: first_newline as u64,
            },
            TypedStatementHeader {
                kind: TYPED_STATEMENT_KIND_ASSIGN,
                flags: 0,
                type_kind: TYPE_KIND_INTEGER,
                reserved: 0,
                target_start: value_spans[1].0,
                target_end: value_spans[1].1,
                expression_node: 3,
                start: (first_newline + 1) as u64,
                end: second_newline as u64,
            },
            TypedStatementHeader {
                kind: TYPED_STATEMENT_KIND_RETURN,
                flags: 0,
                type_kind: TYPE_KIND_INTEGER,
                reserved: 0,
                target_start: 0,
                target_end: 0,
                expression_node: 4,
                start: (second_newline + 1) as u64,
                end: source.len() as u64,
            },
        ];
        let module = lower_typed_statement_sequence(source, source_id, &ast, &[], &statements)
            .expect("straight-line local mutation should lower");
        assert!(verify(&module).is_empty());
        let text = module.to_text();
        assert!(text.contains("stack_alloc"), "{text}");
        assert!(text.contains("store"), "{text}");
        assert!(text.contains("load"), "{text}");
        assert!(text.contains("add"), "{text}");
    }

