        let inner_header = TypedWhileHeader {
            condition_node: 10,
            start: inner_while_start as u64,
            end: inner_while_end as u64,
            kind: TYPED_CONTROL_FLOW_KIND_WHILE,
            type_kind: float,
            reserved: [0; 6],
        };
